window.OSTEO_RA_EMBEDDED_DETAILS={"bySourceRow":{"2":{"source":"OSTPRA1 - page 6","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE ILIUM, en antériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les mains derrière la tête, les doigts sont croisés. Le membre inférieur homolatéral à la dysfonction est posé sur le membre inférieur controlatéral.\nPRATICIEN Debout, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphalique sont sur la ceinture scapulaire homolatérale à la dysfonction ; la main caudale est posée sur l’épine ilium antéro-supérieure du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la ceinture scapulaire dans un plan perpendiculaire à la table et exercer une légère traction dans l’axe vertébral. Stabiliser la position avec la main céphalique. La main caudale empaume l’épine ilium antéro-supérieure du côté à traiter et ramène le pelvis au contact de la table. Amener l’ilium vers la postériorisation jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans la direction de la postériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":6,"sourceRow":2,"titleSource":"DYSFONCTION DE ILIUM, en antériorité à gauche"},"3":{"source":"OSTPRA1 - page 8","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (variante sujet laxe)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. Le membre inférieur du côté à traiter est en flexion de hanche et de genou à 90°. Le membre inférieur sur la table est en rectitude.\nPRATICIEN Debout, face au patient, entre les membres inférieurs du patient à la hauteur du pelvis en fente avant en direction de la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La cuisse gauche du patient est soutenue par le bassin du praticien. Les mains sont en pronation empaumant l’ischium et l’épine ilium antéro-supérieure du côté à traiter.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion de hanche pour amener l’ilium vers la postériorité jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la postériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":8,"sourceRow":3,"titleSource":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (variante sujet laxe)"},"4":{"source":"OSTPRA1 - page 10","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral, controlatéral à l’ilium en dysfonction. Le membre inférieur du côté à traiter est en triple flexion (pied à la hauteur de la fosse poplitée du genou droit).\nPRATICIEN Debout à la hauteur du pelvis, face au patient.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est sous le creux axillaire et maintient l’épaule du patient en haut et en arrière. La main caudale est en regard de l’épine ilium postéro-supérieure, les doigts sont orientés dans le sens de la crête iliaque. Placer le genou du patient entre les membres inférieurs du praticien afin de stabiliser la flexion et organiser la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le rachis dans l’axe et stabiliser la position avec la main céphalique. Rechercher la barrière motrice de la flexion vers l’extension de la hanche jusqu’à percevoir la mise en tension de l’ilium vers l’antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en direction de l’antériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":10,"sourceRow":4,"titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à gauche"},"5":{"source":"OSTPRA1 - page 12","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite (variante sujet laxe)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur à traiter par la main caudale. La paume de la main céphalique est sur l’épine ilium postéro-supérieure du côté à traiter. Les doigts sont orientés vers la crête iliaque.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur à traiter en extension, en adduction et en rotation interne jusqu’à la barrière motrice en antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique sur l’épine ilium postéro-supérieure vers l’antériorité de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":12,"sourceRow":5,"titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite (variante sujet laxe)"},"6":{"source":"OSTPRA1 - page 14","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en supériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. Le membre inférieur à traiter est en légère abduction et rotation interne.\nPRATICIEN Debout face aux pieds du patient.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la cheville, la main externe étant en supination et la main interne en pronation.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère extension, abduction et en rotation interne puis exercer une traction jusqu’à percevoir la barrière motrice une traction.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en traction dans l’axe du membre inférieur.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":14,"sourceRow":6,"titleSource":"DYSFONCTION DE L’ILIUM, en supériorité à droite"},"7":{"source":"OSTPRA1 - page 16","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. La main homolatérale à la dysfonction saisit le sommet de la têtière. Le membre inférieur en dysfonction est en flexion de hanche inférieure à 90°.\nPRATICIEN Debout en fente avant à la hauteur des jambes, la jambe gauche est dirigée vers la tête du patient. Le pied homolatéral du patient est posé sur l’épine ilium antéro-supérieure gauche du\npraticien.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la face interne du genou par sa main céphalique. Poser la main caudale sur l’articulation sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser en flexion de hanche depuis une relative position d’extension jusqu’à la barrière motrice en postériorité de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une abduction de hanche (poussée vers le plafond) contre résistance pendant 10 à 12 secondes – Au relâchement, trouver la nouvelle barrière motrice vers la flexion (quelques degrés) – À répéter 3 fois. Puis demander une adduction de hanche sur le même principe – à répéter trois fois – Même chose en flexion de hanche. Ensuite, demander au patient de pousser en extension de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, gagner en légère flexion de hanche. Répéter la manœuvre une seconde fois. Pour la troisième poussée, le praticien invite le patient à pousser en extension de telle sorte que la poussée exercée soit supérieure à la résistance du praticien, jusqu’à obtenir la rectitude du membre inférieur.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":16,"sourceRow":7,"titleSource":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (E.M.)"},"8":{"source":"OSTPRA1 - page 18","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal le membre inférieur droit est en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume et fixe l’épine ilium antéro-supérieure controlatérale à la dysfonction, la main caudale est posée sur le dessus du genou homolatéral, les doigts sont orientés vers le dehors.","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère abduction et en extension de hanche jusqu’à la barrière motrice en antériorité (contrôler au niveau de l’épine iliaque postéro-supérieure).","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en flexion de hanche contre résistance pendant 10 à 12 secondes puis gagner vers la nouvelle barrière motrice en extension de hanche – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":18,"sourceRow":8,"titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite (E.M.)"},"9":{"source":"OSTPRA1 - page 20","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite en procubitus (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur droit par la main caudale, et de la main céphalique contacter l’épine ilium postéro-supérieure et la partie postérieure de la crête iliaque. Les doigts sont orientés vers la crête iliaque.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en extension, en adduction et en légère rotation interne jusqu’à la barrière motrice en antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une flexion de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en antériorité – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":20,"sourceRow":9,"titleSource":"DYSFONCTION DE L’ILIUM, en postériorité à droite en procubitus (E.M.)"},"10":{"source":"OSTPRA1 - page 22","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en fermeture à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur à traiter est en flexion, en abduction, en rotation externe de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis, le regard est dirigé vers les pieds du patient.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer et fixer l’épine ilium antéro-supérieure controlatérale par la main céphalique et saisir la cheville homolatérale avec la main caudale. Le coude est en contact avec la face interne du genou.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion, l’abduction et la rotation externe de hanche jusqu’à la barrière motrice de la sacro-ilium droite en ouverture.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation interne et en adduction pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en ouverture en rotation externe – à répéter 3 fois. À la fin, reposer le membre inférieur en perdant les paramètres dans l’ordre : d’abord la flexion puis l’abduction et enfin la rotation externe qui est maintenue jusqu’à la fin de la technique.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":22,"sourceRow":10,"titleSource":"DYSFONCTION DE L’ILIUM, en fermeture à droite (E.M.)"},"11":{"source":"OSTPRA1 - page 24","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en ouverture à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur du patient du côté à traiter est en flexion, en adduction, en rotation interne de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis en fente avant. Les épaules sont dirigées vers la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le bord interne de l’épine ilium postéro-supérieure gauche, la main caudale empaume le pied homolatéral à la dysfonction par sa face interne. L’épaule caudale du praticien prend appui sur la face externe du genou du patient.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en flexion, en adduction et en rotation interne avec le genou fléchi jusqu’à la barrière motrice jusqu’à percevoir la fermeture de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation externe et en légère abduction contre résistance pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en fermeture en rotation interne – à répéter 3 fois – À la fin, perdre les paramètres dans l’ordre : d’abord la flexion, puis l’adduction et enfin la rotation interne qui est maintenue jusqu’à la fin de la technique.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":24,"sourceRow":11,"titleSource":"DYSFONCTION DE L’ILIUM, en ouverture à droite (E.M.)"},"12":{"source":"OSTPRA1 - page 26","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en torsion postérieure avec le pisiforme direct, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus controlatéral à la dysfonction, le membre inférieur controlatéral est en extension, l’homolatéral est en légère flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur du pelvis du patient. La main caudale est placée sur l’espace inter-épineux L5-S1.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte avec le pisiforme l’articulation sacro-ilium en dysfonction, la main céphalique est en contact avec le sillon delto-pectoral du membre supérieur sus-jacent.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter dans l’axe vertébral le rachis du patient jusqu’à solliciter l’espace inter-épineux L5-S1. Inviter le patient à croiser les doigts sur son thorax. Majorer la flexion de la hanche du genou du côté à traiter jusqu’à solliciter l’articulation sacro-ilium en dysfonction. Stabiliser la position du membre inférieur homolatéral en plaçant le pied du patient dans la fosse poplitée du membre inférieur en rectitude, le genou reste en dehors de la table.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur la base sacrée à l’aide du pisiforme et simultanément sur le genou du patient dans l’axe de la cuisse pour obtenir une ouverture de l’articulation sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":26,"sourceRow":12,"titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure avec le pisiforme direct, à gauche"},"13":{"source":"OSTPRA1 - page 28","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en flexion unilatérale sur axe horizontal, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main céphalique l’aileron inféro-latéral homolatéral à la dysfonction, la main caudale est superposée à la main céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur homolatéral en légère abduction, en rotation interne, pour ouvrir l’articulation sacro-ilium. Avant la manœuvre demander au sujet de tourner la tête du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer la barrière motrice d’extension unilatérale du sacrum en augmentant la pression de la main caudale sur la main céphalique et porter un thrust en fin d’inspiration vers le bas et l’avant du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":28,"sourceRow":13,"titleSource":"DYSFONCTION DU SACRUM, en flexion unilatérale sur axe horizontal, à gauche"},"14":{"source":"OSTPRA1 - page 30","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur axe oblique droit","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les mains derrière la tête, les doigts sont croisés et les coudes dirigés vers avant.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique fixe la position de la ceinture scapulaire par un appui sur la scapula. La main caudale placée sur l’épine ilium antéro-supérieure homolatérale ramène le pelvis au contact de la table","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Dans un premier temps, amener une concavité opposée à la dysfonction par les membres inférieurs tendus en contrôlant L5-S1 jusqu’à son engagement. Dans un deuxième temps, amener la ceinture scapulaire du patient dans un plan perpendiculaire à la table. Exercer à partir de celle-ci une traction dans l’axe vertébral et la placer légèrement en retrait par rapport au pelvis. Fixer le pelvis contre la table avec la main caudale et majorer la traction et la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration avec la main céphalique depuis la ceinture scapulaire par le levier supérieur en traction et en rotation.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":30,"sourceRow":14,"titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur axe oblique droit"},"15":{"source":"OSTPRA1 - page 32","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DU SACRUM, en torsion antérieure droite sur axe droit (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée vers le\npraticien.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Maintenir les chevilles par la main caudale, soutenir les cuisses du patient à l’aide de sa cuisse caudale, la main céphalique contrôle la sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le patient à faire une extension des membres inférieurs en maintenant de son avant-bras caudale les chevilles du patient afin de les décoller du plan de la table dans le but de glisser son avant-bras céphalique en regard du 1/3 inférieur des cuisses du patient. Effectuer une traction des genoux du patient vers le dehors de la table afin de placer le pelvis du patient à 90° sur la table, le buste restant installé sur la table en procubitus.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à lever les pieds vers le plafond pendant 10 à 12 secondes, contre résistance, en contrôlant la sacro-ilium. Au relâchement chercher une nouvelle barrière motrice par un abaissement des pieds vers le sol – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":32,"sourceRow":15,"titleSource":"DYSFONCTION DU SACRUM, en torsion antérieure droite sur axe droit (E.M.)"},"16":{"source":"OSTPRA1 - page 34","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur un axe droit (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus couché sur l’axe en dysfonction du sacrum.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique contrôle l’articulation sacro-ilium au niveau de son sillon. La main caudale est en contact avec la face externe de la cuisse sus-jacente.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral et amener en légère lordose lombaire. Tracter le membre supérieur sur la table vers le haut et l’avant du sujet de façon à déroter le sujet jusqu’à L5-S1. Demander au patient de croiser ses bras. Faire glisser le membre inférieur sur la table jusqu’à la barrière motrice en extension. Amener le membre inférieur opposé à la table en flexion et en adduction de hanche, en gardant le genou tendu jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser le genou opposé à la table vers le plafond contre résistance pendant 10 à 12 secondes. Au relâchement, chercher la nouvelle barrière motrice en abaissement du membre inférieur – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":34,"sourceRow":16,"titleSource":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur un axe droit (E.M.)"},"17":{"source":"OSTPRA1 - page 36","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en antériorité unilatérale. Manœuvre avec le pisiforme directe sur l’aileron inféro-latéral, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le sillon delto-pectoral, la main caudale contacte par le pisiforme l’aileron inféro-latéral opposé à la table.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral. Tracter le membre supérieur sur la table de façon à déroter le tronc du patient jusqu’à L5-S1. Demander une rotation de la tête vers le plafond. Le membre inférieur sur la table est amené en extension, le membre inférieur opposé à la table est en flexion, le pied fixé dans la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec le pisiforme en direction céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":36,"sourceRow":17,"titleSource":"DYSFONCTION DU SACRUM, en antériorité unilatérale. Manœuvre avec le pisiforme directe sur l’aileron inféro-latéral, à gauche"},"18":{"source":"OSTPRA1 - page 38","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en extension unilatérale sur axe horizontal, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus la tête tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter, avec le pisiforme de la main caudale, la base sacrée en dysfonction par un mouvement de « pas de vis » en direction céphalique. Renforcer la pression de la main caudale par la main céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en légère abduction et en rotation interne. Amener une pression sur la zone sous-facettaire vers la table jusqu’à la barrière motrice en flexion. Demander au patient de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers la flexion du sacrum en direction de la table.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":38,"sourceRow":18,"titleSource":"DYSFONCTION DU SACRUM, en extension unilatérale sur axe horizontal, à droite"},"19":{"source":"OSTPRA1 - page 40","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en supériorité à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. Le membre inférieur homolatéral à la dysfonction est en dehors de la table et est maintenu entre les jambes du\npraticien.\nPRATICIEN Debout à la hauteur du pelvis les épaules sont dirigées vers la tête du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’épine iliaque antéro-supérieure controlatérale. La main homolatérale à la dysfonction enserre la face antérieure et distale de la cuisse.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer l’extension de la hanche jusqu’à la barrière motrice de la symphyse pubienne.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fléchir la hanche en lui demandant de pousser le genou vers le plafond pendant 10 à 12 secondes et s’y opposer – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":40,"sourceRow":19,"titleSource":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en supériorité à droite (E.M.)"},"20":{"source":"OSTPRA1 - page 42","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en infériorité à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le membre inférieur homolatéral à la dysfonction est en flexion.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique saisit le bord opposé de la table. Le creux axillaire homolatéral est en appui sur le genou du sujet, homolatéral à la dysfonction. La main caudale, poing fermé, forme un coin sous la tubérosité ischiatique du sujet du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en flexion sur le thorax. Majorer la flexion de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une extension de hanche et s’y opposer. Rechercher ensuite la nouvelle barrière motrice vers la flexion en s’aidant du coin constitué par la main caudale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":42,"sourceRow":20,"titleSource":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en infériorité à gauche (E.M.)"},"21":{"source":"OSTPRA1 - page 44","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION COMBINÉE DE LA SYMPHYSE PUBIENNE, en supériorité et infériorité (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les genoux sont fléchis les pieds sont posés sur la table.\nPRATICIEN Assis sur les pieds du sujet, les épaules sont dirigées vers la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Dans un premier temps, empaumer la face externe des genoux joints. Puis, dans un deuxième temps, placer les avant-bras entre les genoux.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir les deux genoux accolés.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une abduction des hanches et s’y opposer. Relâcher soudainement la pression sur les genoux et bloquer l’abduction des hanches par les coudes – À répéter 3 fois. Puis, intercaler l’avant-bras entre les genoux, demander une adduction, libérer vivement l’avant-bras et bloquer les deux genoux par le coude.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":44,"sourceRow":21,"titleSource":"DYSFONCTION COMBINÉE DE LA SYMPHYSE PUBIENNE, en supériorité et infériorité (E.M.)"},"22":{"source":"OSTPRA1 - page 46","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en NSR à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale est en contact avec l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse gauche. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en extension. Le membre inférieur sous-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous-jacent jusqu’à solliciter l’espace inter-épineux concerné. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Porter le thrust sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":46,"sourceRow":22,"titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en NSR à droite"},"23":{"source":"OSTPRA1 - page 48","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en ERS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou sous-jacent en extension et maintenir une légère flexion de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent en rotation du tronc jusqu’à solliciter l’espace inter-épineux concerné. Ajouter une composante de flexion du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":48,"sourceRow":23,"titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en ERS à droite"},"24":{"source":"OSTPRA1 - page 50","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en FRS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus‑jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sous‑jacent en rectitude avec une extension de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent jusqu’à solliciter l’espace inter‑épineux concerné. Ajouter une composante d’extension du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens d’une rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire,","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":50,"sourceRow":24,"titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en FRS à droite"},"25":{"source":"OSTPRA1 - page 52","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, assis, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table. Le patient met sa main opposée à la dysfonction sur son épaule homolatérale à la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN La table est en position basse, le\npraticien est assis à califourchon dans le dos du sujet légèrement du coté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien contacte l’épaule opposée du patient. Le pisiforme de la main caudale contacte la transverse de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en légère flexion, en rotation et en inclinaison droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation opposée à la dysfonction sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":52,"sourceRow":25,"titleSource":"DYSFONCTION FACETTAIRE DES LOMBAIRES, assis, à gauche"},"26":{"source":"OSTPRA1 - page 54","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"DYSFONCTION DES LOMBAIRES, en NSR à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposée à la dysfonction. Les genoux et les hanches sont fléchis à 90°. La main du membre supérieur sus-jacent attrape le bord supérieur de la table.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique la vertèbre en dysfonction. La main caudale soutient les chevilles.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Lever vers le plafond les chevilles de façon à corriger la latéroflexion lombaire jusqu’au niveau concerné.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’abaisser les pieds vers le sol et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par l’élévation des pieds – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":54,"sourceRow":26,"titleSource":"DYSFONCTION DES LOMBAIRES, en NSR à gauche (E.M.)"},"27":{"source":"OSTPRA1 - page 56","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"DYSFONCTION DES LOMBAIRES, en ERS à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus. La tête est tournée du côté de la dysfonction. Les hanches et genoux sont amenés par le\npraticien en flexion à 90° en dehors de la table. Le bras opposé à la dysfonction est le long de la table. Le bras homolatéral est pendant en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale soutient les chevilles.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener en flexion les hanches et s’arrêter juste avant d’entraîner la vertèbre en dysfonction. Demander au sujet de pousser le membre supérieur en dehors de la table vers le sol. Amener les pieds vers le sol et s’arrêter juste avant d’entraîner la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de lever les pieds vers le plafond et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par abaissement des pieds et flexion des hanches. Demander au sujet de glisser le membre supérieur posé sur la table vers ses pieds, et le membre supérieur en dehors de la table vers le sol – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":56,"sourceRow":27,"titleSource":"DYSFONCTION DES LOMBAIRES, en ERS à gauche (E.M.)"},"28":{"source":"OSTPRA1 - page 58","category":"Lombaire – lombaire","method":"Mobilisation","intro":"DYSFONCTION DES LOMBAIRES, en FRS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté de la dysfonction. La tête est tournée vers le haut. Le membre inférieur sous‑jacent est amené en extension. Le membre inférieur sus‑jacent est en extension de hanche, genoux à 90°.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale saisit la jambe sus-jacente du patient.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le membre supérieur sous-jacent pour engendrer une rotation du tronc. Demander au sujet de maintenir cette position en saisissant le bord opposé de la table avec sa main. Amener la hanche sus-jacente en rotation interne, en extension et en abduction. S’arrêter juste avant d’entraîner dans ce mouvement la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à faire une flexion de hanche gauche et s’y opposer, pendant 10 à 12 secondes. Puis, au relâchement rechercher de la nouvelle barrière motrice par une extension de la hanche – À répéter trois fois. Puis, inviter le sujet à faire une adduction de la hanche et s’y opposer. Au relâchement, chercher la nouvelle barrière motrice par une abduction de la hanche – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":58,"sourceRow":28,"titleSource":"DYSFONCTION DES LOMBAIRES, en FRS à droite"},"29":{"source":"OSTPRA1 - page 60","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les membres supérieurs sont croisées sur le thorax. La main gauche est sur l’épaule droite et la main droite est sur l’épaule gauche. Les coudes sont superposés, le coude droit est au dessus de l’autre.\nPRATICIEN Debout à la hauteur du pelvis, les épaules sont orientées vers la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique soutient le thorax et la tête. La main caudale par un double appui (éminence thénar et 2 e phalanges des 4 derniers doigts) est en regard des apophyses transverses de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le sujet en flexion du tronc puis amener le sujet au contact de la main du praticien en allongeant le patient sur la table.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice. Le thrust sera porté au passage de la vertèbre en dysfonction sur le double contact de la main applicatrice du praticien sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":60,"sourceRow":29,"titleSource":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique en double appui"},"30":{"source":"OSTPRA1 - page 62","category":"Lombaire – lombaire","method":"Thrust","intro":"NOTE : VERIFIER LE CÔTÉ DE LA POSTÉRIORITÉ\nDYSFONCTION DE LA CHARNIÈRE D12/L1, technique indirecte à droite en « Lumbar Roll »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus droit.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"L’avant-bras caudal contacte la face postéro-externe de la fesse sus-jacente du patient. La main caudale contacte la zone en dysfonction. L’avant-bras céphalique contacte le sillon delto‑pectoral sus-jacent du patient, la main céphalique est sur la zone en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sus-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener le levier supérieur en rotation jusqu’à la zone en dysfonction. Amener le levier inférieur en rotation opposée. Fixer les leviers en amenant le sujet sous le praticien. Porter le thrust en exagération du levier inférieur sous le levier supérieur sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":62,"sourceRow":30,"titleSource":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique indirecte à droite en « Lumbar Roll »"},"31":{"source":"OSTPRA1 - page 64","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION DE L3, technique semi-directe à gauche en « Lumbar Roll »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la postériorité de la vertèbre est positionnée vers le haut.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"L’index de la main caudale contacte la transverse de la vertèbre en dysfonction. La main céphalique maintient les poignets du patient.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sous-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sus-jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en exagérant le levier de rotation.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":64,"sourceRow":31,"titleSource":"DYSFONCTION DE L3, technique semi-directe à gauche en « Lumbar Roll »"},"32":{"source":"OSTPRA1 - page 66","category":"Lombaire – lombaire","method":"Lift","intro":"CHARNIÈRE D12/L1, technique en « Lift », postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table, les pieds sont posés au sol. La face dorsale de la métacarpo-phalangienne de l’index de la main du côté de la dysfonction contacte la transverse postérieure. La main est ouverte, le pouce est dirigé vers le haut. L’autre main est superposée de la même manière.\nPRATICIEN Assis à califourchon derrière du sujet, les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Passer le membre supérieur sous le bras du sujet pour fixer le thorax et l’abdomen. La main opposée à la dysfonction contacte l’arrière de la tête pour contrôler la flexion du tronc. Le contacteur représenter par le sternum du praticien est au contact sur les mains du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener de thorax en flexion jusqu’au niveau de la dysfonction. Fixer la position des leviers par le contact sternal. Amener dans un mouvement en virgule le thorax en compression vers le praticien puis le tracter vers le haut dans un mouvement de décoaptation.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans un mouvement de traction verticale (lift) lors de l’expiration.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":66,"sourceRow":32,"titleSource":"CHARNIÈRE D12/L1, technique en « Lift », postériorité à gauche"},"33":{"source":"OSTPRA2 - page 6","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire des dorsaleS, en flexion, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet vers soi de façon à localiser par la main caudale la vertèbre en dysfonction. Placer les transverses des vertèbres en dysfonction entre son éminence thénar et ses doigts fléchis, le pouce est dans l’axe vertébral en direction de la tête du sujet. Puis maintenir par la main céphalique et le thorax les coudes et le thorax du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’inspiration vers la table.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":6,"sourceRow":33,"titleSource":"Dysfonction facettaire des dorsaleS, en flexion, technique en double appui"},"34":{"source":"OSTPRA2 - page 8","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire des dorsales, en extension, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la vertèbre en dysfonction. Puis, contacter les transverses des vertèbres en dysfonction par l’éminence thénar et les phalangines de la main caudale, le pouce est dans l’axe vertébral vers la tête du sujet. La main et l’avant-bras céphalique soulèvent et soutiennent la tête et le rachis dorsal haut. Le sternum du praticien contacte les coudes du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table dans un mouvement de virgule vers la tête du sujet, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":8,"sourceRow":34,"titleSource":"Dysfonction facettaire des dorsales, en extension, technique en double appui"},"35":{"source":"OSTPRA2 - page 10","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire DES dorsaleS, technique en simple appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude du côté du\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter la transverse en postériorité de la vertèbre en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral en direction de la tête, la main reste à plat. Verrouiller les coudes du sujet par un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration vers le plan de la table.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":10,"sourceRow":35,"titleSource":"Dysfonction facettaire DES dorsaleS, technique en simple appui"},"36":{"source":"OSTPRA2 - page 12","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire DES dorsaleS, avec les pisiformes croisés, postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité de la vertèbre en dysfonction. Contacter par le pisiforme de la main céphalique l’apophyse transverse de la vertèbre sous-jacente en créant ainsi un contre appui.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en fin d’expiration, en direction de la tête du sujet et du sol, dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":12,"sourceRow":36,"titleSource":"Dysfonction facettaire DES dorsaleS, avec les pisiformes croisés, postériorité à droite"},"37":{"source":"OSTPRA2 - page 14","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire Des dorsales, technique en pisiforme simple, postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité. Renforcer ce contact en plaçant le pisiforme de la main céphalique au niveau de la tabatière anatomique de la main applicatrice.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale, en fin d’expiration, en direction de la tête du sujet et du sol dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":14,"sourceRow":37,"titleSource":"Dysfonction facettaire Des dorsales, technique en pisiforme simple, postériorité à droite"},"38":{"source":"OSTPRA2 - page 16","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire(s) des dorsale(s) (D9 à D12), assis, technique en pisiforme simple, postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, la main opposée à la dysfonction est posée sur l’épaule du côté de la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN Assis à califourchon sur la table derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’épaule et la main du sujet du côté de la dysfonction. Le pisiforme de la main caudale contacte la postériorité de la vertèbre en dysfonction. Les doigts sont posés sur le grill costal.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener, par la main céphalique, le levier supérieur thoracique en rotation et en inclinaison opposées à la dysfonction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par le pisiforme de la main caudale en exagérant le levier de rotation, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":16,"sourceRow":38,"titleSource":"Dysfonction facettaire(s) des dorsale(s) (D9 à D12), assis, technique en pisiforme simple, postériorité à gauche"},"39":{"source":"OSTPRA2 - page 18","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dysfonction facettaire DES dorsales, technique en « double Nelson »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Glisser les mains sous les bras du sujet pour se saisir des poignets. Demander au sujet de croiser les doigts derrière la nuque et accompagne le mouvement.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de serrer les coudes jusqu’à ressentir la mise en tension de la zone en dysfonction. Amener le rachis cervical en flexion jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift) en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":18,"sourceRow":39,"titleSource":"Dysfonction facettaire DES dorsales, technique en « double Nelson »"},"40":{"source":"OSTPRA2 - page 20","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dysfonction(s) des vertèbre(s) dorsale(s), technique en « lift » (composantes multiples) assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, les bras sont croisés sur le thorax les coudes sont superposés. Le rachis cervical est en flexion.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer avec les deux mains le coude inférieur du sujet. Puis placer son sternum en contact direct avec la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la zone en dysfonction contre le sternum du praticien par un mouvement de virgule, vers l’arrière et vers le haut, jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift), en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":20,"sourceRow":40,"titleSource":"Dysfonction(s) des vertèbre(s) dorsale(s), technique en « lift » (composantes multiples) assis"},"41":{"source":"OSTPRA2 - page 22","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D8-D12), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds posés au sol, les bras sont croisés sur le thorax.\nPRATICIEN Assis derrière le sujet du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer par la main céphalique l’épaule du sujet du côté de la dysfonction. Contacter par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de s’incliner du côté de la vertèbre en dysfonction. Puis, amener le thorax en rotation opposée jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une inclinaison du tronc dans le sens opposé à la dysfonction, et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison du côté de la dysfonction et en rotation opposée – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":22,"sourceRow":41,"titleSource":"Dysfonction d’une vertèbre dorsale (D8-D12), en NSgRd (E.M.)"},"42":{"source":"OSTPRA2 - page 24","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D7-D12) en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière la tête.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe par l’anneau formé par le membre supérieur controlatéral à la dysfonction pour rejoindre l’omoplate du côté de la dysfonction. Contacter, par la main caudale, l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis dorsal en latéroflexion, en rotation du côté opposé à la dysfonction et y associer une translation controlatérale jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe à l’apex de la courbure.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en latéroflexion, en rotation et en flexion dans le sens opposé à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":24,"sourceRow":42,"titleSource":"Dysfonction d’une vertèbre dorsale (D7-D12) en ERdSd (E.M.)"},"43":{"source":"OSTPRA2 - page 26","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"NOTE : VERIfIER pRISE bOuT DES DOIgTS\nDysfonction d’une vertèbre dorsale (D8-D12), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. La main du côté de la dysfonction est posée sur l’épaule opposée, l’autre main est posée sur la table.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le deltoïde du sujet du côté de la dysfonction. Placer la main caudale sur l’espace inter-épineux sous-jacent à la vertèbre dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à effectuer une extension, une inclinaison par un abaissement de l’épaule et une rotation du côté opposé à la dysfonction ainsi qu’une translation controlatérale du tronc jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe alors à l’apex de la courbure.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison et en rotation – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":26,"sourceRow":43,"titleSource":"Dysfonction d’une vertèbre dorsale (D8-D12), en FRdSd (E.M.)"},"44":{"source":"OSTPRA2 - page 28","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D4-D8), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière le cou.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe sous le coude proximal du sujet puis par l’anneau formé par le membre supérieur distal pour venir se poser sur l’épaule du côté de la dysfonction. La main caudale contacte l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en inclinaison du côté de la dysfonction par l’abaissement de l’épaule homolatérale et une élévation de l’épaule controlatérale. Amener une translation du côté opposé à la dysfonction du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Tracter par la main céphalique l’épaule homolatérale à la dysfonction vers l’avant jusqu’à percevoir la rotation de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale à la dysfonction et en rotation controlatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":28,"sourceRow":44,"titleSource":"Dysfonction d’une vertèbre dorsale (D4-D8), en NSgRd (E.M.)"},"45":{"source":"OSTPRA2 - page 30","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D4-D8), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté opposé à la postériorité de la vertèbre en dysfonction. Amener le membre supérieur homolatéral à la dysfonction le long de la tête, le coude fléchi. Le membre supérieur controlatéral reste le long du corps. Croiser la cheville homolatérale à la dysfonction sur l’autre cheville.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité, les doigts sont en direction de la tête du sujet. Le pisiforme de la main céphalique contacte l’apophyse transverse controlatérale de la même vertèbre. Les doigts sont dirigés vers les pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Augmenter la pression des deux mains de façon à majorer la rotation de l’apophyse transverse en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une respiration profonde et profiter de la phase expiratoire pour exercer, par la main caudale, une pression sur l’apophyse transverse en postériorité en direction de la tête du sujet et du sol dans le plan des facettes articulaires. Exercer simultanément une pression, par la main céphalique, sur l’apophyse transverse opposée en direction des pieds du sujet. Au relâchement rechercher la nouvelle barrière motrice en exagérant les leviers d’inclinaison – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":30,"sourceRow":45,"titleSource":"Dysfonction d’une vertèbre dorsale (D4-D8), en FRdSd (E.M.)"},"46":{"source":"OSTPRA2 - page 32","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D4), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied opposé à la dysfonction sur la table. Glisser le genou sous l’épaule opposée à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Poser la main controlatérale à la dysfonction sur le sommet de la tête du sujet avec l’avant-bras au contact de la face latérale de la tête. Contrôler par la main homolatérale à la dysfonction l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale et cervicale en inclinaison homolatérale à la dysfonction. Puis ajouter une translation controlatérale du tronc en écartant le genou du praticien de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Enfin, amener en rotation controlatérale la tête du sujet jusqu’à percevoir la rotation de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison de la tête controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale et rotation controlatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":32,"sourceRow":46,"titleSource":"Dysfonction d’une vertèbre dorsale (D1-D4), en NSgRd (E.M.)"},"47":{"source":"OSTPRA2 - page 34","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D6), en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Enserrer la tête du sujet entre le bras et l’avant-bras céphalique, la main est au contact de l’occiput. Contacter par les doigts de la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en flexion en y associant une translation postérieure du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Amener la tête du sujet en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et légèrement en rotation homolatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et flexion – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":34,"sourceRow":47,"titleSource":"Dysfonction d’une vertèbre dorsale (D1-D6), en ERdSd (E.M.)"},"48":{"source":"OSTPRA2 - page 36","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D3), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique repose sur le front du sujet, l’avant-bras contacte la face latérale de la tête. Contrôler par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser sur la main et l’avant-bras du praticien et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et extension – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":36,"sourceRow":48,"titleSource":"Dysfonction d’une vertèbre dorsale (D1-D3), en FRdSd (E.M.)"},"49":{"source":"OSTPRA2 - page 38","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire de la 1re côte, en élévation. Technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied controlatéral à la dysfonction sur la table et glisser le genou sous l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer le bord radial de l’articulation inter-phalangienne proximale de l’index de la main homolatérale à la dysfonction sur la face supérieure de la première côte, en avant du trapèze. La main controlatérale empaume la région fronto-pariétale. Le coude vient au contact de la partie antérieure de l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison homolatérale à la dysfonction et en rotation controlatérale jusqu’à la perception du relâchement fascial de la zone. Exercer sur la côte une pression progressive vers le bas et en direction de la hanche controlatérale du sujet jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers le bas et la hanche opposée en fin de mouvement et d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":38,"sourceRow":49,"titleSource":"Dysfonction costo-transversaire de la 1re côte, en élévation. Technique structurelle"},"50":{"source":"OSTPRA2 - page 40","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire antéro-médiane, technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation controlatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dehors en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":40,"sourceRow":50,"titleSource":"Dysfonction costo-transversaire antéro-médiane, technique structurelle"},"51":{"source":"OSTPRA2 - page 42","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire postéro latérale, technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dedans en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":42,"sourceRow":51,"titleSource":"Dysfonction costo-transversaire postéro latérale, technique structurelle"},"52":{"source":"OSTPRA2 - page 44","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire, composantes multiples, technique structurelle, assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon, la main controlatérale est posée sur l’épaule homolatérale à la dysfonction et la main homolatérale repose sur le grill costal controlatéral.\nPRATICIEN Assis à califourchon derrière le sujet légèrement décalé sur le côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien empaume le deltoïde homolatéral à la dysfonction. Contacter par le pisiforme de la main caudale l’articulation costo-transversaire en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en extension.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale vers l’avant, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":44,"sourceRow":52,"titleSource":"Dysfonction costo-transversaire, composantes multiples, technique structurelle, assis"},"53":{"source":"OSTPRA2 - page 46","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dysfonction costo-transversaire antéro-médiane (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table. Amener la main homolatérale à la dysfonction sur l’épaule opposée\nPRATICIEN Debout du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction. Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dedans de l’angle costal postérieur.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation controlatérale à la dysfonction jusqu’à la barrière motrice de la zone.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tirer son coude vers le bas, vers l’arrière et en dehors et s’y opposer. Simultanément avec le pouce le praticien repousse l’angle costal postérieur en dehors. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation controlatérale la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":46,"sourceRow":53,"titleSource":"Dysfonction costo-transversaire antéro-médiane (E.M.)"},"54":{"source":"OSTPRA2 - page 48","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dysfonction costo-transversaire postéro-latérale (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. Amener la main homolatérale à la dysfonction sur l’épaule opposée.\nPRATICIEN Debout du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dehors de l’angle costal postérieur.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation homolatérale à la dysfonction jusqu’à la barrière motrice de la zone.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’amener son coude homolatéral à la dysfonction en dehors et s’y opposer. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":48,"sourceRow":54,"titleSource":"Dysfonction costo-transversaire postéro-latérale (E.M.)"},"55":{"source":"OSTPRA2 - page 50","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique crochète l’angle postérieur de la première côte. La tête du sujet repose sur l’avant-bras du praticien. Le pouce de la main caudale est en contact avec la partie antérieure de la première côte, sous la clavicule.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à percevoir la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, amener la partie antérieure de la première côte en direction des pieds et tracter simultanément sa partie postérieure vers la tête. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":50,"sourceRow":55,"titleSource":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan sagittal (E.M.)"},"56":{"source":"OSTPRA2 - page 52","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main caudale vient au contact de la partie supérieure de la première côte. La main céphalique soutient l’occiput du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, pousser la première côte en direction des pieds. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":52,"sourceRow":56,"titleSource":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan frontal (E.M.)"},"57":{"source":"OSTPRA2 - page 54","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (1re à 6e côte), en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et sur le thorax afin de la guider et de la stabiliser. Le pouce de la main antérieure contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception, par sa main antérieure, d’un relâchement fascial sus-jacent du niveau à normaliser. Par la main postérieure, crocheter simultanément la côte en regard du même niveau","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une expiration exagérer les leviers de flexion du rachis. Au relâchement, rechercher une nouvelle barrière motrice – À répéter trois fois","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":54,"sourceRow":57,"titleSource":"Dysfonction respiratoire des (1re à 6e côte), en élévation dans le plan sagittal (E.M.)"},"58":{"source":"OSTPRA2 - page 56","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (1re-6e côte), en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphaliques soutiennent et guident le rachis dorsal et cervical, la main caudale par sa première commissure contacte la côte en dysfonction en regard de la ligne médio-axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion et une inclinaison du côté homolatéral à la dysfonction du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent de la côte en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":56,"sourceRow":58,"titleSource":"Dysfonction respiratoire des (1re-6e côte), en élévation dans le plan frontal (E.M.)"},"59":{"source":"OSTPRA2 - page 58","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La main caudale contacte par la première commissure la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser. Crocheter simultanément et postérieurement la côte en regard du même niveau.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en flexion et inclinaison homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":58,"sourceRow":59,"titleSource":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan sagittal (E.M.)"},"60":{"source":"OSTPRA2 - page 60","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La première commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en regard de la ligne médio-axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical et dorsal en flexion et en inclinaison homolatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":60,"sourceRow":60,"titleSource":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan frontal (E.M.)"},"61":{"source":"OSTPRA2 - page 62","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (1re-2e côte), en abaissement dans le plan sagittal (E.M.). Technique dite en « bras de pompe »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front. Le\npraticien le maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":62,"sourceRow":61,"titleSource":"Dysfonction des (1re-2e côte), en abaissement dans le plan sagittal (E.M.). Technique dite en « bras de pompe »"},"62":{"source":"OSTPRA2 - page 64","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (1re-2e côte), en abaissement dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front que le\npraticien maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":64,"sourceRow":62,"titleSource":"Dysfonction des (1re-2e côte), en abaissement dans le plan frontal (E.M.)"},"63":{"source":"OSTPRA2 - page 66","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (3e-10e côte), en abaissement, dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front coude vers le haut.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter de la main caudale l’angle postérieur de la 1 re ou de la 2 e côte. La main céphalique du praticien contacte le coude du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser son coude en direction de ses pieds et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":66,"sourceRow":63,"titleSource":"Dysfonction des (3e-10e côte), en abaissement, dans le plan sagittal (E.M.)"},"64":{"source":"OSTPRA2 - page 68","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (3e-10e côte), en abaissement, dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le coude du sujet homolatéral à la dysfonction en passant par le dessus de sa tête. Sa main repose sur l’avant-bras du praticien. La 1 re commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener une inclinaison thoracique controlatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de ramener latéralement le coude en direction du tronc et s’y opposer. Lors du relâchement, majorer l’inclinaison du tronc et la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":68,"sourceRow":64,"titleSource":"Dysfonction des (3e-10e côte), en abaissement, dans le plan frontal (E.M.)"},"65":{"source":"OSTPRA2 - page 70","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (11e-12e côte), en élévation (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée, le bras homolatéral est placé le long du corps.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Sur l’expiration, demander au sujet de pousser le bassin contre la table, s’y opposer. Simultanément, le patient glisse le bras en direction de ses pieds. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en abaissant la côte – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":70,"sourceRow":65,"titleSource":"Dysfonction des (11e-12e côte), en élévation (E.M.)"},"66":{"source":"OSTPRA2 - page 72","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (11e-12e côte), en abaissement (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée. Le membre supérieur homolatéral à la dysfonction est posé à la hauteur de la tête.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"la main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction de la tête.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Fixer la côte à normaliser et demander au sujet d’amener son bassin vers le haut et en direction de la table. S’y opposer pendant 10 à 12 secondes. Lors de la phase d’expiration, étirer le carré des lombes en tractant le bassin en haut et en arrière – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":72,"sourceRow":66,"titleSource":"Dysfonction des (11e-12e côte), en abaissement (E.M.)"},"67":{"source":"OSTPRA2 - page 74","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), position assise, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET assis en bord de table.\nPRATICIEN Debout derrière le sujet, poser le pied droit sur la table, le genou est sous le creux axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la pulpe du pouce gauche la face latérale droite de l’épineuse de la vertèbre en dysfonction. Les autres doigts sont posés sur la clavicule. Le coude est placé dans un axe horizontal. La main droite empaume la face latérale de la tête, le coude reposant sur l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Écarter légèrement le genou droit de façon à induire une translation droite du niveau à normaliser. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement dans l’axe horizontal.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":74,"sourceRow":67,"titleSource":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), position assise, à droite"},"68":{"source":"OSTPRA2 - page 76","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), en procubitus à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, le menton est posé sur la table.\nPRATICIEN Debout, à la hauteur du thorax du sujet, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce gauche contacte la face latérale gauche de l’épineuse. Les autres doigts sont posés sur la clavicule. L’avant bras est horizontal dans la direction de l’épaule opposée au sujet. La main droite est posée en conque sur la face latérale droite de la tête (ne pas écraser l’oreille).","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement en direction de l’épaule droite du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":76,"sourceRow":68,"titleSource":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), en procubitus à droite"},"69":{"source":"OSTPRA2 - page 78","category":"Dorsales et thorax – cervico-dorsales","method":"Mobilisation","intro":"Dysfonction de la région cervico-dorsale (C7-D2) composantes multiples à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En latérocubitus, les membres inférieurs sont fléchis et les mains placées entre les genoux. L’épaule du côté de la table est dégagée vers l’avant et en direction des pieds.\nPRATICIEN Debout en fente avant gauche à la hauteur de la ceinture scapulaire.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soulever la tête du sujet et la maintenir fermement à l’aide du bras et de l’avant-bras gauche, la main recouvre l’occiput. Poser le thorax sur l’épaule gauche du sujet. Appliquer la pulpe du pouce droit sur la face latérale du processus épineux de la vertèbre sous-jacente à la dysfonction, les doigts libres étant étalés sur la région dorsale.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en inclinaison gauche, en translation latérale droite et en rotation droite. Associer ces composantes de mouvement avec celle de flexion, extension ou compression, à la recherche de la convergence de mise en tension de la zone en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant les résultantes de tension, le praticien, par l’intermédiaire de sa main droite (placée sur l’épineuse) majore la rotation gauche par un mouvement de haute vélocité, basse amplitude (HBVA).","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":78,"sourceRow":69,"titleSource":"Dysfonction de la région cervico-dorsale (C7-D2) composantes multiples à droite"},"70":{"source":"OSTPRA2 - page 80","category":"Cervicales – occiput","method":"Thrust","intro":"Dysfonction de l’occiput, en postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le menton par la main controlatérale, l’avant-bras se positionne légèrement en avant de l’oreille du sujet. Contacter l’écaille occipitale par le bord radial de la métacarpo-phalangienne de l’index de la main homolatérale, en arrière de la mastoïde. L’avant-bras est horizontal dans l’axe des yeux du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale à la dysfonction de la tête. Placer l’occiput en légère extension. Exercer une légère pression par son sternum sur la tête du sujet et une pression de l’index sur l’occiput jusqu’à la barrière motrice dans le plan des facettes articulaires de l’occiput.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction des yeux du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":80,"sourceRow":70,"titleSource":"Dysfonction de l’occiput, en postériorité à droite"},"71":{"source":"OSTPRA2 - page 82","category":"Cervicales – occiput","method":"Thrust","intro":"Dysfonction de l’Occiput, en translation à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90° du côté opposé à la dysfonction.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente, les doigts en direction des pieds, empaument la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index et le majeur sont de part et d’autre du muscle sterno-cléido-mastoïdien. La main sus-jacente applicatrice est posée sur la face latérale de la tête. Le talon de la main est en contact avec la branche horizontale du maxillaire inférieur.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener simultanément la tête en inclinaison homolatérale à la dysfonction et en translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de la main sus-jacente applicatrice en majorant l’inclinaison homolatérale. La main sous-jacente accompagnant le mouvement.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":82,"sourceRow":71,"titleSource":"Dysfonction de l’Occiput, en translation à droite"},"72":{"source":"OSTPRA2 - page 84","category":"Cervicales – OAA","method":"Thrust","intro":"Dysfonction articulaire globale Occiput Atlas Axis (OAA)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90°.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente empaume la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index de la main sus-jacente est sur la tempe. Le majeur sous le malaire, les deux autres doigts sous le menton, le pouce contacte l’écaille occipitale. Les deux avant-bras sont dans le prolongement du sterno-cléido-mastoïdien, le coude sus-jacent au dessus du sternum.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tout en maintenant les avant-bras dans l’axe vertébral, effectuer un mouvement hélicoïdal en légère traction et en rotation de la tête jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le mouvement hélicoïdal. Répéter la manœuvre en rotation opposée.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":84,"sourceRow":72,"titleSource":"Dysfonction articulaire globale Occiput Atlas Axis (OAA)"},"73":{"source":"OSTPRA2 - page 86","category":"Cervicales – atlas","method":"Thrust","intro":"Dysfonction de l’Atlas, en postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index. La main et l’avant-bras sont en direction des yeux et parallèles au plan de la table.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale de la tête. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":86,"sourceRow":73,"titleSource":"Dysfonction de l’Atlas, en postériorité à droite"},"74":{"source":"OSTPRA2 - page 88","category":"Cervicales – atlas","method":"Thrust","intro":"Dysfonction de l’Atlas, en translation droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index, la main et l’avant-bras sont en direction des yeux.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale à la dysfonction. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du sol.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":88,"sourceRow":74,"titleSource":"Dysfonction de l’Atlas, en translation droite"},"75":{"source":"OSTPRA2 - page 90","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite (variante)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume la face latérale du visage du sujet. La main homolatérale contacte, par la métacarpo-phalangienne de l’index, la partie postéro-latérale de l’apophyse transverse de la vertèbre en dysfonction. Le pouce est posé sur la branche horizontale de la mandibule.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de rotation controlatérale.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":90,"sourceRow":75,"titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite (variante)"},"76":{"source":"OSTPRA2 - page 92","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite; prise mentonnière","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Veiller à ce que la main et l’avant-bras droits soient dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale et l’inclinaison homolatérale de la tête. Ajouter une légère extension. Exercer une pression indexielle sur l’apophyse articulaire jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en rotation controlatérale dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":92,"sourceRow":76,"titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite; prise mentonnière"},"77":{"source":"OSTPRA2 - page 94","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en translation droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Le pouce est posé sur la branche horizontale de la mandibule.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en légère inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de translation.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":94,"sourceRow":77,"titleSource":"Dysfonction facettaire des cervicales (C2-C6), en translation droite"},"78":{"source":"OSTPRA2 - page 96","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à gauche; sujet assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout, devant le sujet, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main homolatérale applicatrice contacte l’apophyse articulaire de la vertèbre en dysfonction par la pulpe du médius. La main controlatérale est sur la face latérale de la tête.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en légère extension. Exercer par le médius une pression sur l’apophyse articulaire jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":96,"sourceRow":78,"titleSource":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à gauche; sujet assis"},"79":{"source":"OSTPRA2 - page 98","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Dysfonction des cervicales (C2-C7), en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume l’écaille de l’occiput controlatéral. La main homolatérale applicatrice contacte par la métacarpo-phalangienne de l’index l’apophyse transverse de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner la tête vers la main applicatrice et vers l’arrière. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une inclinaison homolatérale, une translation, une rotation controlatérale et une flexion – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":98,"sourceRow":79,"titleSource":"Dysfonction des cervicales (C2-C7), en ERdSd (E.M.)"},"80":{"source":"OSTPRA2 - page 100","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Dysfonction des cervicale (C2-C7), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et vers son épaule homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une extension, une inclinaison homolatérale, une translation et une rotation controlatérale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":100,"sourceRow":80,"titleSource":"Dysfonction des cervicale (C2-C7), en FRdSd (E.M.)"},"81":{"source":"OSTPRA2 - page 102","category":"Cervicales – Atlas – axis","method":"Énergie musculaire","intro":"Dysfonction Atloïdo-axoïdienne, en rotation droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’écaille de l’occiput. La main homolatérale contacte la face latérale du visage du sujet, en avant de l’oreille.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en rotation et en légère translation controlatérales à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner les yeux avec insistance en direction de la dysfonction pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation et la translation controlatérales – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":102,"sourceRow":81,"titleSource":"Dysfonction Atloïdo-axoïdienne, en rotation droite (E.M.)"},"82":{"source":"OSTPRA2 - page 104","category":"Cervicales – occiput atlas","method":"Énergie musculaire","intro":"Dysfonction Occipito-atloïdienne, en ESgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton vers le plafond et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale, en rotation controlatérale et en flexion – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":104,"sourceRow":82,"titleSource":"Dysfonction Occipito-atloïdienne, en ESgRd (E.M.)"},"83":{"source":"OSTPRA2 - page 106","category":"Cervicales – occiput – atlas","method":"Énergie musculaire","intro":"Dysfonction Occipito-atloïdienne, en FSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton en direction de ses pieds et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison homolatérale et en rotation controlatérale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":106,"sourceRow":83,"titleSource":"Dysfonction Occipito-atloïdienne, en FSgRd (E.M.)"},"85":{"source":"OSTPRA3 - page 6","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du thorax du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre supérieur homolatéral à la dysfonction par la main céphalique du praticien. La main caudale applicatrice contacte par l’éminence hypothénar le bord antérieur de l’extrémité interne de la clavicule les doigts reposent sur trapèze.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule. Dans le même axe, exercer une légère traction sur le membre supérieur et porter le moignon de l’épaule en direction du plafond. Majorer par la main applicatrice la pression sur l’extrémité de la clavicule en direction de la table jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans l’axe de la clavicule et en direction de la table en fin de mouvement.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":6,"sourceRow":85,"titleSource":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE, à droite"},"86":{"source":"OSTPRA3 - page 8","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"Dysfonction sus-sternale de la clavicule, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur de la tête du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique prend en berceau le membre supérieur homolatéral à la dysfonction. La main caudale applicatrice contacte, par l’éminence hypothénar, la face supérieure de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule en exerçant une légère traction. Par la main applicatrice, majorer la pression sur l’extrémité interne de la clavicule, en direction des pieds du sujet, jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant la traction sur le membre supérieur, porter le thrust par la main applicatrice en direction des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":8,"sourceRow":86,"titleSource":"Dysfonction sus-sternale de la clavicule, à droite"},"87":{"source":"OSTPRA3 - page 10","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE (E.M.), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction, la main de l’épaule en dysfonction est posée sur l’épaule du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, face au sujet.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Maintenir le poignet du patient et contacter par l’index et le majeur de la main applicatrice le bord antérieur de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le bras et l’épaule du sujet en direction du plafond jusqu’à percevoir, par la main applicatrice, la barrière motrice sterno-claviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tracter l’épaule et le bras en direction de la table et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par élévation de l’épaule – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":10,"sourceRow":87,"titleSource":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE (E.M.), à droite"},"88":{"source":"OSTPRA3 - page 12","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"DYSFONCTION SUS-STERNALE DE LA CLAVICULE (E.M.), à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. L’épaule en dysfonction est légèrement en dehors de la table.\nPRATICIEN Debout face au sujet.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale saisit le poignet du sujet. La main applicatrice contacte par l’index et le majeur, le bord antérieur de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur en rétropulsion, en rotation interne et en légère abduction, jusqu’à percevoir par la main applicatrice, la barrière motrice sterno-claviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de soulever le membre supérieur et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par un abaissement du membre supérieur – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":12,"sourceRow":88,"titleSource":"DYSFONCTION SUS-STERNALE DE LA CLAVICULE (E.M.), à gauche"},"89":{"source":"OSTPRA3 - page 14","category":"Membre supérieur – articulation acromio-claviculaire","method":"Mobilisation","intro":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation antérieure, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main applicatrice contacte par le pisiforme la partie la plus postérieure de la face supéro-externe de la clavicule. La main opposée empaume la partie proximale de l’avant-bras.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Fixer la clavicule en rotation postérieure en exerçant, par la main applicatrice, une pression horizontale vers l’arrière.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’avant et se terminant en position de rétropulsion.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":14,"sourceRow":89,"titleSource":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation antérieure, à gauche"},"90":{"source":"OSTPRA3 - page 16","category":"Membre supérieur – articulation acromio-claviculaire","method":"Mobilisation","intro":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation postérieure à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume l’avant-bras. La main applicatrice contacte par le pisiforme la partie la plus antérieure de la face supéro‑externe la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer par le pisiforme une pression en direction de la table de façon à fixer la clavicule en rotation antérieure.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’arrière et se terminant en position d’antépulsion et adduction.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":16,"sourceRow":90,"titleSource":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation postérieure à gauche"},"91":{"source":"OSTPRA3 - page 18","category":"Membre supérieur – gleno-humérale","method":"Thrust","intro":"DYSFONCTION GLÉNO-HUMÉRALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le coude du sujet. La face antérieure de la cuisse contacte la face supéro-interne du bras du sujet. L’éminence hypothénar de la main applicatrice contacte la tête humérale.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur le membre supérieur en l’amenant en adduction, puis majorer la pression sur la tête de l’humérus en direction du sol jusqu’à percevoir la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":18,"sourceRow":91,"titleSource":"DYSFONCTION GLÉNO-HUMÉRALE, en antériorité, à gauche"},"92":{"source":"OSTPRA3 - page 20","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"DYSFONCTION HUMÉRO-ULNAIRE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur distal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en adduction. Majorer par la main interne la pression sur le coude de dedans en dehors jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":20,"sourceRow":92,"titleSource":"DYSFONCTION HUMÉRO-ULNAIRE, en abduction, à gauche"},"93":{"source":"OSTPRA3 - page 22","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"DYSFONCTION HUMÉRO-ULNAIRE en adduction, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur proximal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale par rapport au sol.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en abduction. Majorer par la main externe la pression sur le coude de dehors en dedans jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":22,"sourceRow":93,"titleSource":"DYSFONCTION HUMÉRO-ULNAIRE en adduction, à droite"},"94":{"source":"OSTPRA3 - page 24","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. Le coude du sujet est posé sur la face antérieure de la cuisse du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, le genou du membre inférieur proximal est posé sur la table.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume le poignet du sujet. L’index et le majeur de la main opposée contactent le pli antérieur du coude.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener l’avant-bras en flexion et en supination. La main applicatrice exerce une pression sur la tête radiale en la tractant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en majorant la traction.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":24,"sourceRow":94,"titleSource":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite"},"95":{"source":"OSTPRA3 - page 26","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le poignet du sujet. Le pouce de la main proximale applicatrice contacte la convexité postérieure de la tête radiale en dysfonction, les autres doigts soutiennent la face interne du coude.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Placer l’avant-bras en extension incomplète de façon à permettre le jeu articulaire. Amener la main du sujet en flexion palmaire et en inclinaison ulnaire.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation interne et l’extension du coude. Simultanément, le pouce applicateur exerce une pression sur la tête radiale. En fin de mouvement, la main du sujet vient en butée sur la hanche du praticien de façon à éviter l’hyper-extension.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":26,"sourceRow":95,"titleSource":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite"},"96":{"source":"OSTPRA3 - page 28","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en postériorité (variante), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en pronation entre le membre supérieur interne et le thorax à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La main externe applicatrice contacte, par la métacarpo-phalangienne de l’index, la partie postérieure de la tête radiale.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension. La main applicatrice exerce une pression sur le coude de l’arrière vers l’avant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du plafond.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":28,"sourceRow":96,"titleSource":"DYSFONCTION HUMÉRO-RADIALE, en postériorité (variante), à droite"},"97":{"source":"OSTPRA3 - page 30","category":"Membre supérieur – radio-carpienne","method":"Snap","intro":"DYSFONCTION RADIO-CARPIENNE DU SCAPHOÏDE OU DU SEMI-LUNAIRE, en postériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la main est placée en dehors de la table.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Enserrer le poignet entre les pouces et les index des deux mains. Les pouces superposés contactent la partie supérieure du scaphoïde ou du semi-lunaire. Les index soutiennent la face palmaire de la main.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » sur l’un ou l’autre des deux os, en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":30,"sourceRow":97,"titleSource":"DYSFONCTION RADIO-CARPIENNE DU SCAPHOÏDE OU DU SEMI-LUNAIRE, en postériorité, à gauche"},"98":{"source":"OSTPRA3 - page 32","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"DYSFONCTION RADIO-CARPIENNE, en adduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main externe contacte le bord ulnaire des os du carpe.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en adduction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":32,"sourceRow":98,"titleSource":"DYSFONCTION RADIO-CARPIENNE, en adduction, à gauche"},"99":{"source":"OSTPRA3 - page 34","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"DYSFONCTION RADIO-CARPIENNE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main interne contacte le bord radial des os du carpe.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en abduction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":34,"sourceRow":99,"titleSource":"DYSFONCTION RADIO-CARPIENNE, en abduction, à gauche"},"100":{"source":"OSTPRA3 - page 36","category":"Membre supérieur – médio-carpienne","method":"Mobilisation","intro":"DYSFONCTION ARTICULAIRE GLOBALE DES MÉDIO-CARPIENNES, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le coude est fléchi à 90°.\nPRATICIEN Debout en fente avant les épaules dirigées du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains recouvrent la région carpienne antérieure et postérieure. Les éminences thénars sont placées perpendiculairement à l’axe de l’avant-bras. Les pouces se croisent sur la première commissure.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Les éminences thénar majorent la compression sur les os du carpe jusqu’à la barrière motrice et la maintiennent.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fermer la main avec force quelques secondes puis, au relâchement, majorer la compression – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":36,"sourceRow":100,"titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DES MÉDIO-CARPIENNES, à droite"},"101":{"source":"OSTPRA3 - page 38","category":"Membre supérieur – inter-carpiennes","method":"Snap","intro":"DYSFONCTION ARTICULAIRE GLOBALE DES INTER-CARPIENNES, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux pouces sont superposés sur la partie postérieure de l’espace inter-carpien en dysfonction. Les autres doigts maintiennent la partie antérieure du poignet.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":38,"sourceRow":101,"titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DES INTER-CARPIENNES, à gauche"},"102":{"source":"OSTPRA3 - page 40","category":"Membre supérieu – trapézo-metacarpienne","method":"Thrust","intro":"DYSFONCTION ARTICULAIRE GLOBALE DE LA TRAPÉZO-MÉTACARPIENNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus.\nPRATICIEN Debout à la hauteur de la main du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le premier rayon de la main du sujet. Le pouce contacte la base postérieure du premier métacarpien. La main proximale empaume l’extrémité distale de l’avant-bras, le pouce de la main proximale se superposant au premier.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Les pouces exercent une pression progressive sur la base métacarpienne en dedans et vers l’extrémité distale du pouce jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la pression sur la base métacarpienne jusqu’à percevoir la décoaptation de l’articulation.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":40,"sourceRow":102,"titleSource":"DYSFONCTION ARTICULAIRE GLOBALE DE LA TRAPÉZO-MÉTACARPIENNE, à droite"},"103":{"source":"OSTPRA3 - page 42","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation interne, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis en bord de table, les pieds sont posés au sol, les mains sont en appui sur la table. Placer la cheville homolatérale à la dysfonction sur le genou opposé, l’ensemble est stabilisé par le genou du\npraticien.\nPRATICIEN Debout face au patient, en fente avant, du côté opposé à l’articulation en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main proximale établit un contact, par la métacarpo-phalangienne de l’index, avec la région inguinale homolatérale à la dysfonction. La main opposée du praticien empaume la face interne du genou.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à incliner et tourner le tronc et la tête légèrement du côté opposé à la dysfonction. Majorer la rotation externe de la hanche jusqu’à la barrière motrice en poussant le genou du patient en direction du sol. Majorer son contact inguinal en appuyant en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à pousser son genou vers le haut et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation externe de la hanche – À répéter trois fois. En fin de technique, porter le thrust en majorant à la fois la rotation externe et la pression au niveau de l’aine.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":42,"sourceRow":103,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation interne, à gauche"},"104":{"source":"OSTPRA3 - page 44","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation externe, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit la cheville homolatérale à la dysfonction du patient. Le talon de la main céphalique contacte la face postérieure du grand trochanter après avoir refoulé les tissus musculaires.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale majore la rotation interne de la hanche, la main céphalique exerce une pression progressive sur le grand trochanter en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer trois fois de suite la rotation interne et la pression sur le grand trochanter puis demander au sujet de tourner la tête du côté opposé à la dysfonction. Porter le thrust en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":44,"sourceRow":104,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation externe, à droite"},"105":{"source":"OSTPRA3 - page 46","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral sur le côté de la dysfonction.\nPRATICIEN Debout derrière le sujet à la hauteur du bassin.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale soutient en prise berceau le membre inférieur en dysfonction. La main céphalique contacte par la métacarpo-phalangienne de l’index la région inguinale homolatérale. Le pelvis du sujet est stabilisé par le bassin du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en légère extension. Amener le membre inférieur en dysfonction en légère flexion de hanche et adduction jusqu’à la barrière motrice. Le praticien majore le contact inguinal de la main céphalique par un mouvement antérieur de son pelvis.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’adduction et la pression inguinale.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":46,"sourceRow":105,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en abduction, à gauche"},"106":{"source":"OSTPRA3 - page 48","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en adduction, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction. Le membre inférieur sous‑jacent est en flexion de hanche et de genou.\nPRATICIEN Debout derrière le sujet à la hauteur du pelvis pour le stabiliser.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur en dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en abduction puis majorer l’appui sur le grand trochanter jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du genou fléchi sous-jacent en majorant à la fois l’abduction et la pression sur le grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":48,"sourceRow":106,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en adduction, à droite"},"107":{"source":"OSTPRA3 - page 50","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en flexion, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur des cuisses, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur homolatéral à la dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en extension jusqu’à la barrière motrice et majorer le contact trochantérien.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’extension et la pression sur le grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":50,"sourceRow":107,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en flexion, à droite"},"108":{"source":"OSTPRA3 - page 52","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en antériorité classique, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table aux pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale et postérieure du tibia du membre inférieur en dysfonction. La main interne empaume l’extrémité distale et antérieure du tibia.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le praticien cherche à amener la hanche en adduction et en rotation interne de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Soulever le membre inférieur de façon à permettre une adduction de la hanche au-delà de l’axe médian du corps. Le praticien transfert son poids sur la jambe externe de façon à amener le membre inférieur en abduction et rotation externe. Il transfert ensuite son poids sur la jambe interne pour porter un thrust en majorant à la fois l’adduction et la rotation interne. Renouveler la manœuvre si nécessaire.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":52,"sourceRow":108,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en antériorité classique, à droite"},"109":{"source":"OSTPRA3 - page 54","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en postériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe et le sillon delto‑pectoral calent le genou fléchi du membre inférieur en dysfonction. La main interne stabilise le pelvis par un contre-appui sur l’épine iliaque antéro-supérieure controlatérale.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer quatre séries de trois pressions. D’abord dans l’axe fémoral en direction de la table, puis en adduction, puis en abduction puis en flexion. La mise en tension se termine par une série de circumduction de plus en plus ample jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de circumduction en majorant l’abduction et la rotation externe dans un mouvement de haute vélocité.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":54,"sourceRow":109,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE, en postériorité, à droite"},"110":{"source":"OSTPRA3 - page 56","category":"Membre inférieur – coxo-fémorale","method":"Mobilisation","intro":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE dans un axe transversal, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains superposées empaument la partie supéro-interne de la cuisse du membre inférieur en dysfonction. La face externe du genou est stabilisée par le sternum du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la compression des tissus de la face interne de la cuisse.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"À l’aide du sternum, exercer une pression sur le genou. Les deux mains tractent la cuisse en direction du haut et du dehors – À répéter plusieurs fois dans un mouvement de pompage.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":56,"sourceRow":110,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE dans un axe transversal, à droite"},"111":{"source":"OSTPRA3 - page 58","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le genou du membre inférieur en dysfonction et l’avant-bras stabilise la face interne du segment jambier. La main céphalique stabilise le pelvis par un contact sur l’épine iliaque antéro-supérieure opposée.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en rotation interne jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":58,"sourceRow":111,"titleSource":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE, en antériorité, à droite"},"112":{"source":"OSTPRA3 - page 60","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou, les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’adduction du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":60,"sourceRow":112,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en abduction, à gauche"},"113":{"source":"OSTPRA3 - page 62","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en adduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou. Les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’abduction du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":62,"sourceRow":113,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en adduction, à gauche"},"114":{"source":"OSTPRA3 - page 64","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer, par les deux mains applicatrices, la pression sur la tubérosité tibiale antérieure vers l’arrière jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’arrière.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":64,"sourceRow":114,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche"},"115":{"source":"OSTPRA3 - page 66","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter, par les deux mains applicatrices, le plateau tibial vers l’avant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’avant.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":66,"sourceRow":115,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche"},"116":{"source":"OSTPRA3 - page 68","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation interne, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur de la jambe, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial interne.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation externe et en flexion complète du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":68,"sourceRow":116,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation interne, à droite"},"117":{"source":"OSTPRA3 - page 70","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation externe, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout en fente avant à la hauteur de la jambe en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial externe.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation interne et en flexion complète du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":70,"sourceRow":117,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation externe, à droite"},"118":{"source":"OSTPRA3 - page 72","category":"Membre inférieur – fémoro-tibiale","method":"Mobilisation","intro":"DYSFONCTION DU MÉNISQUE MÉDIAL, en postériorité et en extension, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume la face plantaire du pied. La main céphalique empaume la partie supérieure du genou. L’index contacte l’interligne fémoro-tibial interne en regard de la corne antérieure du ménisque interne en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le tibia en rotation externe et en abduction pour ouvrir le compartiment interne. Ramener le talon du sujet sur la table. Puis tourner la main céphalique de telle façon à ce que le pouce remplace l’index au contact du ménisque médial et que les autres doigts soutiennent le genou.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"La normalisation dynamique se fait en amenant simultanément le genou en extension complète, en adduction et en rotation interne.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":72,"sourceRow":118,"titleSource":"DYSFONCTION DU MÉNISQUE MÉDIAL, en postériorité et en extension, à droite"},"119":{"source":"OSTPRA3 - page 74","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en translation interne, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité inférieure de la cuisse, au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité supérieure du tibia, en dessous de l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial interne de dedans en dehors jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":74,"sourceRow":119,"titleSource":"DYSFONCTION DE LA FÉMORO-TIBIALE, en translation interne, à gauche"},"120":{"source":"OSTPRA3 - page 76","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION FÉMORO-TIBIALE, en translation externe, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité supérieure du tibia au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité inférieure de la cuisse en dessous de l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial externe de dehors en dedans jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":76,"sourceRow":120,"titleSource":"DYSFONCTION FÉMORO-TIBIALE, en translation externe, à gauche"},"121":{"source":"OSTPRA3 - page 78","category":"Membre inférieur – fémoro-tibiale","method":"Mobilisation","intro":"DYSFONCTION DU MÉNISQUE MÉDIAL en postériorité, en flexion, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inférieure du segment jambier en dysfonction. Les doigts de la main céphalique contactent l’interligne articulaire fémoro-tibial interne, en regard du ménisque médial. La face externe du genou est stabilisée par le sternum du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou en abduction et en rotation externe afin de favoriser l’ouverture du compartiment articulaire interne.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"La main caudale amène le genou en rotation interne et en flexion complète du genou dans un mouvement dynamique. La main céphalique reste, quant à elle, au contact du ménisque.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":78,"sourceRow":121,"titleSource":"DYSFONCTION DU MÉNISQUE MÉDIAL en postériorité, en flexion, à droite"},"122":{"source":"OSTPRA3 - page 80","category":"Membre inférieur – fibulo-tibiale supérieure","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE SUPÉRIEURE, en postériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inféro-interne de la jambe. La métacarpo-phalangienne de l’index de la main céphalique contacte la face postérieure de la tête péronière formant ainsi un contre appui dans la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en flexion de hanche et de genou en y associant une rotation externe du segment jambier et une abduction de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale. La main céphalique restant au contact de la face postérieure de la fibula. Le sternum en appui sur la face antérieure du tibia accompagne le mouvement.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":80,"sourceRow":122,"titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE SUPÉRIEURE, en postériorité, à gauche"},"123":{"source":"OSTPRA3 - page 82","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est posé sur la table.\nPRATICIEN Debout face au pied du sujet, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains empaument le pied. La pulpe du pouce externe contacte la face antérieure de la malléole externe, les autres doigts sont sur le talon. Le pouce de la main interne renforce l’appui initial.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en légère flexion dorsale. Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":82,"sourceRow":123,"titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en antériorité, à gauche"},"124":{"source":"OSTPRA3 - page 84","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en postériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table, face au pied du patient, la plante du pied contacte la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main externe est en appui sur la face postérieure de la malléole externe, les autres doigts maintiennent et stabilisent l’avant-pied en légère flexion dorsale. Le pouce interne renforce l’appui initial.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":84,"sourceRow":124,"titleSource":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en postériorité, à droite"},"125":{"source":"OSTPRA3 - page 86","category":"Membre inférieur – tibio-tarsienne","method":"Lift","intro":"DYSFONCTION DE LA TIBIO-TARSIENNE ARTICULAIRE GLOBALE, en décubitus ventral, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le genou céphalique maintient la face postérieure de la cuisse au dessus de la fosse poplitée. Les deux mains, les doigts sont croisés en regard de la malléole interne, enserrent la cheville en dysfonction. Les avant-bras sont à l’horizontale.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en position neutre et exercer une légère traction en direction du plafond jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer la traction par une traction verticale (lift) des deux mains dans l’axe tibial.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":86,"sourceRow":125,"titleSource":"DYSFONCTION DE LA TIBIO-TARSIENNE ARTICULAIRE GLOBALE, en décubitus ventral, à gauche"},"126":{"source":"OSTPRA3 - page 88","category":"Membre inférieur – tibio-tarsienne","method":"Snap","intro":"ENTORSE TIBIO-TARSIENNE EXTERNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon, le pouce contacte le col du talus. La main interne renforce l’appui en maintenant le coup de pied en légère flexion dorsale.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion dorsale du pied et ajouter une composante d’éversion jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur le talus par le pouce en « snap » vers l’arrière et le dedans.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":88,"sourceRow":126,"titleSource":"ENTORSE TIBIO-TARSIENNE EXTERNE, à droite"},"127":{"source":"OSTPRA3 - page 90","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"DYSFONCTION DE LA TIBIO-TARSIENNE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal.\nPRATICIEN Debout à la hauteur de la cheville.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le talon. La première commissure de la main céphalique maintient la face antérieure du pilon tibial.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir le pied en légère flexion dorsale. La main céphalique majore la pression vers l’arrière jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":90,"sourceRow":127,"titleSource":"DYSFONCTION DE LA TIBIO-TARSIENNE, en antériorité, à droite"},"128":{"source":"OSTPRA3 - page 92","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"DÉCOAPTATION DE LA TIBIO-TARSIENNE GLOBALE, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Position semi-accroupie en bout de table à la hauteur du pied du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains sont croisées sur le coup de pied, les bords cubitaux des deux mains contactent le col du talus.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en flexion dorsale et exercer une traction dans l’axe tibial jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains en majorant la traction du pied.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":92,"sourceRow":128,"titleSource":"DÉCOAPTATION DE LA TIBIO-TARSIENNE GLOBALE, à gauche"},"129":{"source":"OSTPRA3 - page 94","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE ANTÉRO-INTERNE, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est en dehors de la table.\nPRATICIEN Debout entre les jambes du sujet, à la hauteur du pied en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. Le pisiforme de la main céphalique contact la tête du talus en dedans du tibial antérieur.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied successivement en inversion, en flexion dorsale, en éversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":94,"sourceRow":129,"titleSource":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE ANTÉRO-INTERNE, à gauche"},"130":{"source":"OSTPRA3 - page 96","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE POSTÉRO-EXTERNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur du pied en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. La main céphalique contacte par le pisiforme la tête du talus, en dehors de l’extenseur commun des orteils.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener successivement le pied en éversion, en flexion dorsale, en inversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":96,"sourceRow":130,"titleSource":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE POSTÉRO-EXTERNE, à droite"},"131":{"source":"OSTPRA3 - page 98","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en varus, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé au membre inférieur en dysfonction. Les genoux sont fléchis, le pied sus-jacent est légèrement en retrait.\nPRATICIEN Debout à la hauteur des pieds.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le calcanéus en dysfonction. Le bord cubital de la main céphalique contacte la face supéro-externe du calcanéus.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène et maintient le calcanéus en valgus. Exercer par la main céphalique une pression progressive, en direction de la table, sur la face externe du calcanéus jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":98,"sourceRow":131,"titleSource":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en varus, à gauche"},"132":{"source":"OSTPRA3 - page 100","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en valgus, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les genoux sont fléchis, le pied en dysfonction est en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le talon en dysfonction en dehors de la table, le reste du pied est sur la table. La main caudale empaume et fixe l’avant-pied en éversion. La main céphalique empaume la face interne du calcanéus.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique maintient le calcanéus en valgus. La main caudale exerce une pression progressive, en direction de la table jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":100,"sourceRow":132,"titleSource":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en valgus, à droite"},"133":{"source":"OSTPRA3 - page 102","category":"Membre inférieur – calcanéo-cuboïdienne","method":"Thrust","intro":"DYSFONCTION DE LA CALCANÉO-CUBOÏDIENNE, en rotation interne (pronation), à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon en dysfonction, le pouce contacte le col du talus en avant de la malléole externe. La main opposée enserre entre le pouce et les autres doigts la face plantaire et dorsale du pied, jusqu’au 4e et 5e métatarsiens (sous l’interligne cuboïdo-métatarsien)","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main externe fixe le talon, la main interne amène l’avant-pied en supination jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne en supination de l’avant-pied.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":102,"sourceRow":133,"titleSource":"DYSFONCTION DE LA CALCANÉO-CUBOÏDIENNE, en rotation interne (pronation), à gauche"},"134":{"source":"OSTPRA3 - page 104","category":"Membre inférieur – talo-naviculaire","method":"Thrust","intro":"DYSFONCTION TALO-NAVICULAIRE, en rotation externe (supination), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout du côté de la dysfonction à la hauteur du pied du patient.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’extrémité inférieure du segment jambier, l’index est sur le col du talus en dysfonction. La main caudale contacte la face supérieure et interne de l’avant pied, son index est sur la partie interne de l’os naviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène l’os naviculaire en pronation jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale en pronation, en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":104,"sourceRow":134,"titleSource":"DYSFONCTION TALO-NAVICULAIRE, en rotation externe (supination), à droite"},"135":{"source":"OSTPRA3 - page 106","category":"Membre inférieur – naviculo-cuboïdienne","method":"Snap","intro":"DYSFONCTION DE LA NAVICULO-CUBOÏDIENNE ARTICULAIRE GLOBALE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le membre inférieur en dysfonction est en dehors de la table, le genou est fléchi.\nPRATICIEN Debout face au pied du patient, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains enserrent les bords interne et externe du pied. Les pouces sont superposés sur l’interligne articulaire naviculo-cuboïdien de la face plantaire, les autres doigts soutiennent la face dorsale du pied.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser le membre inférieur par plusieurs mouvements en piston jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"En fin de mouvement, porter le thrust en « snap » par les deux pouces en majorant la flexion plantaire et la pression sur l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":106,"sourceRow":135,"titleSource":"DYSFONCTION DE LA NAVICULO-CUBOÏDIENNE ARTICULAIRE GLOBALE, à droite"},"136":{"source":"OSTPRA3 - page 108","category":"Membre inférieur – metatarso-phalangiennes","method":"Thrust","intro":"DYSFONCTION DE LA MÉTACARPO-PHALANGIENNE DE LA 1re PHALANGE, en flexion dorsale, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout sur le côté du pied en dysfonction à la hauteur du pied du patient.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume la face interne de l’avant-pied au niveau du premier rayon métatarsien en dysfonction. La pince pouce-index de la main caudale saisit la première phalange du gros orteil.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique amène le premier métatarsien en pronation. La main caudale majore la flexion plantaire de la première phalange du gros orteil jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale, en flexion plantaire.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":108,"sourceRow":136,"titleSource":"DYSFONCTION DE LA MÉTACARPO-PHALANGIENNE DE LA 1re PHALANGE, en flexion dorsale, à droite"}},"byTechniqueId":{},"officialTechniques":[{"slug":"ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche","sourceRow":2,"sourceBook":"OSTPRA1","sourcePage":6,"matchers":["dysfonction de ilium en anteriorite a gauche"],"title":"DYSFONCTION DE ILIUM, en antériorité à gauche","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal. Les mains derrière la tête, les doigts sont croisés. Le membre inférieur homolatéral à la dysfonction est posé sur le membre inférieur controlatéral.\nPRATICIEN Debout, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main et l’avant-bras céphalique sont sur la ceinture scapulaire homolatérale à la dysfonction ; la main caudale est posée sur l’épine ilium antéro-supérieure du côté de la dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la ceinture scapulaire dans un plan perpendiculaire à la table et exercer une légère traction dans l’axe vertébral. Stabiliser la position avec la main céphalique. La main caudale empaume l’épine ilium antéro-supérieure du côté à traiter et ramène le pelvis au contact de la table. Amener l’ilium vers la postériorisation jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust dans la direction de la postériorisation de l’ilium.","detail":{"source":"OSTPRA1 - page 6","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE ILIUM, en antériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les mains derrière la tête, les doigts sont croisés. Le membre inférieur homolatéral à la dysfonction est posé sur le membre inférieur controlatéral.\nPRATICIEN Debout, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphalique sont sur la ceinture scapulaire homolatérale à la dysfonction ; la main caudale est posée sur l’épine ilium antéro-supérieure du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la ceinture scapulaire dans un plan perpendiculaire à la table et exercer une légère traction dans l’axe vertébral. Stabiliser la position avec la main céphalique. La main caudale empaume l’épine ilium antéro-supérieure du côté à traiter et ramène le pelvis au contact de la table. Amener l’ilium vers la postériorisation jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans la direction de la postériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p006-dysfonction-de-ilium-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":6,"sourceRow":2}},{"slug":"ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe","sourceRow":3,"sourceBook":"OSTPRA1","sourcePage":8,"matchers":["dysfonction de l ilium en anteriorite a gauche variante sujet laxe"],"title":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (variante sujet laxe)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/planche-photos.webp","text":"POSITION\nPATIENT En décubitus latéral du côté opposé à la dysfonction. Le membre inférieur du côté à traiter est en flexion de hanche et de genou à 90°. Le membre inférieur sur la table est en rectitude.\nPRATICIEN Debout, face au patient, entre les membres inférieurs du patient à la hauteur du pelvis en fente avant en direction de la tête du patient.\n\nPOSITION DES MAINS\nLa cuisse gauche du patient est soutenue par le bassin du praticien. Les mains sont en pronation empaumant l’ischium et l’épine ilium antéro-supérieure du côté à traiter.\n\nBARRIÈRE MOTRICE\nMajorer la flexion de hanche pour amener l’ilium vers la postériorité jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction de la postériorisation de l’ilium.","detail":{"source":"OSTPRA1 - page 8","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (variante sujet laxe)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. Le membre inférieur du côté à traiter est en flexion de hanche et de genou à 90°. Le membre inférieur sur la table est en rectitude.\nPRATICIEN Debout, face au patient, entre les membres inférieurs du patient à la hauteur du pelvis en fente avant en direction de la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La cuisse gauche du patient est soutenue par le bassin du praticien. Les mains sont en pronation empaumant l’ischium et l’épine ilium antéro-supérieure du côté à traiter.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion de hanche pour amener l’ilium vers la postériorité jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la postériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p008-dysfonction-de-l-ilium-en-anteriorite-a-gauche-variante-sujet-laxe/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":8,"sourceRow":3}},{"slug":"ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche","sourceRow":4,"sourceBook":"OSTPRA1","sourcePage":10,"matchers":["dysfonction de l ilium en posteriorite a gauche"],"title":"DYSFONCTION DE L’ILIUM, en postériorité à gauche","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus latéral, controlatéral à l’ilium en dysfonction. Le membre inférieur du côté à traiter est en triple flexion (pied à la hauteur de la fosse poplitée du genou droit).\nPRATICIEN Debout à la hauteur du pelvis, face au patient.\n\nPOSITION DES MAINS\nLa main céphalique est sous le creux axillaire et maintient l’épaule du patient en haut et en arrière. La main caudale est en regard de l’épine ilium postéro-supérieure, les doigts sont orientés dans le sens de la crête iliaque. Placer le genou du patient entre les membres inférieurs du praticien afin de stabiliser la flexion et organiser la barrière motrice.\n\nBARRIÈRE MOTRICE\nTracter le rachis dans l’axe et stabiliser la position avec la main céphalique. Rechercher la barrière motrice de la flexion vers l’extension de la hanche jusqu’à percevoir la mise en tension de l’ilium vers l’antériorité.\n\nNORMALISATION\nPorter le thrust par la main caudale en direction de l’antériorisation de l’ilium.","detail":{"source":"OSTPRA1 - page 10","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral, controlatéral à l’ilium en dysfonction. Le membre inférieur du côté à traiter est en triple flexion (pied à la hauteur de la fosse poplitée du genou droit).\nPRATICIEN Debout à la hauteur du pelvis, face au patient.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est sous le creux axillaire et maintient l’épaule du patient en haut et en arrière. La main caudale est en regard de l’épine ilium postéro-supérieure, les doigts sont orientés dans le sens de la crête iliaque. Placer le genou du patient entre les membres inférieurs du praticien afin de stabiliser la flexion et organiser la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le rachis dans l’axe et stabiliser la position avec la main céphalique. Rechercher la barrière motrice de la flexion vers l’extension de la hanche jusqu’à percevoir la mise en tension de l’ilium vers l’antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en direction de l’antériorisation de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p010-dysfonction-de-l-ilium-en-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":10,"sourceRow":4}},{"slug":"ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe","sourceRow":5,"sourceBook":"OSTPRA1","sourcePage":12,"matchers":["dysfonction de l ilium en posteriorite a droite variante sujet laxe"],"title":"DYSFONCTION DE L’ILIUM, en postériorité à droite (variante sujet laxe)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nPrendre en berceau le membre inférieur à traiter par la main caudale. La paume de la main céphalique est sur l’épine ilium postéro-supérieure du côté à traiter. Les doigts sont orientés vers la crête iliaque.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur à traiter en extension, en adduction et en rotation interne jusqu’à la barrière motrice en antériorité.\n\nNORMALISATION\nPorter le thrust par la main céphalique sur l’épine ilium postéro-supérieure vers l’antériorité de l’ilium.","detail":{"source":"OSTPRA1 - page 12","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite (variante sujet laxe)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur à traiter par la main caudale. La paume de la main céphalique est sur l’épine ilium postéro-supérieure du côté à traiter. Les doigts sont orientés vers la crête iliaque.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur à traiter en extension, en adduction et en rotation interne jusqu’à la barrière motrice en antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique sur l’épine ilium postéro-supérieure vers l’antériorité de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p012-dysfonction-de-l-ilium-en-posteriorite-a-droite-variante-sujet-laxe/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":12,"sourceRow":5}},{"slug":"ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite","sourceRow":6,"sourceBook":"OSTPRA1","sourcePage":14,"matchers":["dysfonction de l ilium en superiorite a droite"],"title":"DYSFONCTION DE L’ILIUM, en supériorité à droite","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée du côté de la dysfonction. Le membre inférieur à traiter est en légère abduction et rotation interne.\nPRATICIEN Debout face aux pieds du patient.\n\nPOSITION DES MAINS\nEmpaumer la cheville, la main externe étant en supination et la main interne en pronation.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en légère extension, abduction et en rotation interne puis exercer une traction jusqu’à percevoir la barrière motrice une traction.\n\nNORMALISATION\nPorter le thrust en traction dans l’axe du membre inférieur.","detail":{"source":"OSTPRA1 - page 14","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DE L’ILIUM, en supériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction. Le membre inférieur à traiter est en légère abduction et rotation interne.\nPRATICIEN Debout face aux pieds du patient.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la cheville, la main externe étant en supination et la main interne en pronation.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère extension, abduction et en rotation interne puis exercer une traction jusqu’à percevoir la barrière motrice une traction.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en traction dans l’axe du membre inférieur.","photo":"assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p014-dysfonction-de-l-ilium-en-superiorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":14,"sourceRow":6}},{"slug":"ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m","sourceRow":7,"sourceBook":"OSTPRA1","sourcePage":16,"matchers":["dysfonction de l ilium en anteriorite a gauche e m"],"title":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (E.M.)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/planche-photos.webp","text":"POSITION\nPATIENT En décubitus latéral du côté opposé à la dysfonction. La main homolatérale à la dysfonction saisit le sommet de la têtière. Le membre inférieur en dysfonction est en flexion de hanche inférieure à 90°.\nPRATICIEN Debout en fente avant à la hauteur des jambes, la jambe gauche est dirigée vers la tête du patient. Le pied homolatéral du patient est posé sur l’épine ilium antéro-supérieure gauche du\npraticien.\n\nPOSITION DES MAINS\nEmpaumer la face interne du genou par sa main céphalique. Poser la main caudale sur l’articulation sacro-ilium.\n\nBARRIÈRE MOTRICE\nMobiliser en flexion de hanche depuis une relative position d’extension jusqu’à la barrière motrice en postériorité de l’ilium.\n\nNORMALISATION\nDemander une abduction de hanche (poussée vers le plafond) contre résistance pendant 10 à 12 secondes – Au relâchement, trouver la nouvelle barrière motrice vers la flexion (quelques degrés) – À répéter 3 fois. Puis demander une adduction de hanche sur le même principe – à répéter trois fois – Même chose en flexion de hanche. Ensuite, demander au patient de pousser en extension de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, gagner en légère flexion de hanche. Répéter la manœuvre une seconde fois. Pour la troisième poussée, le praticien invite le patient à pousser en extension de telle sorte que la poussée exercée soit supérieure à la résistance du praticien, jusqu’à obtenir la rectitude du membre inférieur.","detail":{"source":"OSTPRA1 - page 16","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en antériorité à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral du côté opposé à la dysfonction. La main homolatérale à la dysfonction saisit le sommet de la têtière. Le membre inférieur en dysfonction est en flexion de hanche inférieure à 90°.\nPRATICIEN Debout en fente avant à la hauteur des jambes, la jambe gauche est dirigée vers la tête du patient. Le pied homolatéral du patient est posé sur l’épine ilium antéro-supérieure gauche du\npraticien.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer la face interne du genou par sa main céphalique. Poser la main caudale sur l’articulation sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser en flexion de hanche depuis une relative position d’extension jusqu’à la barrière motrice en postériorité de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une abduction de hanche (poussée vers le plafond) contre résistance pendant 10 à 12 secondes – Au relâchement, trouver la nouvelle barrière motrice vers la flexion (quelques degrés) – À répéter 3 fois. Puis demander une adduction de hanche sur le même principe – à répéter trois fois – Même chose en flexion de hanche. Ensuite, demander au patient de pousser en extension de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, gagner en légère flexion de hanche. Répéter la manœuvre une seconde fois. Pour la troisième poussée, le praticien invite le patient à pousser en extension de telle sorte que la poussée exercée soit supérieure à la résistance du praticien, jusqu’à obtenir la rectitude du membre inférieur.","photo":"assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p016-dysfonction-de-l-ilium-en-anteriorite-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":16,"sourceRow":7}},{"slug":"ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m","sourceRow":8,"sourceBook":"OSTPRA1","sourcePage":18,"matchers":["dysfonction de l ilium en posteriorite a droite e m"],"title":"DYSFONCTION DE L’ILIUM, en postériorité à droite (E.M.)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal le membre inférieur droit est en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis\n\nPOSITION DES MAINS\nLa main céphalique empaume et fixe l’épine ilium antéro-supérieure controlatérale à la dysfonction, la main caudale est posée sur le dessus du genou homolatéral, les doigts sont orientés vers le dehors.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en légère abduction et en extension de hanche jusqu’à la barrière motrice en antériorité (contrôler au niveau de l’épine iliaque postéro-supérieure).\n\nNORMALISATION\nInviter le patient à pousser en flexion de hanche contre résistance pendant 10 à 12 secondes puis gagner vers la nouvelle barrière motrice en extension de hanche – à répéter 3 fois.","detail":{"source":"OSTPRA1 - page 18","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal le membre inférieur droit est en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume et fixe l’épine ilium antéro-supérieure controlatérale à la dysfonction, la main caudale est posée sur le dessus du genou homolatéral, les doigts sont orientés vers le dehors.","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en légère abduction et en extension de hanche jusqu’à la barrière motrice en antériorité (contrôler au niveau de l’épine iliaque postéro-supérieure).","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en flexion de hanche contre résistance pendant 10 à 12 secondes puis gagner vers la nouvelle barrière motrice en extension de hanche – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p018-dysfonction-de-l-ilium-en-posteriorite-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":18,"sourceRow":8}},{"slug":"ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m","sourceRow":9,"sourceBook":"OSTPRA1","sourcePage":20,"matchers":["dysfonction de l ilium en posteriorite a droite en procubitus e m"],"title":"DYSFONCTION DE L’ILIUM, en postériorité à droite en procubitus (E.M.)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nPrendre en berceau le membre inférieur droit par la main caudale, et de la main céphalique contacter l’épine ilium postéro-supérieure et la partie postérieure de la crête iliaque. Les doigts sont orientés vers la crête iliaque.\n\nBARRIÈRE MOTRICE\nAmener la hanche en extension, en adduction et en légère rotation interne jusqu’à la barrière motrice en antériorité.\n\nNORMALISATION\nDemander une flexion de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en antériorité – à répéter 3 fois.","detail":{"source":"OSTPRA1 - page 20","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en postériorité à droite en procubitus (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre inférieur droit par la main caudale, et de la main céphalique contacter l’épine ilium postéro-supérieure et la partie postérieure de la crête iliaque. Les doigts sont orientés vers la crête iliaque.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en extension, en adduction et en légère rotation interne jusqu’à la barrière motrice en antériorité.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une flexion de hanche contre résistance pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en antériorité – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p020-dysfonction-de-l-ilium-en-posteriorite-a-droite-en-procubitus-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":20,"sourceRow":9}},{"slug":"ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m","sourceRow":10,"sourceBook":"OSTPRA1","sourcePage":22,"matchers":["dysfonction de l ilium en fermeture a droite e m"],"title":"DYSFONCTION DE L’ILIUM, en fermeture à droite (E.M.)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur à traiter est en flexion, en abduction, en rotation externe de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis, le regard est dirigé vers les pieds du patient.\n\nPOSITION DES MAINS\nEmpaumer et fixer l’épine ilium antéro-supérieure controlatérale par la main céphalique et saisir la cheville homolatérale avec la main caudale. Le coude est en contact avec la face interne du genou.\n\nBARRIÈRE MOTRICE\nMajorer la flexion, l’abduction et la rotation externe de hanche jusqu’à la barrière motrice de la sacro-ilium droite en ouverture.\n\nNORMALISATION\nInviter le patient à pousser en rotation interne et en adduction pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en ouverture en rotation externe – à répéter 3 fois. À la fin, reposer le membre inférieur en perdant les paramètres dans l’ordre : d’abord la flexion puis l’abduction et enfin la rotation externe qui est maintenue jusqu’à la fin de la technique.","detail":{"source":"OSTPRA1 - page 22","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en fermeture à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur à traiter est en flexion, en abduction, en rotation externe de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis, le regard est dirigé vers les pieds du patient.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer et fixer l’épine ilium antéro-supérieure controlatérale par la main céphalique et saisir la cheville homolatérale avec la main caudale. Le coude est en contact avec la face interne du genou.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion, l’abduction et la rotation externe de hanche jusqu’à la barrière motrice de la sacro-ilium droite en ouverture.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation interne et en adduction pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en ouverture en rotation externe – à répéter 3 fois. À la fin, reposer le membre inférieur en perdant les paramètres dans l’ordre : d’abord la flexion puis l’abduction et enfin la rotation externe qui est maintenue jusqu’à la fin de la technique.","photo":"assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p022-dysfonction-de-l-ilium-en-fermeture-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":22,"sourceRow":10}},{"slug":"ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m","sourceRow":11,"sourceBook":"OSTPRA1","sourcePage":24,"matchers":["dysfonction de l ilium en ouverture a droite e m"],"title":"DYSFONCTION DE L’ILIUM, en ouverture à droite (E.M.)","zone":"Bassin","sub":"Ilium","level":"Niveau intermédiaire","status":"non vue","icon":"IL","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur du patient du côté à traiter est en flexion, en adduction, en rotation interne de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis en fente avant. Les épaules sont dirigées vers la tête du patient.\n\nPOSITION DES MAINS\nLa main céphalique est posée sur le bord interne de l’épine ilium postéro-supérieure gauche, la main caudale empaume le pied homolatéral à la dysfonction par sa face interne. L’épaule caudale du praticien prend appui sur la face externe du genou du patient.\n\nBARRIÈRE MOTRICE\nAmener la hanche en flexion, en adduction et en rotation interne avec le genou fléchi jusqu’à la barrière motrice jusqu’à percevoir la fermeture de l’ilium.\n\nNORMALISATION\nInviter le patient à pousser en rotation externe et en légère abduction contre résistance pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en fermeture en rotation interne – à répéter 3 fois – À la fin, perdre les paramètres dans l’ordre : d’abord la flexion, puis l’adduction et enfin la rotation interne qui est maintenue jusqu’à la fin de la technique.","detail":{"source":"OSTPRA1 - page 24","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DE L’ILIUM, en ouverture à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur du patient du côté à traiter est en flexion, en adduction, en rotation interne de hanche et en flexion de genou.\nPRATICIEN Debout à la hauteur du pelvis en fente avant. Les épaules sont dirigées vers la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le bord interne de l’épine ilium postéro-supérieure gauche, la main caudale empaume le pied homolatéral à la dysfonction par sa face interne. L’épaule caudale du praticien prend appui sur la face externe du genou du patient.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la hanche en flexion, en adduction et en rotation interne avec le genou fléchi jusqu’à la barrière motrice jusqu’à percevoir la fermeture de l’ilium.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser en rotation externe et en légère abduction contre résistance pendant 10 à 12 secondes. Au relâchement, gagner dans la nouvelle barrière motrice en fermeture en rotation interne – à répéter 3 fois – À la fin, perdre les paramètres dans l’ordre : d’abord la flexion, puis l’adduction et enfin la rotation interne qui est maintenue jusqu’à la fin de la technique.","photo":"assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p024-dysfonction-de-l-ilium-en-ouverture-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":24,"sourceRow":11}},{"slug":"ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc","sourceRow":12,"sourceBook":"OSTPRA1","sourcePage":26,"matchers":["dysfonction du sacrum en torsion posterieure avec le pisiforme direct a gauche"],"title":"DYSFONCTION DU SACRUM, en torsion postérieure avec le pisiforme direct, à gauche","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus controlatéral à la dysfonction, le membre inférieur controlatéral est en extension, l’homolatéral est en légère flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur du pelvis du patient. La main caudale est placée sur l’espace inter-épineux L5-S1.\n\nPOSITION DES MAINS\nLa main caudale contacte avec le pisiforme l’articulation sacro-ilium en dysfonction, la main céphalique est en contact avec le sillon delto-pectoral du membre supérieur sus-jacent.\n\nBARRIÈRE MOTRICE\nTracter dans l’axe vertébral le rachis du patient jusqu’à solliciter l’espace inter-épineux L5-S1. Inviter le patient à croiser les doigts sur son thorax. Majorer la flexion de la hanche du genou du côté à traiter jusqu’à solliciter l’articulation sacro-ilium en dysfonction. Stabiliser la position du membre inférieur homolatéral en plaçant le pied du patient dans la fosse poplitée du membre inférieur en rectitude, le genou reste en dehors de la table.\n\nNORMALISATION\nPorter le thrust sur la base sacrée à l’aide du pisiforme et simultanément sur le genou du patient dans l’axe de la cuisse pour obtenir une ouverture de l’articulation sacro-ilium.","detail":{"source":"OSTPRA1 - page 26","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en torsion postérieure avec le pisiforme direct, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus controlatéral à la dysfonction, le membre inférieur controlatéral est en extension, l’homolatéral est en légère flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur du pelvis du patient. La main caudale est placée sur l’espace inter-épineux L5-S1.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte avec le pisiforme l’articulation sacro-ilium en dysfonction, la main céphalique est en contact avec le sillon delto-pectoral du membre supérieur sus-jacent.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter dans l’axe vertébral le rachis du patient jusqu’à solliciter l’espace inter-épineux L5-S1. Inviter le patient à croiser les doigts sur son thorax. Majorer la flexion de la hanche du genou du côté à traiter jusqu’à solliciter l’articulation sacro-ilium en dysfonction. Stabiliser la position du membre inférieur homolatéral en plaçant le pied du patient dans la fosse poplitée du membre inférieur en rectitude, le genou reste en dehors de la table.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur la base sacrée à l’aide du pisiforme et simultanément sur le genou du patient dans l’axe de la cuisse pour obtenir une ouverture de l’articulation sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p026-dysfonction-du-sacrum-en-torsion-posterieure-avec-le-pisiforme-direct-a-gauc/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":26,"sourceRow":12}},{"slug":"ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche","sourceRow":13,"sourceBook":"OSTPRA1","sourcePage":28,"matchers":["dysfonction du sacrum en flexion unilaterale sur axe horizontal a gauche"],"title":"DYSFONCTION DU SACRUM, en flexion unilatérale sur axe horizontal, à gauche","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nContacter par le pisiforme de la main céphalique l’aileron inféro-latéral homolatéral à la dysfonction, la main caudale est superposée à la main céphalique.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur homolatéral en légère abduction, en rotation interne, pour ouvrir l’articulation sacro-ilium. Avant la manœuvre demander au sujet de tourner la tête du côté de la dysfonction.\n\nNORMALISATION\nMajorer la barrière motrice d’extension unilatérale du sacrum en augmentant la pression de la main caudale sur la main céphalique et porter un thrust en fin d’inspiration vers le bas et l’avant du sujet.","detail":{"source":"OSTPRA1 - page 28","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en flexion unilatérale sur axe horizontal, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main céphalique l’aileron inféro-latéral homolatéral à la dysfonction, la main caudale est superposée à la main céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur homolatéral en légère abduction, en rotation interne, pour ouvrir l’articulation sacro-ilium. Avant la manœuvre demander au sujet de tourner la tête du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer la barrière motrice d’extension unilatérale du sacrum en augmentant la pression de la main caudale sur la main céphalique et porter un thrust en fin d’inspiration vers le bas et l’avant du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p028-dysfonction-du-sacrum-en-flexion-unilaterale-sur-axe-horizontal-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":28,"sourceRow":13}},{"slug":"ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit","sourceRow":14,"sourceBook":"OSTPRA1","sourcePage":30,"matchers":["dysfonction du sacrum en torsion posterieure gauche sur axe oblique droit"],"title":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur axe oblique droit","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les mains derrière la tête, les doigts sont croisés et les coudes dirigés vers avant.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique fixe la position de la ceinture scapulaire par un appui sur la scapula. La main caudale placée sur l’épine ilium antéro-supérieure homolatérale ramène le pelvis au contact de la table\n\nBARRIÈRE MOTRICE\nDans un premier temps, amener une concavité opposée à la dysfonction par les membres inférieurs tendus en contrôlant L5-S1 jusqu’à son engagement. Dans un deuxième temps, amener la ceinture scapulaire du patient dans un plan perpendiculaire à la table. Exercer à partir de celle-ci une traction dans l’axe vertébral et la placer légèrement en retrait par rapport au pelvis. Fixer le pelvis contre la table avec la main caudale et majorer la traction et la rotation du tronc jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin d’expiration avec la main céphalique depuis la ceinture scapulaire par le levier supérieur en traction et en rotation.","detail":{"source":"OSTPRA1 - page 30","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur axe oblique droit","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les mains derrière la tête, les doigts sont croisés et les coudes dirigés vers avant.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique fixe la position de la ceinture scapulaire par un appui sur la scapula. La main caudale placée sur l’épine ilium antéro-supérieure homolatérale ramène le pelvis au contact de la table","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Dans un premier temps, amener une concavité opposée à la dysfonction par les membres inférieurs tendus en contrôlant L5-S1 jusqu’à son engagement. Dans un deuxième temps, amener la ceinture scapulaire du patient dans un plan perpendiculaire à la table. Exercer à partir de celle-ci une traction dans l’axe vertébral et la placer légèrement en retrait par rapport au pelvis. Fixer le pelvis contre la table avec la main caudale et majorer la traction et la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration avec la main céphalique depuis la ceinture scapulaire par le levier supérieur en traction et en rotation.","photo":"assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p030-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-axe-oblique-droit/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":30,"sourceRow":14}},{"slug":"ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m","sourceRow":15,"sourceBook":"OSTPRA1","sourcePage":32,"matchers":["dysfonction du sacrum en torsion anterieure droite sur axe droit e m"],"title":"DYSFONCTION DU SACRUM, en torsion antérieure droite sur axe droit (E.M.)","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée vers le\npraticien.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nMaintenir les chevilles par la main caudale, soutenir les cuisses du patient à l’aide de sa cuisse caudale, la main céphalique contrôle la sacro-ilium.\n\nBARRIÈRE MOTRICE\nInviter le patient à faire une extension des membres inférieurs en maintenant de son avant-bras caudale les chevilles du patient afin de les décoller du plan de la table dans le but de glisser son avant-bras céphalique en regard du 1/3 inférieur des cuisses du patient. Effectuer une traction des genoux du patient vers le dehors de la table afin de placer le pelvis du patient à 90° sur la table, le buste restant installé sur la table en procubitus.\n\nNORMALISATION\nInviter le patient à lever les pieds vers le plafond pendant 10 à 12 secondes, contre résistance, en contrôlant la sacro-ilium. Au relâchement chercher une nouvelle barrière motrice par un abaissement des pieds vers le sol – à répéter 3 fois.","detail":{"source":"OSTPRA1 - page 32","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DU SACRUM, en torsion antérieure droite sur axe droit (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée vers le\npraticien.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Maintenir les chevilles par la main caudale, soutenir les cuisses du patient à l’aide de sa cuisse caudale, la main céphalique contrôle la sacro-ilium.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le patient à faire une extension des membres inférieurs en maintenant de son avant-bras caudale les chevilles du patient afin de les décoller du plan de la table dans le but de glisser son avant-bras céphalique en regard du 1/3 inférieur des cuisses du patient. Effectuer une traction des genoux du patient vers le dehors de la table afin de placer le pelvis du patient à 90° sur la table, le buste restant installé sur la table en procubitus.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à lever les pieds vers le plafond pendant 10 à 12 secondes, contre résistance, en contrôlant la sacro-ilium. Au relâchement chercher une nouvelle barrière motrice par un abaissement des pieds vers le sol – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p032-dysfonction-du-sacrum-en-torsion-anterieure-droite-sur-axe-droit-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":32,"sourceRow":15}},{"slug":"ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m","sourceRow":16,"sourceBook":"OSTPRA1","sourcePage":34,"matchers":["dysfonction du sacrum en torsion posterieure gauche sur un axe droit e m"],"title":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur un axe droit (E.M.)","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus couché sur l’axe en dysfonction du sacrum.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main céphalique contrôle l’articulation sacro-ilium au niveau de son sillon. La main caudale est en contact avec la face externe de la cuisse sus-jacente.\n\nBARRIÈRE MOTRICE\nExercer une traction du tronc dans l’axe vertébral et amener en légère lordose lombaire. Tracter le membre supérieur sur la table vers le haut et l’avant du sujet de façon à déroter le sujet jusqu’à L5-S1. Demander au patient de croiser ses bras. Faire glisser le membre inférieur sur la table jusqu’à la barrière motrice en extension. Amener le membre inférieur opposé à la table en flexion et en adduction de hanche, en gardant le genou tendu jusqu’à la barrière motrice.\n\nNORMALISATION\nInviter le patient à pousser le genou opposé à la table vers le plafond contre résistance pendant 10 à 12 secondes. Au relâchement, chercher la nouvelle barrière motrice en abaissement du membre inférieur – à répéter 3 fois.","detail":{"source":"OSTPRA1 - page 34","category":"Pelvis – sacro-ilium","method":"Énergie musculaire","intro":"DYSFONCTION DU SACRUM, en torsion postérieure gauche sur un axe droit (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus couché sur l’axe en dysfonction du sacrum.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique contrôle l’articulation sacro-ilium au niveau de son sillon. La main caudale est en contact avec la face externe de la cuisse sus-jacente.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral et amener en légère lordose lombaire. Tracter le membre supérieur sur la table vers le haut et l’avant du sujet de façon à déroter le sujet jusqu’à L5-S1. Demander au patient de croiser ses bras. Faire glisser le membre inférieur sur la table jusqu’à la barrière motrice en extension. Amener le membre inférieur opposé à la table en flexion et en adduction de hanche, en gardant le genou tendu jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le patient à pousser le genou opposé à la table vers le plafond contre résistance pendant 10 à 12 secondes. Au relâchement, chercher la nouvelle barrière motrice en abaissement du membre inférieur – à répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p034-dysfonction-du-sacrum-en-torsion-posterieure-gauche-sur-un-axe-droit-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":34,"sourceRow":16}},{"slug":"ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme","sourceRow":17,"sourceBook":"OSTPRA1","sourcePage":36,"matchers":["dysfonction du sacrum en anteriorite unilaterale manoeuvre avec le pisiforme directe sur l aileron infero lateral a gauche"],"title":"DYSFONCTION DU SACRUM, en antériorité unilatérale. Manœuvre avec le pisiforme directe sur l’aileron inféro-latéral, à gauche","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main céphalique est posée sur le sillon delto-pectoral, la main caudale contacte par le pisiforme l’aileron inféro-latéral opposé à la table.\n\nBARRIÈRE MOTRICE\nExercer une traction du tronc dans l’axe vertébral. Tracter le membre supérieur sur la table de façon à déroter le tronc du patient jusqu’à L5-S1. Demander une rotation de la tête vers le plafond. Le membre inférieur sur la table est amené en extension, le membre inférieur opposé à la table est en flexion, le pied fixé dans la fosse poplitée.\n\nNORMALISATION\nPorter le thrust avec le pisiforme en direction céphalique.","detail":{"source":"OSTPRA1 - page 36","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en antériorité unilatérale. Manœuvre avec le pisiforme directe sur l’aileron inféro-latéral, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur le sillon delto-pectoral, la main caudale contacte par le pisiforme l’aileron inféro-latéral opposé à la table.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une traction du tronc dans l’axe vertébral. Tracter le membre supérieur sur la table de façon à déroter le tronc du patient jusqu’à L5-S1. Demander une rotation de la tête vers le plafond. Le membre inférieur sur la table est amené en extension, le membre inférieur opposé à la table est en flexion, le pied fixé dans la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec le pisiforme en direction céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p036-dysfonction-du-sacrum-en-anteriorite-unilaterale-manoeuvre-avec-le-pisiforme/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":36,"sourceRow":17}},{"slug":"ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite","sourceRow":18,"sourceBook":"OSTPRA1","sourcePage":38,"matchers":["dysfonction du sacrum en extension unilaterale sur axe horizontal a droite"],"title":"DYSFONCTION DU SACRUM, en extension unilatérale sur axe horizontal, à droite","zone":"Bassin","sub":"Sacrum","level":"Niveau intermédiaire","status":"non vue","icon":"S","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus la tête tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nContacter, avec le pisiforme de la main caudale, la base sacrée en dysfonction par un mouvement de « pas de vis » en direction céphalique. Renforcer la pression de la main caudale par la main céphalique.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur du côté de la dysfonction en légère abduction et en rotation interne. Amener une pression sur la zone sous-facettaire vers la table jusqu’à la barrière motrice en flexion. Demander au patient de tourner la tête du côté opposé à la dysfonction.\n\nNORMALISATION\nPorter le thrust vers la flexion du sacrum en direction de la table.","detail":{"source":"OSTPRA1 - page 38","category":"Pelvis – sacro-ilium","method":"Thrust","intro":"DYSFONCTION DU SACRUM, en extension unilatérale sur axe horizontal, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus la tête tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter, avec le pisiforme de la main caudale, la base sacrée en dysfonction par un mouvement de « pas de vis » en direction céphalique. Renforcer la pression de la main caudale par la main céphalique.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en légère abduction et en rotation interne. Amener une pression sur la zone sous-facettaire vers la table jusqu’à la barrière motrice en flexion. Demander au patient de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers la flexion du sacrum en direction de la table.","photo":"assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p038-dysfonction-du-sacrum-en-extension-unilaterale-sur-axe-horizontal-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":38,"sourceRow":18}},{"slug":"ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m","sourceRow":19,"sourceBook":"OSTPRA1","sourcePage":40,"matchers":["dysfonction de la symphyse pubienne en superiorite a droite e m"],"title":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en supériorité à droite (E.M.)","zone":"Bassin","sub":"Symphyse pubienne","level":"Niveau intermédiaire","status":"non vue","icon":"SP","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal. Le membre inférieur homolatéral à la dysfonction est en dehors de la table et est maintenu entre les jambes du\npraticien.\nPRATICIEN Debout à la hauteur du pelvis les épaules sont dirigées vers la tête du sujet, du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume l’épine iliaque antéro-supérieure controlatérale. La main homolatérale à la dysfonction enserre la face antérieure et distale de la cuisse.\n\nBARRIÈRE MOTRICE\nMajorer l’extension de la hanche jusqu’à la barrière motrice de la symphyse pubienne.\n\nNORMALISATION\nInviter le sujet à fléchir la hanche en lui demandant de pousser le genou vers le plafond pendant 10 à 12 secondes et s’y opposer – À répéter trois fois.","detail":{"source":"OSTPRA1 - page 40","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en supériorité à droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. Le membre inférieur homolatéral à la dysfonction est en dehors de la table et est maintenu entre les jambes du\npraticien.\nPRATICIEN Debout à la hauteur du pelvis les épaules sont dirigées vers la tête du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’épine iliaque antéro-supérieure controlatérale. La main homolatérale à la dysfonction enserre la face antérieure et distale de la cuisse.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer l’extension de la hanche jusqu’à la barrière motrice de la symphyse pubienne.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fléchir la hanche en lui demandant de pousser le genou vers le plafond pendant 10 à 12 secondes et s’y opposer – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p040-dysfonction-de-la-symphyse-pubienne-en-superiorite-a-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":40,"sourceRow":19}},{"slug":"ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m","sourceRow":20,"sourceBook":"OSTPRA1","sourcePage":42,"matchers":["dysfonction de la symphyse pubienne en inferiorite a gauche e m"],"title":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en infériorité à gauche (E.M.)","zone":"Bassin","sub":"Symphyse pubienne","level":"Niveau intermédiaire","status":"non vue","icon":"SP","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, le membre inférieur homolatéral à la dysfonction est en flexion.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique saisit le bord opposé de la table. Le creux axillaire homolatéral est en appui sur le genou du sujet, homolatéral à la dysfonction. La main caudale, poing fermé, forme un coin sous la tubérosité ischiatique du sujet du côté de la dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur du côté de la dysfonction en flexion sur le thorax. Majorer la flexion de hanche jusqu’à la barrière motrice.\n\nNORMALISATION\nInviter le sujet à effectuer une extension de hanche et s’y opposer. Rechercher ensuite la nouvelle barrière motrice vers la flexion en s’aidant du coin constitué par la main caudale – À répéter 3 fois.","detail":{"source":"OSTPRA1 - page 42","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION DE LA SYMPHYSE PUBIENNE, en infériorité à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le membre inférieur homolatéral à la dysfonction est en flexion.\nPRATICIEN Debout à la hauteur du pelvis du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique saisit le bord opposé de la table. Le creux axillaire homolatéral est en appui sur le genou du sujet, homolatéral à la dysfonction. La main caudale, poing fermé, forme un coin sous la tubérosité ischiatique du sujet du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur du côté de la dysfonction en flexion sur le thorax. Majorer la flexion de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une extension de hanche et s’y opposer. Rechercher ensuite la nouvelle barrière motrice vers la flexion en s’aidant du coin constitué par la main caudale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p042-dysfonction-de-la-symphyse-pubienne-en-inferiorite-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":42,"sourceRow":20}},{"slug":"ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e","sourceRow":21,"sourceBook":"OSTPRA1","sourcePage":44,"matchers":["dysfonction combinee de la symphyse pubienne en superiorite et inferiorite e m"],"title":"DYSFONCTION COMBINÉE DE LA SYMPHYSE PUBIENNE, en supériorité et infériorité (E.M.)","zone":"Bassin","sub":"Symphyse pubienne","level":"Niveau intermédiaire","status":"non vue","icon":"SP","video":"","headerImage":"assets/images/zones/zone-bassin.webp","image":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les genoux sont fléchis les pieds sont posés sur la table.\nPRATICIEN Assis sur les pieds du sujet, les épaules sont dirigées vers la tête du sujet.\n\nPOSITION DES MAINS\nDans un premier temps, empaumer la face externe des genoux joints. Puis, dans un deuxième temps, placer les avant-bras entre les genoux.\n\nBARRIÈRE MOTRICE\nMaintenir les deux genoux accolés.\n\nNORMALISATION\nInviter le sujet à effectuer une abduction des hanches et s’y opposer. Relâcher soudainement la pression sur les genoux et bloquer l’abduction des hanches par les coudes – À répéter 3 fois. Puis, intercaler l’avant-bras entre les genoux, demander une adduction, libérer vivement l’avant-bras et bloquer les deux genoux par le coude.","detail":{"source":"OSTPRA1 - page 44","category":"Pelvis – symphyse pubienne","method":"Énergie musculaire","intro":"DYSFONCTION COMBINÉE DE LA SYMPHYSE PUBIENNE, en supériorité et infériorité (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les genoux sont fléchis les pieds sont posés sur la table.\nPRATICIEN Assis sur les pieds du sujet, les épaules sont dirigées vers la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Dans un premier temps, empaumer la face externe des genoux joints. Puis, dans un deuxième temps, placer les avant-bras entre les genoux.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir les deux genoux accolés.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une abduction des hanches et s’y opposer. Relâcher soudainement la pression sur les genoux et bloquer l’abduction des hanches par les coudes – À répéter 3 fois. Puis, intercaler l’avant-bras entre les genoux, demander une adduction, libérer vivement l’avant-bras et bloquer les deux genoux par le coude.","photo":"assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p044-dysfonction-combinee-de-la-symphyse-pubienne-en-superiorite-et-inferiorite-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":44,"sourceRow":21}},{"slug":"ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite","sourceRow":22,"sourceBook":"OSTPRA1","sourcePage":46,"matchers":["dysfonction facettaire des lombaires en nsr a droite"],"title":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en NSR à droite","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main caudale est en contact avec l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse gauche. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur sus-jacent en extension. Le membre inférieur sous-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous-jacent jusqu’à solliciter l’espace inter-épineux concerné. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.\n\nNORMALISATION\nExercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Porter le thrust sur la phase expiratoire.","detail":{"source":"OSTPRA1 - page 46","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en NSR à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale est en contact avec l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse gauche. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en extension. Le membre inférieur sous-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous-jacent jusqu’à solliciter l’espace inter-épineux concerné. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Porter le thrust sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p046-dysfonction-facettaire-des-lombaires-en-nsr-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":46,"sourceRow":22}},{"slug":"ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite","sourceRow":23,"sourceBook":"OSTPRA1","sourcePage":48,"matchers":["dysfonction facettaire des lombaires en ers a droite"],"title":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en ERS à droite","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.\n\nBARRIÈRE MOTRICE\nAmener le genou sous-jacent en extension et maintenir une légère flexion de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent en rotation du tronc jusqu’à solliciter l’espace inter-épineux concerné. Ajouter une composante de flexion du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.\n\nNORMALISATION\nExercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire.","detail":{"source":"OSTPRA1 - page 48","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en ERS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus-jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou sous-jacent en extension et maintenir une légère flexion de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent en rotation du tronc jusqu’à solliciter l’espace inter-épineux concerné. Ajouter une composante de flexion du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens de la rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p048-dysfonction-facettaire-des-lombaires-en-ers-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":48,"sourceRow":23}},{"slug":"ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite","sourceRow":24,"sourceBook":"OSTPRA1","sourcePage":50,"matchers":["dysfonction facettaire des lombaires en frs a droite"],"title":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en FRS à droite","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus‑jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur sous‑jacent en rectitude avec une extension de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent jusqu’à solliciter l’espace inter‑épineux concerné. Ajouter une composante d’extension du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.\n\nNORMALISATION\nExercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens d’une rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire,","detail":{"source":"OSTPRA1 - page 50","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, en FRS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus, la dysfonction est sur la table, les membres inférieurs sont fléchis.\nPRATICIEN Debout face au sujet à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale contacte l’espace inter-épineux concerné. L’avant-bras est en appui sur la partie supéro-postérieure de la fesse sus-jacente. La main céphalique se glisse dans l’anneau formé par le membre supérieur sus-jacent du sujet et vient palper la vertèbre sus‑jacente à la dysfonction. L’avant-bras céphalique est posé au niveau du sillon delto-pectoral sus-jacent et fixe la rotation du tronc.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sous‑jacent en rectitude avec une extension de hanche. Le membre inférieur sus-jacent est en flexion, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent jusqu’à solliciter l’espace inter‑épineux concerné. Ajouter une composante d’extension du tronc. Basculer le sujet à la verticale du thorax du praticien. Majorer la rotation du tronc jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur l’épineuse de la vertèbre en dysfonction dans le sens d’une rotation gauche. Maintenir les leviers du tronc en rotation du pelvis par une majoration des leviers inférieurs sous les leviers supérieurs et porter le thrust sur la phase expiratoire,","photo":"assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p050-dysfonction-facettaire-des-lombaires-en-frs-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":50,"sourceRow":24}},{"slug":"ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche","sourceRow":25,"sourceBook":"OSTPRA1","sourcePage":52,"matchers":["dysfonction facettaire des lombaires assis a gauche"],"title":"DYSFONCTION FACETTAIRE DES LOMBAIRES, assis, à gauche","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT Assis à califourchon sur la table. Le patient met sa main opposée à la dysfonction sur son épaule homolatérale à la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN La table est en position basse, le\npraticien est assis à califourchon dans le dos du sujet légèrement du coté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique du praticien contacte l’épaule opposée du patient. Le pisiforme de la main caudale contacte la transverse de la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le thorax en légère flexion, en rotation et en inclinaison droite jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la rotation opposée à la dysfonction sur la phase expiratoire.","detail":{"source":"OSTPRA1 - page 52","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION FACETTAIRE DES LOMBAIRES, assis, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table. Le patient met sa main opposée à la dysfonction sur son épaule homolatérale à la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN La table est en position basse, le\npraticien est assis à califourchon dans le dos du sujet légèrement du coté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien contacte l’épaule opposée du patient. Le pisiforme de la main caudale contacte la transverse de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en légère flexion, en rotation et en inclinaison droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation opposée à la dysfonction sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p052-dysfonction-facettaire-des-lombaires-assis-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":52,"sourceRow":25}},{"slug":"ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m","sourceRow":26,"sourceBook":"OSTPRA1","sourcePage":54,"matchers":["dysfonction des lombaires en nsr a gauche e m"],"title":"DYSFONCTION DES LOMBAIRES, en NSR à gauche (E.M.)","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus du côté opposée à la dysfonction. Les genoux et les hanches sont fléchis à 90°. La main du membre supérieur sus-jacent attrape le bord supérieur de la table.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nContacter par la main céphalique la vertèbre en dysfonction. La main caudale soutient les chevilles.\n\nBARRIÈRE MOTRICE\nLever vers le plafond les chevilles de façon à corriger la latéroflexion lombaire jusqu’au niveau concerné.\n\nNORMALISATION\nDemander au sujet d’abaisser les pieds vers le sol et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par l’élévation des pieds – À répéter trois fois.","detail":{"source":"OSTPRA1 - page 54","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"DYSFONCTION DES LOMBAIRES, en NSR à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposée à la dysfonction. Les genoux et les hanches sont fléchis à 90°. La main du membre supérieur sus-jacent attrape le bord supérieur de la table.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique la vertèbre en dysfonction. La main caudale soutient les chevilles.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Lever vers le plafond les chevilles de façon à corriger la latéroflexion lombaire jusqu’au niveau concerné.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’abaisser les pieds vers le sol et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par l’élévation des pieds – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p054-dysfonction-des-lombaires-en-nsr-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":54,"sourceRow":26}},{"slug":"ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m","sourceRow":27,"sourceBook":"OSTPRA1","sourcePage":56,"matchers":["dysfonction des lombaires en ers a gauche e m"],"title":"DYSFONCTION DES LOMBAIRES, en ERS à gauche (E.M.)","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/planche-photos.webp","text":"POSITION\nPATIENT En procubitus. La tête est tournée du côté de la dysfonction. Les hanches et genoux sont amenés par le\npraticien en flexion à 90° en dehors de la table. Le bras opposé à la dysfonction est le long de la table. Le bras homolatéral est pendant en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nContacter par la main céphalique l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale soutient les chevilles.\n\nBARRIÈRE MOTRICE\nAmener en flexion les hanches et s’arrêter juste avant d’entraîner la vertèbre en dysfonction. Demander au sujet de pousser le membre supérieur en dehors de la table vers le sol. Amener les pieds vers le sol et s’arrêter juste avant d’entraîner la vertèbre en dysfonction.\n\nNORMALISATION\nDemander au sujet de lever les pieds vers le plafond et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par abaissement des pieds et flexion des hanches. Demander au sujet de glisser le membre supérieur posé sur la table vers ses pieds, et le membre supérieur en dehors de la table vers le sol – À répéter trois fois.","detail":{"source":"OSTPRA1 - page 56","category":"Lombaire – lombaire","method":"Énergie musculaire","intro":"DYSFONCTION DES LOMBAIRES, en ERS à gauche (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus. La tête est tournée du côté de la dysfonction. Les hanches et genoux sont amenés par le\npraticien en flexion à 90° en dehors de la table. Le bras opposé à la dysfonction est le long de la table. Le bras homolatéral est pendant en dehors de la table.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la main céphalique l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale soutient les chevilles.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener en flexion les hanches et s’arrêter juste avant d’entraîner la vertèbre en dysfonction. Demander au sujet de pousser le membre supérieur en dehors de la table vers le sol. Amener les pieds vers le sol et s’arrêter juste avant d’entraîner la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de lever les pieds vers le plafond et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par abaissement des pieds et flexion des hanches. Demander au sujet de glisser le membre supérieur posé sur la table vers ses pieds, et le membre supérieur en dehors de la table vers le sol – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p056-dysfonction-des-lombaires-en-ers-a-gauche-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":56,"sourceRow":27}},{"slug":"ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite","sourceRow":28,"sourceBook":"OSTPRA1","sourcePage":58,"matchers":["dysfonction des lombaires en frs a droite"],"title":"DYSFONCTION DES LOMBAIRES, en FRS à droite","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus du côté de la dysfonction. La tête est tournée vers le haut. Le membre inférieur sous‑jacent est amené en extension. Le membre inférieur sus‑jacent est en extension de hanche, genoux à 90°.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nLa main céphalique est posée sur l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale saisit la jambe sus-jacente du patient.\n\nBARRIÈRE MOTRICE\nTracter le membre supérieur sous-jacent pour engendrer une rotation du tronc. Demander au sujet de maintenir cette position en saisissant le bord opposé de la table avec sa main. Amener la hanche sus-jacente en rotation interne, en extension et en abduction. S’arrêter juste avant d’entraîner dans ce mouvement la vertèbre en dysfonction.\n\nNORMALISATION\nInviter le sujet à faire une flexion de hanche gauche et s’y opposer, pendant 10 à 12 secondes. Puis, au relâchement rechercher de la nouvelle barrière motrice par une extension de la hanche – À répéter trois fois. Puis, inviter le sujet à faire une adduction de la hanche et s’y opposer. Au relâchement, chercher la nouvelle barrière motrice par une abduction de la hanche – À répéter trois fois.","detail":{"source":"OSTPRA1 - page 58","category":"Lombaire – lombaire","method":"Mobilisation","intro":"DYSFONCTION DES LOMBAIRES, en FRS à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté de la dysfonction. La tête est tournée vers le haut. Le membre inférieur sous‑jacent est amené en extension. Le membre inférieur sus‑jacent est en extension de hanche, genoux à 90°.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique est posée sur l’espace inter-épineux sous-jacent à la vertèbre en dysfonction. La main caudale saisit la jambe sus-jacente du patient.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le membre supérieur sous-jacent pour engendrer une rotation du tronc. Demander au sujet de maintenir cette position en saisissant le bord opposé de la table avec sa main. Amener la hanche sus-jacente en rotation interne, en extension et en abduction. S’arrêter juste avant d’entraîner dans ce mouvement la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à faire une flexion de hanche gauche et s’y opposer, pendant 10 à 12 secondes. Puis, au relâchement rechercher de la nouvelle barrière motrice par une extension de la hanche – À répéter trois fois. Puis, inviter le sujet à faire une adduction de la hanche et s’y opposer. Au relâchement, chercher la nouvelle barrière motrice par une abduction de la hanche – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p058-dysfonction-des-lombaires-en-frs-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":58,"sourceRow":28}},{"slug":"ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui","sourceRow":29,"sourceBook":"OSTPRA1","sourcePage":60,"matchers":["dysfonction de la charniere d12 l1 technique en double appui"],"title":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique en double appui","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal. Les membres supérieurs sont croisées sur le thorax. La main gauche est sur l’épaule droite et la main droite est sur l’épaule gauche. Les coudes sont superposés, le coude droit est au dessus de l’autre.\nPRATICIEN Debout à la hauteur du pelvis, les épaules sont orientées vers la tête du patient.\n\nPOSITION DES MAINS\nLa main céphalique soutient le thorax et la tête. La main caudale par un double appui (éminence thénar et 2 e phalanges des 4 derniers doigts) est en regard des apophyses transverses de la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le sujet en flexion du tronc puis amener le sujet au contact de la main du praticien en allongeant le patient sur la table.\n\nNORMALISATION\nExercer une pression sur les coudes jusqu’à la barrière motrice. Le thrust sera porté au passage de la vertèbre en dysfonction sur le double contact de la main applicatrice du praticien sur la phase expiratoire.","detail":{"source":"OSTPRA1 - page 60","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal. Les membres supérieurs sont croisées sur le thorax. La main gauche est sur l’épaule droite et la main droite est sur l’épaule gauche. Les coudes sont superposés, le coude droit est au dessus de l’autre.\nPRATICIEN Debout à la hauteur du pelvis, les épaules sont orientées vers la tête du patient.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique soutient le thorax et la tête. La main caudale par un double appui (éminence thénar et 2 e phalanges des 4 derniers doigts) est en regard des apophyses transverses de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le sujet en flexion du tronc puis amener le sujet au contact de la main du praticien en allongeant le patient sur la table.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice. Le thrust sera porté au passage de la vertèbre en dysfonction sur le double contact de la main applicatrice du praticien sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p060-dysfonction-de-la-charniere-d12-l1-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":60,"sourceRow":29}},{"slug":"ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro","sourceRow":30,"sourceBook":"OSTPRA1","sourcePage":62,"matchers":["dysfonction de la charniere d12 l1 technique indirecte a droite en lumbar roll"],"title":"DYSFONCTION DE LA CHARNIÈRE D12/L1, technique indirecte à droite en « Lumbar Roll »","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/planche-photos.webp","text":"VERIFIER LE CÔTÉ DE LA POSTÉRIORITÉ\n\nPOSITION\nPATIENT En latérocubitus droit.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nL’avant-bras caudal contacte la face postéro-externe de la fesse sus-jacente du patient. La main caudale contacte la zone en dysfonction. L’avant-bras céphalique contacte le sillon delto‑pectoral sus-jacent du patient, la main céphalique est sur la zone en dysfonction.\n\nBARRIÈRE MOTRICE\nLe membre inférieur sous-jacent est amené en extension. Le membre inférieur sus-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.\n\nNORMALISATION\nAmener le levier supérieur en rotation jusqu’à la zone en dysfonction. Amener le levier inférieur en rotation opposée. Fixer les leviers en amenant le sujet sous le praticien. Porter le thrust en exagération du levier inférieur sous le levier supérieur sur la phase expiratoire.","detail":{"source":"OSTPRA1 - page 62","category":"Lombaire – lombaire","method":"Thrust","intro":"NOTE : VERIFIER LE CÔTÉ DE LA POSTÉRIORITÉ\nDYSFONCTION DE LA CHARNIÈRE D12/L1, technique indirecte à droite en « Lumbar Roll »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus droit.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"L’avant-bras caudal contacte la face postéro-externe de la fesse sus-jacente du patient. La main caudale contacte la zone en dysfonction. L’avant-bras céphalique contacte le sillon delto‑pectoral sus-jacent du patient, la main céphalique est sur la zone en dysfonction.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sus-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sous‑jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener le levier supérieur en rotation jusqu’à la zone en dysfonction. Amener le levier inférieur en rotation opposée. Fixer les leviers en amenant le sujet sous le praticien. Porter le thrust en exagération du levier inférieur sous le levier supérieur sur la phase expiratoire.","photo":"assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p062-dysfonction-de-la-charniere-d12-l1-technique-indirecte-a-droite-en-lumbar-ro/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":62,"sourceRow":30}},{"slug":"ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll","sourceRow":31,"sourceBook":"OSTPRA1","sourcePage":64,"matchers":["dysfonction de l3 technique semi directe a gauche en lumbar roll"],"title":"DYSFONCTION DE L3, technique semi-directe à gauche en « Lumbar Roll »","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus la postériorité de la vertèbre est positionnée vers le haut.\nPRATICIEN Debout à la hauteur du pelvis.\n\nPOSITION DES MAINS\nL’index de la main caudale contacte la transverse de la vertèbre en dysfonction. La main céphalique maintient les poignets du patient.\n\nBARRIÈRE MOTRICE\nLe membre inférieur sous-jacent est amené en extension. Le membre inférieur sous-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sus-jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.\n\nNORMALISATION\nPorter le thrust par la main caudale en exagérant le levier de rotation.","detail":{"source":"OSTPRA1 - page 64","category":"Lombaire – lombaire","method":"Thrust","intro":"DYSFONCTION DE L3, technique semi-directe à gauche en « Lumbar Roll »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus la postériorité de la vertèbre est positionnée vers le haut.\nPRATICIEN Debout à la hauteur du pelvis.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"L’index de la main caudale contacte la transverse de la vertèbre en dysfonction. La main céphalique maintient les poignets du patient.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le membre inférieur sous-jacent est amené en extension. Le membre inférieur sous-jacent est en flexion de hanche et de genou, la cheville est calée dans la fosse poplitée. Tracter le membre supérieur sus-jacent pour ramener le thorax en rotation jusqu’à l’étage concerné. Demander au sujet de tenir ses poignets pour fixer la position.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en exagérant le levier de rotation.","photo":"assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p064-dysfonction-de-l3-technique-semi-directe-a-gauche-en-lumbar-roll/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":64,"sourceRow":31}},{"slug":"ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche","sourceRow":32,"sourceBook":"OSTPRA1","sourcePage":66,"matchers":["charniere d12 l1 technique en lift posteriorite a gauche"],"title":"CHARNIÈRE D12/L1, technique en « Lift », postériorité à gauche","zone":"Rachis","sub":"Lombaires","level":"Niveau intermédiaire","status":"non vue","icon":"L","video":"","headerImage":"assets/images/zones/zone-lombaires.webp","image":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT Assis à califourchon sur la table, les pieds sont posés au sol. La face dorsale de la métacarpo-phalangienne de l’index de la main du côté de la dysfonction contacte la transverse postérieure. La main est ouverte, le pouce est dirigé vers le haut. L’autre main est superposée de la même manière.\nPRATICIEN Assis à califourchon derrière du sujet, les pieds sont posés au sol.\n\nPOSITION DES MAINS\nPasser le membre supérieur sous le bras du sujet pour fixer le thorax et l’abdomen. La main opposée à la dysfonction contacte l’arrière de la tête pour contrôler la flexion du tronc. Le contacteur représenter par le sternum du praticien est au contact sur les mains du sujet.\n\nBARRIÈRE MOTRICE\nAmener de thorax en flexion jusqu’au niveau de la dysfonction. Fixer la position des leviers par le contact sternal. Amener dans un mouvement en virgule le thorax en compression vers le praticien puis le tracter vers le haut dans un mouvement de décoaptation.\n\nNORMALISATION\nPorter le thrust dans un mouvement de traction verticale (lift) lors de l’expiration.","detail":{"source":"OSTPRA1 - page 66","category":"Lombaire – lombaire","method":"Lift","intro":"CHARNIÈRE D12/L1, technique en « Lift », postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis à califourchon sur la table, les pieds sont posés au sol. La face dorsale de la métacarpo-phalangienne de l’index de la main du côté de la dysfonction contacte la transverse postérieure. La main est ouverte, le pouce est dirigé vers le haut. L’autre main est superposée de la même manière.\nPRATICIEN Assis à califourchon derrière du sujet, les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Passer le membre supérieur sous le bras du sujet pour fixer le thorax et l’abdomen. La main opposée à la dysfonction contacte l’arrière de la tête pour contrôler la flexion du tronc. Le contacteur représenter par le sternum du praticien est au contact sur les mains du sujet.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener de thorax en flexion jusqu’au niveau de la dysfonction. Fixer la position des leviers par le contact sternal. Amener dans un mouvement en virgule le thorax en compression vers le praticien puis le tracter vers le haut dans un mouvement de décoaptation.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans un mouvement de traction verticale (lift) lors de l’expiration.","photo":"assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra1-p066-charniere-d12-l1-technique-en-lift-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA1","sourcePage":66,"sourceRow":32}},{"slug":"ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui","sourceRow":33,"sourceBook":"OSTPRA2","sourcePage":6,"matchers":["dysfonction facettaire des dorsales en flexion technique en double appui"],"title":"Dysfonction facettaire des dorsaleS, en flexion, technique en double appui","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.\n\nPOSITION DES MAINS\nAmener le tronc du sujet vers soi de façon à localiser par la main caudale la vertèbre en dysfonction. Placer les transverses des vertèbres en dysfonction entre son éminence thénar et ses doigts fléchis, le pouce est dans l’axe vertébral en direction de la tête du sujet. Puis maintenir par la main céphalique et le thorax les coudes et le thorax du sujet.\n\nBARRIÈRE MOTRICE\nExercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin d’inspiration vers la table.","detail":{"source":"OSTPRA2 - page 6","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire des dorsaleS, en flexion, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet vers soi de façon à localiser par la main caudale la vertèbre en dysfonction. Placer les transverses des vertèbres en dysfonction entre son éminence thénar et ses doigts fléchis, le pouce est dans l’axe vertébral en direction de la tête du sujet. Puis maintenir par la main céphalique et le thorax les coudes et le thorax du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’inspiration vers la table.","photo":"assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p006-dysfonction-facettaire-des-dorsales-en-flexion-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":6,"sourceRow":33}},{"slug":"ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui","sourceRow":34,"sourceBook":"OSTPRA2","sourcePage":8,"matchers":["dysfonction facettaire des dorsales en extension technique en double appui"],"title":"Dysfonction facettaire des dorsales, en extension, technique en double appui","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.\n\nPOSITION DES MAINS\nAmener le tronc du sujet de façon à localiser par la main caudale la vertèbre en dysfonction. Puis, contacter les transverses des vertèbres en dysfonction par l’éminence thénar et les phalangines de la main caudale, le pouce est dans l’axe vertébral vers la tête du sujet. La main et l’avant-bras céphalique soulèvent et soutiennent la tête et le rachis dorsal haut. Le sternum du praticien contacte les coudes du sujet.\n\nBARRIÈRE MOTRICE\nExercer une pression sur les coudes jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction de la table dans un mouvement de virgule vers la tête du sujet, en fin d’expiration.","detail":{"source":"OSTPRA2 - page 8","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire des dorsales, en extension, technique en double appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax les coudes sont superposés. Le coude côté\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la vertèbre en dysfonction. Puis, contacter les transverses des vertèbres en dysfonction par l’éminence thénar et les phalangines de la main caudale, le pouce est dans l’axe vertébral vers la tête du sujet. La main et l’avant-bras céphalique soulèvent et soutiennent la tête et le rachis dorsal haut. Le sternum du praticien contacte les coudes du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table dans un mouvement de virgule vers la tête du sujet, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p008-dysfonction-facettaire-des-dorsales-en-extension-technique-en-double-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":8,"sourceRow":34}},{"slug":"ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui","sourceRow":35,"sourceBook":"OSTPRA2","sourcePage":10,"matchers":["dysfonction facettaire des dorsales technique en simple appui"],"title":"Dysfonction facettaire DES dorsaleS, technique en simple appui","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude du côté du\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.\n\nPOSITION DES MAINS\nContacter la transverse en postériorité de la vertèbre en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral en direction de la tête, la main reste à plat. Verrouiller les coudes du sujet par un appui sternal.\n\nBARRIÈRE MOTRICE\nExercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin d’expiration vers le plan de la table.","detail":{"source":"OSTPRA2 - page 10","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire DES dorsaleS, technique en simple appui","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les avant-bras sont croisés sur le thorax, les coudes sont superposés. Le coude du côté du\npraticien est placé au dessus de l’autre.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter la transverse en postériorité de la vertèbre en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral en direction de la tête, la main reste à plat. Verrouiller les coudes du sujet par un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une pression sur les coudes en direction de la main applicatrice jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin d’expiration vers le plan de la table.","photo":"assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p010-dysfonction-facettaire-des-dorsales-technique-en-simple-appui/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":10,"sourceRow":35}},{"slug":"ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite","sourceRow":36,"sourceBook":"OSTPRA2","sourcePage":12,"matchers":["dysfonction facettaire des dorsales avec les pisiformes croises posteriorite a droite"],"title":"Dysfonction facettaire DES dorsaleS, avec les pisiformes croisés, postériorité à droite","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/planche-photos.webp","text":"POSITION\nSUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.\n\nPOSITION DES MAINS\nContacter par le pisiforme de la main caudale l’apophyse transverse en postériorité de la vertèbre en dysfonction. Contacter par le pisiforme de la main céphalique l’apophyse transverse de la vertèbre sous-jacente en créant ainsi un contre appui.\n\nBARRIÈRE MOTRICE\nEn se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.\n\nNORMALISATION\nPorter le thrust par la main caudale en fin d’expiration, en direction de la tête du sujet et du sol, dans le plan des facettes articulaires.","detail":{"source":"OSTPRA2 - page 12","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire DES dorsaleS, avec les pisiformes croisés, postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité de la vertèbre en dysfonction. Contacter par le pisiforme de la main céphalique l’apophyse transverse de la vertèbre sous-jacente en créant ainsi un contre appui.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale en fin d’expiration, en direction de la tête du sujet et du sol, dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p012-dysfonction-facettaire-des-dorsales-avec-les-pisiformes-croises-posteriorite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":12,"sourceRow":36}},{"slug":"ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori","sourceRow":37,"sourceBook":"OSTPRA2","sourcePage":14,"matchers":["dysfonction facettaire des dorsales technique en pisiforme simple posteriorite a droite"],"title":"Dysfonction facettaire Des dorsales, technique en pisiforme simple, postériorité à droite","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/planche-photos.webp","text":"POSITION\nSUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.\n\nPOSITION DES MAINS\nContacter par le pisiforme de la main caudale l’apophyse transverse en postériorité. Renforcer ce contact en plaçant le pisiforme de la main céphalique au niveau de la tabatière anatomique de la main applicatrice.\n\nBARRIÈRE MOTRICE\nEn se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.\n\nNORMALISATION\nPorter le thrust par la main caudale, en fin d’expiration, en direction de la tête du sujet et du sol dans le plan des facettes articulaires.","detail":{"source":"OSTPRA2 - page 14","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire Des dorsales, technique en pisiforme simple, postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, les bras sont le long du corps, la tête est tournée du côté de la postériorité de la vertèbre en dysfonction.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité. Renforcer ce contact en plaçant le pisiforme de la main céphalique au niveau de la tabatière anatomique de la main applicatrice.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"En se plaçant à l’aplomb du niveau en dysfonction, exercer une pression constante sur l’apophyse transverse en postériorité et demander au sujet de tourner la tête du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale, en fin d’expiration, en direction de la tête du sujet et du sol dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p014-dysfonction-facettaire-des-dorsales-technique-en-pisiforme-simple-posteriori/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":14,"sourceRow":37}},{"slug":"ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme","sourceRow":38,"sourceBook":"OSTPRA2","sourcePage":16,"matchers":["dysfonction facettaire s des dorsale s d9 a d12 assis technique en pisiforme simple posteriorite a gauche"],"title":"Dysfonction facettaire(s) des dorsale(s) (D9 à D12), assis, technique en pisiforme simple, postériorité à gauche","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/planche-photos.webp","text":"POSITION\nSUJET Assis à califourchon sur la table, la main opposée à la dysfonction est posée sur l’épaule du côté de la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN Assis à califourchon sur la table derrière le sujet, légèrement décalé du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique empaume l’épaule et la main du sujet du côté de la dysfonction. Le pisiforme de la main caudale contacte la postériorité de la vertèbre en dysfonction. Les doigts sont posés sur le grill costal.\n\nBARRIÈRE MOTRICE\nAmener, par la main céphalique, le levier supérieur thoracique en rotation et en inclinaison opposées à la dysfonction jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par le pisiforme de la main caudale en exagérant le levier de rotation, en fin d’expiration.","detail":{"source":"OSTPRA2 - page 16","category":"Dorsales et thorax – dorsale","method":"Thrust","intro":"Dysfonction facettaire(s) des dorsale(s) (D9 à D12), assis, technique en pisiforme simple, postériorité à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, la main opposée à la dysfonction est posée sur l’épaule du côté de la dysfonction. L’autre main est posée sur le ventre.\nPRATICIEN Assis à califourchon sur la table derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’épaule et la main du sujet du côté de la dysfonction. Le pisiforme de la main caudale contacte la postériorité de la vertèbre en dysfonction. Les doigts sont posés sur le grill costal.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener, par la main céphalique, le levier supérieur thoracique en rotation et en inclinaison opposées à la dysfonction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par le pisiforme de la main caudale en exagérant le levier de rotation, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p016-dysfonction-facettaire-s-des-dorsale-s-d9-a-d12-assis-technique-en-pisiforme/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":16,"sourceRow":38}},{"slug":"ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson","sourceRow":39,"sourceBook":"OSTPRA2","sourcePage":18,"matchers":["dysfonction facettaire des dorsales technique en double nelson"],"title":"Dysfonction facettaire DES dorsales, technique en « double Nelson »","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/planche-photos.webp","text":"POSITION\nSUJET Assis à califourchon sur la table.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.\n\nPOSITION DES MAINS\nGlisser les mains sous les bras du sujet pour se saisir des poignets. Demander au sujet de croiser les doigts derrière la nuque et accompagne le mouvement.\n\nBARRIÈRE MOTRICE\nDemander au sujet de serrer les coudes jusqu’à ressentir la mise en tension de la zone en dysfonction. Amener le rachis cervical en flexion jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par une traction verticale (lift) en fin d’expiration.","detail":{"source":"OSTPRA2 - page 18","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dysfonction facettaire DES dorsales, technique en « double Nelson »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Glisser les mains sous les bras du sujet pour se saisir des poignets. Demander au sujet de croiser les doigts derrière la nuque et accompagne le mouvement.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de serrer les coudes jusqu’à ressentir la mise en tension de la zone en dysfonction. Amener le rachis cervical en flexion jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift) en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p018-dysfonction-facettaire-des-dorsales-technique-en-double-nelson/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":18,"sourceRow":39}},{"slug":"ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl","sourceRow":40,"sourceBook":"OSTPRA2","sourcePage":20,"matchers":["dysfonction s des vertebre s dorsale s technique en lift composantes multiples assis"],"title":"Dysfonction(s) des vertèbre(s) dorsale(s), technique en « lift » (composantes multiples) assis","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/planche-photos.webp","text":"POSITION\nSUJET Assis à califourchon sur la table, les bras sont croisés sur le thorax les coudes sont superposés. Le rachis cervical est en flexion.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.\n\nPOSITION DES MAINS\nEmpaumer avec les deux mains le coude inférieur du sujet. Puis placer son sternum en contact direct avec la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la zone en dysfonction contre le sternum du praticien par un mouvement de virgule, vers l’arrière et vers le haut, jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par une traction verticale (lift), en fin d’expiration.","detail":{"source":"OSTPRA2 - page 20","category":"Dorsales et thorax – dorsale","method":"Lift","intro":"Dysfonction(s) des vertèbre(s) dorsale(s), technique en « lift » (composantes multiples) assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table, les bras sont croisés sur le thorax les coudes sont superposés. Le rachis cervical est en flexion.\nPRATICIEN Assis à califourchon sur la table derrière le sujet. Les pieds sont posés au sol.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer avec les deux mains le coude inférieur du sujet. Puis placer son sternum en contact direct avec la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la zone en dysfonction contre le sternum du praticien par un mouvement de virgule, vers l’arrière et vers le haut, jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par une traction verticale (lift), en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p020-dysfonction-s-des-vertebre-s-dorsale-s-technique-en-lift-composantes-multipl/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":20,"sourceRow":40}},{"slug":"ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m","sourceRow":41,"sourceBook":"OSTPRA2","sourcePage":22,"matchers":["dysfonction d une vertebre dorsale d8 d12 en nsgrd e m"],"title":"Dysfonction d’une vertèbre dorsale (D8-D12), en NSgRd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis, les jambes sont légèrement écartées, les pieds posés au sol, les bras sont croisés sur le thorax.\nPRATICIEN Assis derrière le sujet du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nEmpaumer par la main céphalique l’épaule du sujet du côté de la dysfonction. Contacter par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nDemander au sujet de s’incliner du côté de la vertèbre en dysfonction. Puis, amener le thorax en rotation opposée jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet une inclinaison du tronc dans le sens opposé à la dysfonction, et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison du côté de la dysfonction et en rotation opposée – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 22","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D8-D12), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds posés au sol, les bras sont croisés sur le thorax.\nPRATICIEN Assis derrière le sujet du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer par la main céphalique l’épaule du sujet du côté de la dysfonction. Contacter par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Demander au sujet de s’incliner du côté de la vertèbre en dysfonction. Puis, amener le thorax en rotation opposée jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une inclinaison du tronc dans le sens opposé à la dysfonction, et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison du côté de la dysfonction et en rotation opposée – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p022-dysfonction-d-une-vertebre-dorsale-d8-d12-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":22,"sourceRow":41}},{"slug":"ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m","sourceRow":42,"sourceBook":"OSTPRA2","sourcePage":24,"matchers":["dysfonction d une vertebre dorsale d7 d12 en erdsd e m"],"title":"Dysfonction d’une vertèbre dorsale (D7-D12) en ERdSd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière la tête.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.\n\nPOSITION DES MAINS\nLa main céphalique passe par l’anneau formé par le membre supérieur controlatéral à la dysfonction pour rejoindre l’omoplate du côté de la dysfonction. Contacter, par la main caudale, l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le rachis dorsal en latéroflexion, en rotation du côté opposé à la dysfonction et y associer une translation controlatérale jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe à l’apex de la courbure.\n\nNORMALISATION\nInviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en latéroflexion, en rotation et en flexion dans le sens opposé à la dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 24","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D7-D12) en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière la tête.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe par l’anneau formé par le membre supérieur controlatéral à la dysfonction pour rejoindre l’omoplate du côté de la dysfonction. Contacter, par la main caudale, l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis dorsal en latéroflexion, en rotation du côté opposé à la dysfonction et y associer une translation controlatérale jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe à l’apex de la courbure.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en latéroflexion, en rotation et en flexion dans le sens opposé à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p024-dysfonction-d-une-vertebre-dorsale-d7-d12-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":24,"sourceRow":42}},{"slug":"ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m","sourceRow":43,"sourceBook":"OSTPRA2","sourcePage":26,"matchers":["dysfonction d une vertebre dorsale d8 d12 en frdsd e m"],"title":"Dysfonction d’une vertèbre dorsale (D8-D12), en FRdSd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/planche-photos.webp","text":"VERIfIER pRISE bOuT DES DOIgTS\n\nPOSITION\nSUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. La main du côté de la dysfonction est posée sur l’épaule opposée, l’autre main est posée sur la table.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.\n\nPOSITION DES MAINS\nLa main céphalique empaume le deltoïde du sujet du côté de la dysfonction. Placer la main caudale sur l’espace inter-épineux sous-jacent à la vertèbre dysfonction.\n\nBARRIÈRE MOTRICE\nInviter le sujet à effectuer une extension, une inclinaison par un abaissement de l’épaule et une rotation du côté opposé à la dysfonction ainsi qu’une translation controlatérale du tronc jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe alors à l’apex de la courbure.\n\nNORMALISATION\nInviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison et en rotation – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 26","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"NOTE : VERIfIER pRISE bOuT DES DOIgTS\nDysfonction d’une vertèbre dorsale (D8-D12), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. La main du côté de la dysfonction est posée sur l’épaule opposée, l’autre main est posée sur la table.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le deltoïde du sujet du côté de la dysfonction. Placer la main caudale sur l’espace inter-épineux sous-jacent à la vertèbre dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à effectuer une extension, une inclinaison par un abaissement de l’épaule et une rotation du côté opposé à la dysfonction ainsi qu’une translation controlatérale du tronc jusqu’à percevoir le mouvement de la vertèbre en dysfonction. La vertèbre en dysfonction se situe alors à l’apex de la courbure.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à tourner les épaules dans le sens de la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison et en rotation – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p026-dysfonction-d-une-vertebre-dorsale-d8-d12-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":26,"sourceRow":43}},{"slug":"ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m","sourceRow":44,"sourceBook":"OSTPRA2","sourcePage":28,"matchers":["dysfonction d une vertebre dorsale d4 d8 en nsgrd e m"],"title":"Dysfonction d’une vertèbre dorsale (D4-D8), en NSgRd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière le cou.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.\n\nPOSITION DES MAINS\nLa main céphalique passe sous le coude proximal du sujet puis par l’anneau formé par le membre supérieur distal pour venir se poser sur l’épaule du côté de la dysfonction. La main caudale contacte l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la colonne dorsale en inclinaison du côté de la dysfonction par l’abaissement de l’épaule homolatérale et une élévation de l’épaule controlatérale. Amener une translation du côté opposé à la dysfonction du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Tracter par la main céphalique l’épaule homolatérale à la dysfonction vers l’avant jusqu’à percevoir la rotation de la vertèbre en dysfonction.\n\nNORMALISATION\nInviter le sujet à effectuer une inclinaison controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale à la dysfonction et en rotation controlatérale – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 28","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D4-D8), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis, les jambes sont légèrement écartées, les pieds sont posés au sol. Demander au sujet de croiser les doigts derrière le cou.\nPRATICIEN Debout derrière le sujet du côté opposé à la dysfonction. En fente avant.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique passe sous le coude proximal du sujet puis par l’anneau formé par le membre supérieur distal pour venir se poser sur l’épaule du côté de la dysfonction. La main caudale contacte l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en inclinaison du côté de la dysfonction par l’abaissement de l’épaule homolatérale et une élévation de l’épaule controlatérale. Amener une translation du côté opposé à la dysfonction du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Tracter par la main céphalique l’épaule homolatérale à la dysfonction vers l’avant jusqu’à percevoir la rotation de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale à la dysfonction et en rotation controlatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p028-dysfonction-d-une-vertebre-dorsale-d4-d8-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":28,"sourceRow":44}},{"slug":"ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m","sourceRow":45,"sourceBook":"OSTPRA2","sourcePage":30,"matchers":["dysfonction d une vertebre dorsale d4 d8 en frdsd e m"],"title":"Dysfonction d’une vertèbre dorsale (D4-D8), en FRdSd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET En procubitus, la tête est tournée du côté opposé à la postériorité de la vertèbre en dysfonction. Amener le membre supérieur homolatéral à la dysfonction le long de la tête, le coude fléchi. Le membre supérieur controlatéral reste le long du corps. Croiser la cheville homolatérale à la dysfonction sur l’autre cheville.\nPRATICIEN Debout à la hauteur du thorax.\n\nPOSITION DES MAINS\nContacter par le pisiforme de la main caudale l’apophyse transverse en postériorité, les doigts sont en direction de la tête du sujet. Le pisiforme de la main céphalique contacte l’apophyse transverse controlatérale de la même vertèbre. Les doigts sont dirigés vers les pieds du sujet.\n\nBARRIÈRE MOTRICE\nAugmenter la pression des deux mains de façon à majorer la rotation de l’apophyse transverse en dysfonction.\n\nNORMALISATION\nDemander une respiration profonde et profiter de la phase expiratoire pour exercer, par la main caudale, une pression sur l’apophyse transverse en postériorité en direction de la tête du sujet et du sol dans le plan des facettes articulaires. Exercer simultanément une pression, par la main céphalique, sur l’apophyse transverse opposée en direction des pieds du sujet. Au relâchement rechercher la nouvelle barrière motrice en exagérant les leviers d’inclinaison – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 30","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D4-D8), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté opposé à la postériorité de la vertèbre en dysfonction. Amener le membre supérieur homolatéral à la dysfonction le long de la tête, le coude fléchi. Le membre supérieur controlatéral reste le long du corps. Croiser la cheville homolatérale à la dysfonction sur l’autre cheville.\nPRATICIEN Debout à la hauteur du thorax.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par le pisiforme de la main caudale l’apophyse transverse en postériorité, les doigts sont en direction de la tête du sujet. Le pisiforme de la main céphalique contacte l’apophyse transverse controlatérale de la même vertèbre. Les doigts sont dirigés vers les pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Augmenter la pression des deux mains de façon à majorer la rotation de l’apophyse transverse en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une respiration profonde et profiter de la phase expiratoire pour exercer, par la main caudale, une pression sur l’apophyse transverse en postériorité en direction de la tête du sujet et du sol dans le plan des facettes articulaires. Exercer simultanément une pression, par la main céphalique, sur l’apophyse transverse opposée en direction des pieds du sujet. Au relâchement rechercher la nouvelle barrière motrice en exagérant les leviers d’inclinaison – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p030-dysfonction-d-une-vertebre-dorsale-d4-d8-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":30,"sourceRow":45}},{"slug":"ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m","sourceRow":46,"sourceBook":"OSTPRA2","sourcePage":32,"matchers":["dysfonction d une vertebre dorsale d1 d4 en nsgrd e m"],"title":"Dysfonction d’une vertèbre dorsale (D1-D4), en NSgRd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied opposé à la dysfonction sur la table. Glisser le genou sous l’épaule opposée à la dysfonction.\n\nPOSITION DES MAINS\nPoser la main controlatérale à la dysfonction sur le sommet de la tête du sujet avec l’avant-bras au contact de la face latérale de la tête. Contrôler par la main homolatérale à la dysfonction l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la colonne dorsale et cervicale en inclinaison homolatérale à la dysfonction. Puis ajouter une translation controlatérale du tronc en écartant le genou du praticien de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Enfin, amener en rotation controlatérale la tête du sujet jusqu’à percevoir la rotation de la vertèbre en dysfonction.\n\nNORMALISATION\nInviter le sujet à effectuer une inclinaison de la tête controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale et rotation controlatérale – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 32","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D4), en NSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied opposé à la dysfonction sur la table. Glisser le genou sous l’épaule opposée à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Poser la main controlatérale à la dysfonction sur le sommet de la tête du sujet avec l’avant-bras au contact de la face latérale de la tête. Contrôler par la main homolatérale à la dysfonction l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale et cervicale en inclinaison homolatérale à la dysfonction. Puis ajouter une translation controlatérale du tronc en écartant le genou du praticien de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Enfin, amener en rotation controlatérale la tête du sujet jusqu’à percevoir la rotation de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à effectuer une inclinaison de la tête controlatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale et rotation controlatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p032-dysfonction-d-une-vertebre-dorsale-d1-d4-en-nsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":32,"sourceRow":46}},{"slug":"ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m","sourceRow":47,"sourceBook":"OSTPRA2","sourcePage":34,"matchers":["dysfonction d une vertebre dorsale d1 d6 en erdsd e m"],"title":"Dysfonction d’une vertèbre dorsale (D1-D6), en ERdSd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nEnserrer la tête du sujet entre le bras et l’avant-bras céphalique, la main est au contact de l’occiput. Contacter par les doigts de la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la colonne dorsale en flexion en y associant une translation postérieure du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Amener la tête du sujet en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.\n\nNORMALISATION\nDemander au sujet de pousser la tête vers l’arrière et légèrement en rotation homolatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et flexion – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 34","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D6), en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Enserrer la tête du sujet entre le bras et l’avant-bras céphalique, la main est au contact de l’occiput. Contacter par les doigts de la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne dorsale en flexion en y associant une translation postérieure du tronc de telle façon que la vertèbre en dysfonction se situe à l’apex de la courbure. Amener la tête du sujet en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et légèrement en rotation homolatérale à la dysfonction et s’y opposer pendant 10 à 12 secondes. Au relâchement rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et flexion – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p034-dysfonction-d-une-vertebre-dorsale-d1-d6-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":34,"sourceRow":47}},{"slug":"ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m","sourceRow":48,"sourceBook":"OSTPRA2","sourcePage":36,"matchers":["dysfonction d une vertebre dorsale d1 d3 en frdsd e m"],"title":"Dysfonction d’une vertèbre dorsale (D1-D3), en FRdSd (E.M.)","zone":"Rachis","sub":"Dorsales","level":"Niveau intermédiaire","status":"non vue","icon":"D","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique repose sur le front du sujet, l’avant-bras contacte la face latérale de la tête. Contrôler par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener la colonne cervicale en extension, en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.\n\nNORMALISATION\nDemander au sujet de pousser sur la main et l’avant-bras du praticien et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et extension – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 36","category":"Dorsales et thorax – dorsale","method":"Énergie musculaire","intro":"Dysfonction d’une vertèbre dorsale (D1-D3), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet, légèrement décalé du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique repose sur le front du sujet, l’avant-bras contacte la face latérale de la tête. Contrôler par la main caudale l’espace inter-épineux sous-jacent à la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison et en rotation controlatérale à la dysfonction jusqu’à percevoir le mouvement de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser sur la main et l’avant-bras du praticien et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison, rotation controlatérale et extension – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p036-dysfonction-d-une-vertebre-dorsale-d1-d3-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":36,"sourceRow":48}},{"slug":"ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct","sourceRow":49,"sourceBook":"OSTPRA2","sourcePage":38,"matchers":["dysfonction costo transversaire de la 1re cote en elevation technique structurelle"],"title":"Dysfonction costo-transversaire de la 1re côte, en élévation. Technique structurelle","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied controlatéral à la dysfonction sur la table et glisser le genou sous l’épaule du sujet.\n\nPOSITION DES MAINS\nPlacer le bord radial de l’articulation inter-phalangienne proximale de l’index de la main homolatérale à la dysfonction sur la face supérieure de la première côte, en avant du trapèze. La main controlatérale empaume la région fronto-pariétale. Le coude vient au contact de la partie antérieure de l’épaule du sujet.\n\nBARRIÈRE MOTRICE\nAmener la colonne cervicale en extension, en inclinaison homolatérale à la dysfonction et en rotation controlatérale jusqu’à la perception du relâchement fascial de la zone. Exercer sur la côte une pression progressive vers le bas et en direction de la hanche controlatérale du sujet jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust vers le bas et la hanche opposée en fin de mouvement et d’expiration.","detail":{"source":"OSTPRA2 - page 38","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire de la 1re côte, en élévation. Technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout derrière le sujet. Poser le pied controlatéral à la dysfonction sur la table et glisser le genou sous l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer le bord radial de l’articulation inter-phalangienne proximale de l’index de la main homolatérale à la dysfonction sur la face supérieure de la première côte, en avant du trapèze. La main controlatérale empaume la région fronto-pariétale. Le coude vient au contact de la partie antérieure de l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en extension, en inclinaison homolatérale à la dysfonction et en rotation controlatérale jusqu’à la perception du relâchement fascial de la zone. Exercer sur la côte une pression progressive vers le bas et en direction de la hanche controlatérale du sujet jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust vers le bas et la hanche opposée en fin de mouvement et d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p038-dysfonction-costo-transversaire-de-la-1re-cote-en-elevation-technique-struct/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":38,"sourceRow":49}},{"slug":"ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle","sourceRow":50,"sourceBook":"OSTPRA2","sourcePage":40,"matchers":["dysfonction costo transversaire antero mediane technique structurelle"],"title":"Dysfonction costo-transversaire antéro-médiane, technique structurelle","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nAmener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.\n\nBARRIÈRE MOTRICE\nRechercher la barrière motrice en amenant le thorax en légère rotation controlatérale à la dysfonction.\n\nNORMALISATION\nPorter le thrust en direction de la table et en tractant la main applicatrice vers le dehors en fin d’expiration.","detail":{"source":"OSTPRA2 - page 40","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire antéro-médiane, technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation controlatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dehors en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p040-dysfonction-costo-transversaire-antero-mediane-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":40,"sourceRow":50}},{"slug":"ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle","sourceRow":51,"sourceBook":"OSTPRA2","sourcePage":42,"matchers":["dysfonction costo transversaire postero laterale technique structurelle"],"title":"Dysfonction costo-transversaire postéro latérale, technique structurelle","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nAmener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.\n\nBARRIÈRE MOTRICE\nRechercher la barrière motrice en amenant le thorax en légère rotation homolatérale à la dysfonction.\n\nNORMALISATION\nPorter le thrust en direction de la table et en tractant la main applicatrice vers le dedans en fin d’expiration.","detail":{"source":"OSTPRA2 - page 42","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire postéro latérale, technique structurelle","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, les bras sont croisés sur le thorax, les coudes sont superposés.\nPRATICIEN Debout à la hauteur du thorax, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le tronc du sujet de façon à localiser par la main caudale la côte en dysfonction. Contacter l’articulation costo-transversaire en dysfonction par l’éminence thénar de la main caudale, le pouce est dans l’axe vertébral, la main à plat. Puis, maintenir par la main céphalique les coudes et le thorax avec un appui sternal.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Rechercher la barrière motrice en amenant le thorax en légère rotation homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table et en tractant la main applicatrice vers le dedans en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p042-dysfonction-costo-transversaire-postero-laterale-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":42,"sourceRow":51}},{"slug":"ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle","sourceRow":52,"sourceBook":"OSTPRA2","sourcePage":44,"matchers":["dysfonction costo transversaire composantes multiples technique structurelle assis"],"title":"Dysfonction costo-transversaire, composantes multiples, technique structurelle, assis","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/planche-photos.webp","text":"POSITION\nSUJET Assis à califourchon, la main controlatérale est posée sur l’épaule homolatérale à la dysfonction et la main homolatérale repose sur le grill costal controlatéral.\nPRATICIEN Assis à califourchon derrière le sujet légèrement décalé sur le côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique du praticien empaume le deltoïde homolatéral à la dysfonction. Contacter par le pisiforme de la main caudale l’articulation costo-transversaire en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le thorax en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en extension.\n\nNORMALISATION\nPorter le thrust par la main caudale vers l’avant, en fin d’expiration.","detail":{"source":"OSTPRA2 - page 44","category":"Dorsales et thorax – costo-vertébrale","method":"Thrust","intro":"Dysfonction costo-transversaire, composantes multiples, technique structurelle, assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon, la main controlatérale est posée sur l’épaule homolatérale à la dysfonction et la main homolatérale repose sur le grill costal controlatéral.\nPRATICIEN Assis à califourchon derrière le sujet légèrement décalé sur le côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique du praticien empaume le deltoïde homolatéral à la dysfonction. Contacter par le pisiforme de la main caudale l’articulation costo-transversaire en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le thorax en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en extension.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main caudale vers l’avant, en fin d’expiration.","photo":"assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p044-dysfonction-costo-transversaire-composantes-multiples-technique-structurelle/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":44,"sourceRow":52}},{"slug":"ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m","sourceRow":53,"sourceBook":"OSTPRA2","sourcePage":46,"matchers":["dysfonction costo transversaire antero mediane e m"],"title":"Dysfonction costo-transversaire antéro-médiane (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis à califourchon sur la table. Amener la main homolatérale à la dysfonction sur l’épaule opposée\nPRATICIEN Debout du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nSoutenir le coude homolatéral à la dysfonction. Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dedans de l’angle costal postérieur.\n\nBARRIÈRE MOTRICE\nAmener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation controlatérale à la dysfonction jusqu’à la barrière motrice de la zone.\n\nNORMALISATION\nDemander au sujet de tirer son coude vers le bas, vers l’arrière et en dehors et s’y opposer. Simultanément avec le pouce le praticien repousse l’angle costal postérieur en dehors. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation controlatérale la dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 46","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dysfonction costo-transversaire antéro-médiane (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis à califourchon sur la table. Amener la main homolatérale à la dysfonction sur l’épaule opposée\nPRATICIEN Debout du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction. Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dedans de l’angle costal postérieur.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation controlatérale à la dysfonction jusqu’à la barrière motrice de la zone.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tirer son coude vers le bas, vers l’arrière et en dehors et s’y opposer. Simultanément avec le pouce le praticien repousse l’angle costal postérieur en dehors. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation controlatérale la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p046-dysfonction-costo-transversaire-antero-mediane-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":46,"sourceRow":53}},{"slug":"ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m","sourceRow":54,"sourceBook":"OSTPRA2","sourcePage":48,"matchers":["dysfonction costo transversaire postero laterale e m"],"title":"Dysfonction costo-transversaire postéro-latérale (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table. Amener la main homolatérale à la dysfonction sur l’épaule opposée.\nPRATICIEN Debout du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nSoutenir le coude homolatéral à la dysfonction Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dehors de l’angle costal postérieur.\n\nBARRIÈRE MOTRICE\nAmener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation homolatérale à la dysfonction jusqu’à la barrière motrice de la zone.\n\nNORMALISATION\nDemander au sujet d’amener son coude homolatéral à la dysfonction en dehors et s’y opposer. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation homolatérale à la dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 48","category":"Dorsales et thorax – costo-vertébrale","method":"Énergie musculaire","intro":"Dysfonction costo-transversaire postéro-latérale (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table. Amener la main homolatérale à la dysfonction sur l’épaule opposée.\nPRATICIEN Debout du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soutenir le coude homolatéral à la dysfonction Contacter par la main opposée le corps de la côte de telle façon à ce que le pouce soit en dehors de l’angle costal postérieur.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude à hauteur de la côte à normaliser. Amener le thorax en légère rotation homolatérale à la dysfonction jusqu’à la barrière motrice de la zone.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet d’amener son coude homolatéral à la dysfonction en dehors et s’y opposer. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p048-dysfonction-costo-transversaire-postero-laterale-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":48,"sourceRow":54}},{"slug":"ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e","sourceRow":55,"sourceBook":"OSTPRA2","sourcePage":50,"matchers":["dysfonction respiratoire de la 1re cote en elevation dans le plan sagittal e m"],"title":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan sagittal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nLa main céphalique crochète l’angle postérieur de la première côte. La tête du sujet repose sur l’avant-bras du praticien. Le pouce de la main caudale est en contact avec la partie antérieure de la première côte, sous la clavicule.\n\nBARRIÈRE MOTRICE\nAmener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à percevoir la barrière motrice.\n\nNORMALISATION\nDemander au sujet de respirer amplement. Lors de l’expiration, amener la partie antérieure de la première côte en direction des pieds et tracter simultanément sa partie postérieure vers la tête. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 50","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique crochète l’angle postérieur de la première côte. La tête du sujet repose sur l’avant-bras du praticien. Le pouce de la main caudale est en contact avec la partie antérieure de la première côte, sous la clavicule.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à percevoir la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, amener la partie antérieure de la première côte en direction des pieds et tracter simultanément sa partie postérieure vers la tête. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p050-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-sagittal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":50,"sourceRow":55}},{"slug":"ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-","sourceRow":56,"sourceBook":"OSTPRA2","sourcePage":52,"matchers":["dysfonction respiratoire de la 1re cote en elevation dans le plan frontal e m"],"title":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan frontal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nLa pulpe du pouce de la main caudale vient au contact de la partie supérieure de la première côte. La main céphalique soutient l’occiput du sujet.\n\nBARRIÈRE MOTRICE\nAmener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet de respirer amplement. Lors de l’expiration, pousser la première côte en direction des pieds. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 52","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire de la 1re côte, en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main caudale vient au contact de la partie supérieure de la première côte. La main céphalique soutient l’occiput du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la tête en flexion et en inclinaison du côté homolatéral à la dysfonction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de respirer amplement. Lors de l’expiration, pousser la première côte en direction des pieds. Au relâchement, rechercher la nouvelle barrière motrice en exagérant la flexion et l’inclinaison cervicale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p052-dysfonction-respiratoire-de-la-1re-cote-en-elevation-dans-le-plan-frontal-e-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":52,"sourceRow":56}},{"slug":"ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta","sourceRow":57,"sourceBook":"OSTPRA2","sourcePage":54,"matchers":["dysfonction respiratoire des 1re a 6e cote en elevation dans le plan sagittal e m"],"title":"Dysfonction respiratoire des (1re à 6e côte), en élévation dans le plan sagittal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nBasculer le thorax du sujet afin de crocheter l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et sur le thorax afin de la guider et de la stabiliser. Le pouce de la main antérieure contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.\n\nBARRIÈRE MOTRICE\nEffectuer une flexion du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception, par sa main antérieure, d’un relâchement fascial sus-jacent du niveau à normaliser. Par la main postérieure, crocheter simultanément la côte en regard du même niveau\n\nNORMALISATION\nDemander au sujet une expiration exagérer les leviers de flexion du rachis. Au relâchement, rechercher une nouvelle barrière motrice – À répéter trois fois","detail":{"source":"OSTPRA2 - page 54","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (1re à 6e côte), en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et sur le thorax afin de la guider et de la stabiliser. Le pouce de la main antérieure contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception, par sa main antérieure, d’un relâchement fascial sus-jacent du niveau à normaliser. Par la main postérieure, crocheter simultanément la côte en regard du même niveau","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet une expiration exagérer les leviers de flexion du rachis. Au relâchement, rechercher une nouvelle barrière motrice – À répéter trois fois","photo":"assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p054-dysfonction-respiratoire-des-1re-a-6e-cote-en-elevation-dans-le-plan-sagitta/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":54,"sourceRow":57}},{"slug":"ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e","sourceRow":58,"sourceBook":"OSTPRA2","sourcePage":56,"matchers":["dysfonction respiratoire des 1re 6e cote en elevation dans le plan frontal e m"],"title":"Dysfonction respiratoire des (1re-6e côte), en élévation dans le plan frontal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nLa main et l’avant-bras céphaliques soutiennent et guident le rachis dorsal et cervical, la main caudale par sa première commissure contacte la côte en dysfonction en regard de la ligne médio-axillaire.\n\nBARRIÈRE MOTRICE\nEffectuer une flexion et une inclinaison du côté homolatéral à la dysfonction du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent de la côte en dysfonction.\n\nNORMALISATION\nDemander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 56","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (1re-6e côte), en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras céphaliques soutiennent et guident le rachis dorsal et cervical, la main caudale par sa première commissure contacte la côte en dysfonction en regard de la ligne médio-axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion et une inclinaison du côté homolatéral à la dysfonction du rachis cervical et, si nécessaire, du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent de la côte en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p056-dysfonction-respiratoire-des-1re-6e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":56,"sourceRow":58}},{"slug":"ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-","sourceRow":59,"sourceBook":"OSTPRA2","sourcePage":58,"matchers":["dysfonction respiratoire des 7e 10e cote en elevation dans le plan sagittal e m"],"title":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan sagittal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nBasculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La main caudale contacte par la première commissure la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.\n\nBARRIÈRE MOTRICE\nEffectuer une flexion du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser. Crocheter simultanément et postérieurement la côte en regard du même niveau.\n\nNORMALISATION\nDemander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en flexion et inclinaison homolatérale à la dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 58","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La main caudale contacte par la première commissure la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Effectuer une flexion du rachis dorsal jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser. Crocheter simultanément et postérieurement la côte en regard du même niveau.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en flexion et inclinaison homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p058-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-sagittal-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":58,"sourceRow":59}},{"slug":"ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e","sourceRow":60,"sourceBook":"OSTPRA2","sourcePage":60,"matchers":["dysfonction respiratoire des 7e 10e cote en elevation dans le plan frontal e m"],"title":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan frontal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.\n\nPOSITION DES MAINS\nBasculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La première commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en regard de la ligne médio-axillaire.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical et dorsal en flexion et en inclinaison homolatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.\n\nNORMALISATION\nDemander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale à la dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 60","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction respiratoire des (7e-10e côte), en élévation dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le thorax du sujet afin de crocheter par la main céphalique l’angle postérieur de la côte en dysfonction. La tête du sujet repose sur l’avant-bras et le thorax du praticien afin de la guider et de la stabiliser. La première commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en regard de la ligne médio-axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical et dorsal en flexion et en inclinaison homolatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au patient de souffler et rechercher à chaque fin de phase expiratoire une nouvelle barrière motrice en inclinaison homolatérale à la dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p060-dysfonction-respiratoire-des-7e-10e-cote-en-elevation-dans-le-plan-frontal-e/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":60,"sourceRow":60}},{"slug":"ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq","sourceRow":61,"sourceBook":"OSTPRA2","sourcePage":62,"matchers":["dysfonction des 1re 2e cote en abaissement dans le plan sagittal e m technique dite en bras de pompe"],"title":"Dysfonction des (1re-2e côte), en abaissement dans le plan sagittal (E.M.). Technique dite en « bras de pompe »","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front. Le\npraticien le maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nBasculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.\n\nBARRIÈRE MOTRICE\nImprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.\n\nNORMALISATION\nDemander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 62","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (1re-2e côte), en abaissement dans le plan sagittal (E.M.). Technique dite en « bras de pompe »","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front. Le\npraticien le maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p062-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-sagittal-e-m-techniq/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":62,"sourceRow":61}},{"slug":"ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m","sourceRow":62,"sourceBook":"OSTPRA2","sourcePage":64,"matchers":["dysfonction des 1re 2e cote en abaissement dans le plan frontal e m"],"title":"Dysfonction des (1re-2e côte), en abaissement dans le plan frontal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front que le\npraticien maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nBasculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.\n\nBARRIÈRE MOTRICE\nImprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.\n\nNORMALISATION\nDemander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 64","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (1re-2e côte), en abaissement dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front que le\npraticien maintient par sa main céphalique.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter par la main caudale l’angle postérieur de la 1 re ou de la 2 e côte.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander une élévation de la tête et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p064-dysfonction-des-1re-2e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":64,"sourceRow":62}},{"slug":"ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m","sourceRow":63,"sourceBook":"OSTPRA2","sourcePage":66,"matchers":["dysfonction des 3e 10e cote en abaissement dans le plan sagittal e m"],"title":"Dysfonction des (3e-10e côte), en abaissement, dans le plan sagittal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front coude vers le haut.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nBasculer le sujet afin de crocheter de la main caudale l’angle postérieur de la 1 re ou de la 2 e côte. La main céphalique du praticien contacte le coude du sujet.\n\nBARRIÈRE MOTRICE\nImprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.\n\nNORMALISATION\nDemander au sujet de pousser son coude en direction de ses pieds et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 66","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (3e-10e côte), en abaissement, dans le plan sagittal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée à 60° du côté opposé à la dysfonction. Demander au sujet de poser son poignet sur son front coude vers le haut.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Basculer le sujet afin de crocheter de la main caudale l’angle postérieur de la 1 re ou de la 2 e côte. La main céphalique du praticien contacte le coude du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Imprimer au niveau de la côte en dysfonction une pression associée à une traction à la fois latérale externe et en direction des pieds.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser son coude en direction de ses pieds et s’y opposer. Lors du relâchement, majorer la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p066-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-sagittal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":66,"sourceRow":63}},{"slug":"ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m","sourceRow":64,"sourceBook":"OSTPRA2","sourcePage":68,"matchers":["dysfonction des 3e 10e cote en abaissement dans le plan frontal e m"],"title":"Dysfonction des (3e-10e côte), en abaissement, dans le plan frontal (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique empaume le coude du sujet homolatéral à la dysfonction en passant par le dessus de sa tête. Sa main repose sur l’avant-bras du praticien. La 1 re commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.\n\nBARRIÈRE MOTRICE\nAmener une inclinaison thoracique controlatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.\n\nNORMALISATION\nDemander au sujet de ramener latéralement le coude en direction du tronc et s’y opposer. Lors du relâchement, majorer l’inclinaison du tronc et la traction de la côte en dysfonction – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 68","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (3e-10e côte), en abaissement, dans le plan frontal (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est tournée légèrement du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume le coude du sujet homolatéral à la dysfonction en passant par le dessus de sa tête. Sa main repose sur l’avant-bras du praticien. La 1 re commissure de la main caudale contacte la partie antérieure de la côte en dysfonction, en dehors de la jonction chondro-costale.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener une inclinaison thoracique controlatérale à la dysfonction jusqu’à perception d’un relâchement fascial sus-jacent du niveau à normaliser.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de ramener latéralement le coude en direction du tronc et s’y opposer. Lors du relâchement, majorer l’inclinaison du tronc et la traction de la côte en dysfonction – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p068-dysfonction-des-3e-10e-cote-en-abaissement-dans-le-plan-frontal-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":68,"sourceRow":64}},{"slug":"ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m","sourceRow":65,"sourceBook":"OSTPRA2","sourcePage":70,"matchers":["dysfonction des 11e 12e cote en elevation e m"],"title":"Dysfonction des (11e-12e côte), en élévation (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/planche-photos.webp","text":"POSITION\nSUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée, le bras homolatéral est placé le long du corps.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.\n\nBARRIÈRE MOTRICE\nLa main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction des pieds du sujet.\n\nNORMALISATION\nSur l’expiration, demander au sujet de pousser le bassin contre la table, s’y opposer. Simultanément, le patient glisse le bras en direction de ses pieds. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en abaissant la côte – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 70","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (11e-12e côte), en élévation (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée, le bras homolatéral est placé le long du corps.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Sur l’expiration, demander au sujet de pousser le bassin contre la table, s’y opposer. Simultanément, le patient glisse le bras en direction de ses pieds. Maintenir la position 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en abaissant la côte – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p070-dysfonction-des-11e-12e-cote-en-elevation-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":70,"sourceRow":65}},{"slug":"ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m","sourceRow":66,"sourceBook":"OSTPRA2","sourcePage":72,"matchers":["dysfonction des 11e 12e cote en abaissement e m"],"title":"Dysfonction des (11e-12e côte), en abaissement (E.M.)","zone":"Rachis","sub":"Côtes","level":"Niveau intermédiaire","status":"non vue","icon":"CT","video":"","headerImage":"assets/images/zones/zone-dorsales.webp","image":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/planche-photos.webp","text":"POSITION\nSUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée. Le membre supérieur homolatéral à la dysfonction est posé à la hauteur de la tête.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à dysfonction.\n\nPOSITION DES MAINS\nla main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.\n\nBARRIÈRE MOTRICE\nLa main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction de la tête.\n\nNORMALISATION\nFixer la côte à normaliser et demander au sujet d’amener son bassin vers le haut et en direction de la table. S’y opposer pendant 10 à 12 secondes. Lors de la phase d’expiration, étirer le carré des lombes en tractant le bassin en haut et en arrière – À répéter trois fois.","detail":{"source":"OSTPRA2 - page 72","category":"Dorsales et thorax – côtes","method":"Énergie musculaire","intro":"Dysfonction des (11e-12e côte), en abaissement (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, la tête est tournée du côté de la dysfonction, la cheville homolatérale à la dysfonction est croisée sur l’opposée. Le membre supérieur homolatéral à la dysfonction est posé à la hauteur de la tête.\nPRATICIEN Debout à la hauteur du bassin, du côté opposé à dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"la main céphalique posée à plat contacte la zone en dysfonction. La main caudale agrippe l’épine iliaque antéro-supérieure homolatérale à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale tracte le bassin vers l’arrière, la main céphalique exerce une pression sur la côte en dysfonction en direction de la tête.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Fixer la côte à normaliser et demander au sujet d’amener son bassin vers le haut et en direction de la table. S’y opposer pendant 10 à 12 secondes. Lors de la phase d’expiration, étirer le carré des lombes en tractant le bassin en haut et en arrière – À répéter trois fois.","photo":"assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p072-dysfonction-des-11e-12e-cote-en-abaissement-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":72,"sourceRow":66}},{"slug":"ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-","sourceRow":67,"sourceBook":"OSTPRA2","sourcePage":74,"matchers":["dysfonction facettaire de la region cervico dorsale c7 d2 position assise a droite"],"title":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), position assise, à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/planche-photos.webp","text":"POSITION\nSUJET assis en bord de table.\nPRATICIEN Debout derrière le sujet, poser le pied droit sur la table, le genou est sous le creux axillaire.\n\nPOSITION DES MAINS\nContacter par la pulpe du pouce gauche la face latérale droite de l’épineuse de la vertèbre en dysfonction. Les autres doigts sont posés sur la clavicule. Le coude est placé dans un axe horizontal. La main droite empaume la face latérale de la tête, le coude reposant sur l’épaule du sujet.\n\nBARRIÈRE MOTRICE\nGuider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Écarter légèrement le genou droit de façon à induire une translation droite du niveau à normaliser. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin de mouvement dans l’axe horizontal.","detail":{"source":"OSTPRA2 - page 74","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), position assise, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET assis en bord de table.\nPRATICIEN Debout derrière le sujet, poser le pied droit sur la table, le genou est sous le creux axillaire.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Contacter par la pulpe du pouce gauche la face latérale droite de l’épineuse de la vertèbre en dysfonction. Les autres doigts sont posés sur la clavicule. Le coude est placé dans un axe horizontal. La main droite empaume la face latérale de la tête, le coude reposant sur l’épaule du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Écarter légèrement le genou droit de façon à induire une translation droite du niveau à normaliser. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement dans l’axe horizontal.","photo":"assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p074-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-position-assise-a-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":74,"sourceRow":67}},{"slug":"ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr","sourceRow":68,"sourceBook":"OSTPRA2","sourcePage":76,"matchers":["dysfonction facettaire de la region cervico dorsale c7 d2 en procubitus a droite"],"title":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), en procubitus à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/planche-photos.webp","text":"POSITION\nSUJET En procubitus, le menton est posé sur la table.\nPRATICIEN Debout, à la hauteur du thorax du sujet, du côté opposé à la postériorité de la vertèbre en dysfonction.\n\nPOSITION DES MAINS\nLa pulpe du pouce gauche contacte la face latérale gauche de l’épineuse. Les autres doigts sont posés sur la clavicule. L’avant bras est horizontal dans la direction de l’épaule opposée au sujet. La main droite est posée en conque sur la face latérale droite de la tête (ne pas écraser l’oreille).\n\nBARRIÈRE MOTRICE\nGuider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin de mouvement en direction de l’épaule droite du sujet.","detail":{"source":"OSTPRA2 - page 76","category":"Dorsales et thorax – cervico-dorsales","method":"Thrust","intro":"Dysfonction facettaire de la région cervico-dorsale (C7-D2), en procubitus à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En procubitus, le menton est posé sur la table.\nPRATICIEN Debout, à la hauteur du thorax du sujet, du côté opposé à la postériorité de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce gauche contacte la face latérale gauche de l’épineuse. Les autres doigts sont posés sur la clavicule. L’avant bras est horizontal dans la direction de l’épaule opposée au sujet. La main droite est posée en conque sur la face latérale droite de la tête (ne pas écraser l’oreille).","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Guider par la main droite la colonne cervicale en extension, en inclinaison gauche et en rotation droite jusqu’au niveau de la dysfonction. Exercer par le pouce gauche une pression progressive sur l’épineuse vers la droite jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de mouvement en direction de l’épaule droite du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p076-dysfonction-facettaire-de-la-region-cervico-dorsale-c7-d2-en-procubitus-a-dr/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":76,"sourceRow":68}},{"slug":"ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit","sourceRow":69,"sourceBook":"OSTPRA2","sourcePage":78,"matchers":["dysfonction de la region cervico dorsale c7 d2 composantes multiples a droite"],"title":"Dysfonction de la région cervico-dorsale (C7-D2) composantes multiples à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/planche-photos.webp","text":"POSITION\nSUJET En latérocubitus, les membres inférieurs sont fléchis et les mains placées entre les genoux. L’épaule du côté de la table est dégagée vers l’avant et en direction des pieds.\nPRATICIEN Debout en fente avant gauche à la hauteur de la ceinture scapulaire.\n\nPOSITION DES MAINS\nSoulever la tête du sujet et la maintenir fermement à l’aide du bras et de l’avant-bras gauche, la main recouvre l’occiput. Poser le thorax sur l’épaule gauche du sujet. Appliquer la pulpe du pouce droit sur la face latérale du processus épineux de la vertèbre sous-jacente à la dysfonction, les doigts libres étant étalés sur la région dorsale.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en inclinaison gauche, en translation latérale droite et en rotation droite. Associer ces composantes de mouvement avec celle de flexion, extension ou compression, à la recherche de la convergence de mise en tension de la zone en dysfonction.\n\nNORMALISATION\nTout en maintenant les résultantes de tension, le praticien, par l’intermédiaire de sa main droite (placée sur l’épineuse) majore la rotation gauche par un mouvement de haute vélocité, basse amplitude (HBVA).","detail":{"source":"OSTPRA2 - page 78","category":"Dorsales et thorax – cervico-dorsales","method":"Mobilisation","intro":"Dysfonction de la région cervico-dorsale (C7-D2) composantes multiples à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En latérocubitus, les membres inférieurs sont fléchis et les mains placées entre les genoux. L’épaule du côté de la table est dégagée vers l’avant et en direction des pieds.\nPRATICIEN Debout en fente avant gauche à la hauteur de la ceinture scapulaire.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Soulever la tête du sujet et la maintenir fermement à l’aide du bras et de l’avant-bras gauche, la main recouvre l’occiput. Poser le thorax sur l’épaule gauche du sujet. Appliquer la pulpe du pouce droit sur la face latérale du processus épineux de la vertèbre sous-jacente à la dysfonction, les doigts libres étant étalés sur la région dorsale.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en inclinaison gauche, en translation latérale droite et en rotation droite. Associer ces composantes de mouvement avec celle de flexion, extension ou compression, à la recherche de la convergence de mise en tension de la zone en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant les résultantes de tension, le praticien, par l’intermédiaire de sa main droite (placée sur l’épineuse) majore la rotation gauche par un mouvement de haute vélocité, basse amplitude (HBVA).","photo":"assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p078-dysfonction-de-la-region-cervico-dorsale-c7-d2-composantes-multiples-a-droit/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":78,"sourceRow":69}},{"slug":"ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite","sourceRow":70,"sourceBook":"OSTPRA2","sourcePage":80,"matchers":["dysfonction de l occiput en posteriorite a droite"],"title":"Dysfonction de l’occiput, en postériorité à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.\n\nPOSITION DES MAINS\nEmpaumer le menton par la main controlatérale, l’avant-bras se positionne légèrement en avant de l’oreille du sujet. Contacter l’écaille occipitale par le bord radial de la métacarpo-phalangienne de l’index de la main homolatérale, en arrière de la mastoïde. L’avant-bras est horizontal dans l’axe des yeux du sujet.\n\nBARRIÈRE MOTRICE\nMajorer la rotation controlatérale à la dysfonction de la tête. Placer l’occiput en légère extension. Exercer une légère pression par son sternum sur la tête du sujet et une pression de l’index sur l’occiput jusqu’à la barrière motrice dans le plan des facettes articulaires de l’occiput.\n\nNORMALISATION\nPorter le thrust en direction des yeux du sujet.","detail":{"source":"OSTPRA2 - page 80","category":"Cervicales – occiput","method":"Thrust","intro":"Dysfonction de l’occiput, en postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le menton par la main controlatérale, l’avant-bras se positionne légèrement en avant de l’oreille du sujet. Contacter l’écaille occipitale par le bord radial de la métacarpo-phalangienne de l’index de la main homolatérale, en arrière de la mastoïde. L’avant-bras est horizontal dans l’axe des yeux du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale à la dysfonction de la tête. Placer l’occiput en légère extension. Exercer une légère pression par son sternum sur la tête du sujet et une pression de l’index sur l’occiput jusqu’à la barrière motrice dans le plan des facettes articulaires de l’occiput.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction des yeux du sujet.","photo":"assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p080-dysfonction-de-l-occiput-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":80,"sourceRow":70}},{"slug":"ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite","sourceRow":71,"sourceBook":"OSTPRA2","sourcePage":82,"matchers":["dysfonction de l occiput en translation a droite"],"title":"Dysfonction de l’Occiput, en translation à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal. La tête est tournée à 90° du côté opposé à la dysfonction.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.\n\nPOSITION DES MAINS\nLa main sous-jacente, les doigts en direction des pieds, empaument la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index et le majeur sont de part et d’autre du muscle sterno-cléido-mastoïdien. La main sus-jacente applicatrice est posée sur la face latérale de la tête. Le talon de la main est en contact avec la branche horizontale du maxillaire inférieur.\n\nBARRIÈRE MOTRICE\nAmener simultanément la tête en inclinaison homolatérale à la dysfonction et en translation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust de la main sus-jacente applicatrice en majorant l’inclinaison homolatérale. La main sous-jacente accompagnant le mouvement.","detail":{"source":"OSTPRA2 - page 82","category":"Cervicales – occiput","method":"Thrust","intro":"Dysfonction de l’Occiput, en translation à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90° du côté opposé à la dysfonction.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente, les doigts en direction des pieds, empaument la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index et le majeur sont de part et d’autre du muscle sterno-cléido-mastoïdien. La main sus-jacente applicatrice est posée sur la face latérale de la tête. Le talon de la main est en contact avec la branche horizontale du maxillaire inférieur.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener simultanément la tête en inclinaison homolatérale à la dysfonction et en translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de la main sus-jacente applicatrice en majorant l’inclinaison homolatérale. La main sous-jacente accompagnant le mouvement.","photo":"assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p082-dysfonction-de-l-occiput-en-translation-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":82,"sourceRow":71}},{"slug":"ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa","sourceRow":72,"sourceBook":"OSTPRA2","sourcePage":84,"matchers":["dysfonction articulaire globale occiput atlas axis oaa"],"title":"Dysfonction articulaire globale Occiput Atlas Axis (OAA)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal. La tête est tournée à 90°.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.\n\nPOSITION DES MAINS\nLa main sous-jacente empaume la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index de la main sus-jacente est sur la tempe. Le majeur sous le malaire, les deux autres doigts sous le menton, le pouce contacte l’écaille occipitale. Les deux avant-bras sont dans le prolongement du sterno-cléido-mastoïdien, le coude sus-jacent au dessus du sternum.\n\nBARRIÈRE MOTRICE\nTout en maintenant les avant-bras dans l’axe vertébral, effectuer un mouvement hélicoïdal en légère traction et en rotation de la tête jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant le mouvement hélicoïdal. Répéter la manœuvre en rotation opposée.","detail":{"source":"OSTPRA2 - page 84","category":"Cervicales – OAA","method":"Thrust","intro":"Dysfonction articulaire globale Occiput Atlas Axis (OAA)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal. La tête est tournée à 90°.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main sous-jacente empaume la face latérale de la tête en prenant soin de ne pas écraser l’oreille. L’index de la main sus-jacente est sur la tempe. Le majeur sous le malaire, les deux autres doigts sous le menton, le pouce contacte l’écaille occipitale. Les deux avant-bras sont dans le prolongement du sterno-cléido-mastoïdien, le coude sus-jacent au dessus du sternum.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tout en maintenant les avant-bras dans l’axe vertébral, effectuer un mouvement hélicoïdal en légère traction et en rotation de la tête jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le mouvement hélicoïdal. Répéter la manœuvre en rotation opposée.","photo":"assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p084-dysfonction-articulaire-globale-occiput-atlas-axis-oaa/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":84,"sourceRow":72}},{"slug":"ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite","sourceRow":73,"sourceBook":"OSTPRA2","sourcePage":86,"matchers":["dysfonction de l atlas en posteriorite a droite"],"title":"Dysfonction de l’Atlas, en postériorité à droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index. La main et l’avant-bras sont en direction des yeux et parallèles au plan de la table.\n\nBARRIÈRE MOTRICE\nLa main applicatrice majore la rotation controlatérale de la tête. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la rotation.","detail":{"source":"OSTPRA2 - page 86","category":"Cervicales – atlas","method":"Thrust","intro":"Dysfonction de l’Atlas, en postériorité à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index. La main et l’avant-bras sont en direction des yeux et parallèles au plan de la table.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale de la tête. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation.","photo":"assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p086-dysfonction-de-l-atlas-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":86,"sourceRow":73}},{"slug":"ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite","sourceRow":74,"sourceBook":"OSTPRA2","sourcePage":88,"matchers":["dysfonction de l atlas en translation droite"],"title":"Dysfonction de l’Atlas, en translation droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index, la main et l’avant-bras sont en direction des yeux.\n\nBARRIÈRE MOTRICE\nLa main applicatrice majore la rotation controlatérale à la dysfonction. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction du sol.","detail":{"source":"OSTPRA2 - page 88","category":"Cervicales – atlas","method":"Thrust","intro":"Dysfonction de l’Atlas, en translation droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, en fente latérale, légèrement décalé du côté homolatéral à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale applicatrice contacte la partie postérieure de l’apophyse transverse de l’atlas par le bord radial de la métacarpo-phalangienne de l’index, la main et l’avant-bras sont en direction des yeux.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main applicatrice majore la rotation controlatérale à la dysfonction. Exercer une pression de l’index sur l’apophyse transverse de l’atlas jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du sol.","photo":"assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p088-dysfonction-de-l-atlas-en-translation-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":88,"sourceRow":74}},{"slug":"ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant","sourceRow":75,"sourceBook":"OSTPRA2","sourcePage":90,"matchers":["dysfonction facettaire des cervicales c2 c6 en posteriorite a droite variante"],"title":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite (variante)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet en fente latérale du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale empaume la face latérale du visage du sujet. La main homolatérale contacte, par la métacarpo-phalangienne de l’index, la partie postéro-latérale de l’apophyse transverse de la vertèbre en dysfonction. Le pouce est posé sur la branche horizontale de la mandibule.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant le levier de rotation controlatérale.","detail":{"source":"OSTPRA2 - page 90","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite (variante)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume la face latérale du visage du sujet. La main homolatérale contacte, par la métacarpo-phalangienne de l’index, la partie postéro-latérale de l’apophyse transverse de la vertèbre en dysfonction. Le pouce est posé sur la branche horizontale de la mandibule.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de rotation controlatérale.","photo":"assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p090-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-variant/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":90,"sourceRow":75}},{"slug":"ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m","sourceRow":76,"sourceBook":"OSTPRA2","sourcePage":92,"matchers":["dysfonction facettaire des cervicales c2 c6 en posteriorite a droite prise mentonniere"],"title":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite; prise mentonnière","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Veiller à ce que la main et l’avant-bras droits soient dans le plan des facettes articulaires.\n\nBARRIÈRE MOTRICE\nMajorer la rotation controlatérale et l’inclinaison homolatérale de la tête. Ajouter une légère extension. Exercer une pression indexielle sur l’apophyse articulaire jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en rotation controlatérale dans le plan des facettes articulaires.","detail":{"source":"OSTPRA2 - page 92","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à droite; prise mentonnière","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Veiller à ce que la main et l’avant-bras droits soient dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la rotation controlatérale et l’inclinaison homolatérale de la tête. Ajouter une légère extension. Exercer une pression indexielle sur l’apophyse articulaire jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en rotation controlatérale dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p092-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-droite-prise-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":92,"sourceRow":76}},{"slug":"ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite","sourceRow":77,"sourceBook":"OSTPRA2","sourcePage":94,"matchers":["dysfonction facettaire des cervicales c2 c6 en translation droite"],"title":"Dysfonction facettaire des cervicales (C2-C6), en translation droite","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Le pouce est posé sur la branche horizontale de la mandibule.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en flexion, en légère inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant le levier de translation.","detail":{"source":"OSTPRA2 - page 94","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en translation droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN À la tête du sujet, en fente latérale du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index. Le pouce est posé sur la branche horizontale de la mandibule.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en légère inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant le levier de translation.","photo":"assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p094-dysfonction-facettaire-des-cervicales-c2-c6-en-translation-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":94,"sourceRow":77}},{"slug":"ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a","sourceRow":78,"sourceBook":"OSTPRA2","sourcePage":96,"matchers":["dysfonction facettaire des cervicales c2 c6 en posteriorite a gauche sujet assis"],"title":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à gauche; sujet assis","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table.\nPRATICIEN Debout, devant le sujet, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main homolatérale applicatrice contacte l’apophyse articulaire de la vertèbre en dysfonction par la pulpe du médius. La main controlatérale est sur la face latérale de la tête.\n\nBARRIÈRE MOTRICE\nAmener la colonne cervicale en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en légère extension. Exercer par le médius une pression sur l’apophyse articulaire jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la rotation dans le plan des facettes articulaires.","detail":{"source":"OSTPRA2 - page 96","category":"Cervicales – facettes cervicales","method":"Thrust","intro":"Dysfonction facettaire des cervicales (C2-C6), en postériorité à gauche; sujet assis","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table.\nPRATICIEN Debout, devant le sujet, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main homolatérale applicatrice contacte l’apophyse articulaire de la vertèbre en dysfonction par la pulpe du médius. La main controlatérale est sur la face latérale de la tête.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener la colonne cervicale en inclinaison homolatérale à la dysfonction, en rotation controlatérale et en légère extension. Exercer par le médius une pression sur l’apophyse articulaire jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation dans le plan des facettes articulaires.","photo":"assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p096-dysfonction-facettaire-des-cervicales-c2-c6-en-posteriorite-a-gauche-sujet-a/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":96,"sourceRow":78}},{"slug":"ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m","sourceRow":79,"sourceBook":"OSTPRA2","sourcePage":98,"matchers":["dysfonction des cervicales c2 c7 en erdsd e m"],"title":"Dysfonction des cervicales (C2-C7), en ERdSd (E.M.)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale empaume l’écaille de l’occiput controlatéral. La main homolatérale applicatrice contacte par la métacarpo-phalangienne de l’index l’apophyse transverse de la vertèbre en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet de tourner la tête vers la main applicatrice et vers l’arrière. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une inclinaison homolatérale, une translation, une rotation controlatérale et une flexion – À répéter 3 fois.","detail":{"source":"OSTPRA2 - page 98","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Dysfonction des cervicales (C2-C7), en ERdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale empaume l’écaille de l’occiput controlatéral. La main homolatérale applicatrice contacte par la métacarpo-phalangienne de l’index l’apophyse transverse de la vertèbre en dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner la tête vers la main applicatrice et vers l’arrière. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une inclinaison homolatérale, une translation, une rotation controlatérale et une flexion – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p098-dysfonction-des-cervicales-c2-c7-en-erdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":98,"sourceRow":79}},{"slug":"ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m","sourceRow":80,"sourceBook":"OSTPRA2","sourcePage":100,"matchers":["dysfonction des cervicale c2 c7 en frdsd e m"],"title":"Dysfonction des cervicale (C2-C7), en FRdSd (E.M.)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en extension, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet de pousser la tête vers l’arrière et vers son épaule homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une extension, une inclinaison homolatérale, une translation et une rotation controlatérale – À répéter 3 fois.","detail":{"source":"OSTPRA2 - page 100","category":"Cervicales – cervicales","method":"Énergie musculaire","intro":"Dysfonction des cervicale (C2-C7), en FRdSd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton. La main homolatérale contacte l’apophyse articulaire de la vertèbre en dysfonction par le bord radial de la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en inclinaison homolatérale, en translation et en rotation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser la tête vers l’arrière et vers son épaule homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par une extension, une inclinaison homolatérale, une translation et une rotation controlatérale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p100-dysfonction-des-cervicale-c2-c7-en-frdsd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":100,"sourceRow":80}},{"slug":"ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m","sourceRow":81,"sourceBook":"OSTPRA2","sourcePage":102,"matchers":["dysfonction atloido axoidienne en rotation droite e m"],"title":"Dysfonction Atloïdo-axoïdienne, en rotation droite (E.M.)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume l’écaille de l’occiput. La main homolatérale contacte la face latérale du visage du sujet, en avant de l’oreille.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en rotation et en légère translation controlatérales à la dysfonction.\n\nNORMALISATION\nDemander au sujet de tourner les yeux avec insistance en direction de la dysfonction pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation et la translation controlatérales – À répéter 3 fois.","detail":{"source":"OSTPRA2 - page 102","category":"Cervicales – Atlas – axis","method":"Énergie musculaire","intro":"Dysfonction Atloïdo-axoïdienne, en rotation droite (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume l’écaille de l’occiput. La main homolatérale contacte la face latérale du visage du sujet, en avant de l’oreille.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en rotation et en légère translation controlatérales à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tourner les yeux avec insistance en direction de la dysfonction pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation et la translation controlatérales – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p102-dysfonction-atloido-axoidienne-en-rotation-droite-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":102,"sourceRow":81}},{"slug":"ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m","sourceRow":82,"sourceBook":"OSTPRA2","sourcePage":104,"matchers":["dysfonction occipito atloidienne en esgrd e m"],"title":"Dysfonction Occipito-atloïdienne, en ESgRd (E.M.)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en flexion, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet de pousser le menton vers le plafond et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale, en rotation controlatérale et en flexion – À répéter 3 fois.","detail":{"source":"OSTPRA2 - page 104","category":"Cervicales – occiput atlas","method":"Énergie musculaire","intro":"Dysfonction Occipito-atloïdienne, en ESgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en flexion, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton vers le plafond et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en inclinaison homolatérale, en rotation controlatérale et en flexion – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p104-dysfonction-occipito-atloidienne-en-esgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":104,"sourceRow":82}},{"slug":"ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m","sourceRow":83,"sourceBook":"OSTPRA2","sourcePage":106,"matchers":["dysfonction occipito atloidienne en fsgrd e m"],"title":"Dysfonction Occipito-atloïdienne, en FSgRd (E.M.)","zone":"Rachis","sub":"Cervicales","level":"Niveau intermédiaire","status":"non vue","icon":"C","video":"","headerImage":"assets/images/zones/zone-cervicales.webp","image":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.\n\nBARRIÈRE MOTRICE\nAmener le rachis cervical en extension, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.\n\nNORMALISATION\nDemander au sujet de pousser le menton en direction de ses pieds et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison homolatérale et en rotation controlatérale – À répéter 3 fois.","detail":{"source":"OSTPRA2 - page 106","category":"Cervicales – occiput – atlas","method":"Énergie musculaire","intro":"Dysfonction Occipito-atloïdienne, en FSgRd (E.M.)","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la tête du sujet, légèrement décalé du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main controlatérale à la dysfonction empaume le menton du sujet. La face latérale de la tête est en appui sur l’avant-bras du praticien. La main homolatérale contacte la zone sous-occipitale par la métacarpo-phalangienne de l’index.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le rachis cervical en extension, en rotation et en légère translation controlatérale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de pousser le menton en direction de ses pieds et en rotation homolatérale à la dysfonction. S’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en extension, en inclinaison homolatérale et en rotation controlatérale – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra2-p106-dysfonction-occipito-atloidienne-en-fsgrd-e-m/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA2","sourcePage":106,"sourceRow":83}},{"slug":"ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite","sourceRow":85,"sourceBook":"OSTPRA3","sourcePage":6,"matchers":["dysfonction pre sternale de la clavicule a droite"],"title":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE, à droite","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du thorax du sujet, du côté de la dysfonction.\n\nPOSITION DES MAINS\nPrendre en berceau le membre supérieur homolatéral à la dysfonction par la main céphalique du praticien. La main caudale applicatrice contacte par l’éminence hypothénar le bord antérieur de l’extrémité interne de la clavicule les doigts reposent sur trapèze.\n\nBARRIÈRE MOTRICE\nAmener le membre supérieur du sujet dans l’axe longitudinal de la clavicule. Dans le même axe, exercer une légère traction sur le membre supérieur et porter le moignon de l’épaule en direction du plafond. Majorer par la main applicatrice la pression sur l’extrémité de la clavicule en direction de la table jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust dans l’axe de la clavicule et en direction de la table en fin de mouvement.","detail":{"source":"OSTPRA3 - page 6","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur du thorax du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Prendre en berceau le membre supérieur homolatéral à la dysfonction par la main céphalique du praticien. La main caudale applicatrice contacte par l’éminence hypothénar le bord antérieur de l’extrémité interne de la clavicule les doigts reposent sur trapèze.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule. Dans le même axe, exercer une légère traction sur le membre supérieur et porter le moignon de l’épaule en direction du plafond. Majorer par la main applicatrice la pression sur l’extrémité de la clavicule en direction de la table jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust dans l’axe de la clavicule et en direction de la table en fin de mouvement.","photo":"assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p006-dysfonction-pre-sternale-de-la-clavicule-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":6,"sourceRow":85}},{"slug":"ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite","sourceRow":86,"sourceBook":"OSTPRA3","sourcePage":8,"matchers":["dysfonction sus sternale de la clavicule a droite"],"title":"Dysfonction sus-sternale de la clavicule, à droite","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur de la tête du sujet, du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main céphalique prend en berceau le membre supérieur homolatéral à la dysfonction. La main caudale applicatrice contacte, par l’éminence hypothénar, la face supérieure de l’extrémité interne de la clavicule.\n\nBARRIÈRE MOTRICE\nAmener le membre supérieur du sujet dans l’axe longitudinal de la clavicule en exerçant une légère traction. Par la main applicatrice, majorer la pression sur l’extrémité interne de la clavicule, en direction des pieds du sujet, jusqu’à la barrière motrice.\n\nNORMALISATION\nTout en maintenant la traction sur le membre supérieur, porter le thrust par la main applicatrice en direction des pieds du sujet.","detail":{"source":"OSTPRA3 - page 8","category":"Membre supérieur – articulation sterno-claviculaire","method":"Thrust","intro":"Dysfonction sus-sternale de la clavicule, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction.\nPRATICIEN Debout à la hauteur de la tête du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique prend en berceau le membre supérieur homolatéral à la dysfonction. La main caudale applicatrice contacte, par l’éminence hypothénar, la face supérieure de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur du sujet dans l’axe longitudinal de la clavicule en exerçant une légère traction. Par la main applicatrice, majorer la pression sur l’extrémité interne de la clavicule, en direction des pieds du sujet, jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Tout en maintenant la traction sur le membre supérieur, porter le thrust par la main applicatrice en direction des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p008-dysfonction-sus-sternale-de-la-clavicule-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":8,"sourceRow":86}},{"slug":"ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite","sourceRow":87,"sourceBook":"OSTPRA3","sourcePage":10,"matchers":["dysfonction pre sternale de la clavicule e m a droite"],"title":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE (E.M.), à droite","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction, la main de l’épaule en dysfonction est posée sur l’épaule du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, face au sujet.\n\nPOSITION DES MAINS\nMaintenir le poignet du patient et contacter par l’index et le majeur de la main applicatrice le bord antérieur de l’extrémité interne de la clavicule.\n\nBARRIÈRE MOTRICE\nTracter le bras et l’épaule du sujet en direction du plafond jusqu’à percevoir, par la main applicatrice, la barrière motrice sterno-claviculaire.\n\nNORMALISATION\nDemander au sujet de tracter l’épaule et le bras en direction de la table et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par élévation de l’épaule – À répéter 3 fois.","detail":{"source":"OSTPRA3 - page 10","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"DYSFONCTION PRÉ-STERNALE DE LA CLAVICULE (E.M.), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction, la main de l’épaule en dysfonction est posée sur l’épaule du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, face au sujet.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Maintenir le poignet du patient et contacter par l’index et le majeur de la main applicatrice le bord antérieur de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter le bras et l’épaule du sujet en direction du plafond jusqu’à percevoir, par la main applicatrice, la barrière motrice sterno-claviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de tracter l’épaule et le bras en direction de la table et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par élévation de l’épaule – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p010-dysfonction-pre-sternale-de-la-clavicule-e-m-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":10,"sourceRow":87}},{"slug":"ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche","sourceRow":88,"sourceBook":"OSTPRA3","sourcePage":12,"matchers":["dysfonction sus sternale de la clavicule e m a gauche"],"title":"DYSFONCTION SUS-STERNALE DE LA CLAVICULE (E.M.), à gauche","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. L’épaule en dysfonction est légèrement en dehors de la table.\nPRATICIEN Debout face au sujet.\n\nPOSITION DES MAINS\nLa main distale saisit le poignet du sujet. La main applicatrice contacte par l’index et le majeur, le bord antérieur de l’extrémité interne de la clavicule.\n\nBARRIÈRE MOTRICE\nAmener le membre supérieur en rétropulsion, en rotation interne et en légère abduction, jusqu’à percevoir par la main applicatrice, la barrière motrice sterno-claviculaire.\n\nNORMALISATION\nDemander au sujet de soulever le membre supérieur et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par un abaissement du membre supérieur – À répéter 3 fois.","detail":{"source":"OSTPRA3 - page 12","category":"Membre supérieur – articulation sterno-claviculaire","method":"Énergie musculaire","intro":"DYSFONCTION SUS-STERNALE DE LA CLAVICULE (E.M.), à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. L’épaule en dysfonction est légèrement en dehors de la table.\nPRATICIEN Debout face au sujet.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale saisit le poignet du sujet. La main applicatrice contacte par l’index et le majeur, le bord antérieur de l’extrémité interne de la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre supérieur en rétropulsion, en rotation interne et en légère abduction, jusqu’à percevoir par la main applicatrice, la barrière motrice sterno-claviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Demander au sujet de soulever le membre supérieur et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice par un abaissement du membre supérieur – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p012-dysfonction-sus-sternale-de-la-clavicule-e-m-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":12,"sourceRow":88}},{"slug":"ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche","sourceRow":89,"sourceBook":"OSTPRA3","sourcePage":14,"matchers":["dysfonction acromio claviculaire en rotation anterieure a gauche"],"title":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation antérieure, à gauche","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.\n\nPOSITION DES MAINS\nLa main applicatrice contacte par le pisiforme la partie la plus postérieure de la face supéro-externe de la clavicule. La main opposée empaume la partie proximale de l’avant-bras.\n\nBARRIÈRE MOTRICE\nFixer la clavicule en rotation postérieure en exerçant, par la main applicatrice, une pression horizontale vers l’arrière.\n\nNORMALISATION\nAmener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’avant et se terminant en position de rétropulsion.","detail":{"source":"OSTPRA3 - page 14","category":"Membre supérieur – articulation acromio-claviculaire","method":"Mobilisation","intro":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation antérieure, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main applicatrice contacte par le pisiforme la partie la plus postérieure de la face supéro-externe de la clavicule. La main opposée empaume la partie proximale de l’avant-bras.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Fixer la clavicule en rotation postérieure en exerçant, par la main applicatrice, une pression horizontale vers l’arrière.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’avant et se terminant en position de rétropulsion.","photo":"assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p014-dysfonction-acromio-claviculaire-en-rotation-anterieure-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":14,"sourceRow":89}},{"slug":"ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche","sourceRow":90,"sourceBook":"OSTPRA3","sourcePage":16,"matchers":["dysfonction acromio claviculaire en rotation posterieure a gauche"],"title":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation postérieure à gauche","zone":"Membres supérieurs","sub":"Clavicule","level":"Niveau intermédiaire","status":"non vue","icon":"CL","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/planche-photos.webp","text":"POSITION\nSUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.\n\nPOSITION DES MAINS\nLa main distale empaume l’avant-bras. La main applicatrice contacte par le pisiforme la partie la plus antérieure de la face supéro‑externe la clavicule.\n\nBARRIÈRE MOTRICE\nExercer par le pisiforme une pression en direction de la table de façon à fixer la clavicule en rotation antérieure.\n\nNORMALISATION\nAmener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’arrière et se terminant en position d’antépulsion et adduction.","detail":{"source":"OSTPRA3 - page 16","category":"Membre supérieur – articulation acromio-claviculaire","method":"Mobilisation","intro":"DYSFONCTION ACROMIO - CLAVICULAIRE, en rotation postérieure à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET Assis en bord de table, la tête est légèrement tournée et inclinée du côté opposé à la dysfonction.\nPRATICIEN Debout, derrière le sujet.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume l’avant-bras. La main applicatrice contacte par le pisiforme la partie la plus antérieure de la face supéro‑externe la clavicule.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer par le pisiforme une pression en direction de la table de façon à fixer la clavicule en rotation antérieure.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Amener l’épaule en abduction et imprimer à celle-ci un mouvement de circumduction sec et rapide en commençant par l’arrière et se terminant en position d’antépulsion et adduction.","photo":"assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p016-dysfonction-acromio-claviculaire-en-rotation-posterieure-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":16,"sourceRow":90}},{"slug":"ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche","sourceRow":91,"sourceBook":"OSTPRA3","sourcePage":18,"matchers":["dysfonction gleno humerale en anteriorite a gauche"],"title":"DYSFONCTION GLÉNO-HUMÉRALE, en antériorité, à gauche","zone":"Membres supérieurs","sub":"Épaule","level":"Niveau intermédiaire","status":"non vue","icon":"EP","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main distale empaume le coude du sujet. La face antérieure de la cuisse contacte la face supéro-interne du bras du sujet. L’éminence hypothénar de la main applicatrice contacte la tête humérale.\n\nBARRIÈRE MOTRICE\nExercer une légère traction sur le membre supérieur en l’amenant en adduction, puis majorer la pression sur la tête de l’humérus en direction du sol jusqu’à percevoir la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main applicatrice en direction du sol.","detail":{"source":"OSTPRA3 - page 18","category":"Membre supérieur – gleno-humérale","method":"Thrust","intro":"DYSFONCTION GLÉNO-HUMÉRALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le coude du sujet. La face antérieure de la cuisse contacte la face supéro-interne du bras du sujet. L’éminence hypothénar de la main applicatrice contacte la tête humérale.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur le membre supérieur en l’amenant en adduction, puis majorer la pression sur la tête de l’humérus en direction du sol jusqu’à percevoir la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p018-dysfonction-gleno-humerale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":18,"sourceRow":91}},{"slug":"ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche","sourceRow":92,"sourceBook":"OSTPRA3","sourcePage":20,"matchers":["dysfonction humero ulnaire en abduction a gauche"],"title":"DYSFONCTION HUMÉRO-ULNAIRE, en abduction, à gauche","zone":"Membres supérieurs","sub":"Coude","level":"Niveau intermédiaire","status":"non vue","icon":"CO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant, du côté de la dysfonction.\n\nPOSITION DES MAINS\nPlacer et maintenir l’avant-bras du sujet en supination entre le membre supérieur distal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale.\n\nBARRIÈRE MOTRICE\nAmener le coude du sujet en extension incomplète de façon à permettre la mobilisation en adduction. Majorer par la main interne la pression sur le coude de dedans en dehors jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust de dedans en dehors.","detail":{"source":"OSTPRA3 - page 20","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"DYSFONCTION HUMÉRO-ULNAIRE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur distal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en adduction. Majorer par la main interne la pression sur le coude de dedans en dehors jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p020-dysfonction-humero-ulnaire-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":20,"sourceRow":92}},{"slug":"ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite","sourceRow":93,"sourceBook":"OSTPRA3","sourcePage":22,"matchers":["dysfonction humero ulnaire en adduction a droite"],"title":"DYSFONCTION HUMÉRO-ULNAIRE en adduction, à droite","zone":"Membres supérieurs","sub":"Coude","level":"Niveau intermédiaire","status":"non vue","icon":"CO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nPlacer et maintenir l’avant-bras du sujet en supination entre le membre supérieur proximal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale par rapport au sol.\n\nBARRIÈRE MOTRICE\nAmener le coude du sujet en extension incomplète de façon à permettre la mobilisation en abduction. Majorer par la main externe la pression sur le coude de dehors en dedans jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust de dehors en dedans.","detail":{"source":"OSTPRA3 - page 22","category":"Membre supérieur – huméro-ulnaire","method":"Thrust","intro":"DYSFONCTION HUMÉRO-ULNAIRE en adduction, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en supination entre le membre supérieur proximal et le thorax, à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La palette humérale doit rester parfaitement horizontale par rapport au sol.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension incomplète de façon à permettre la mobilisation en abduction. Majorer par la main externe la pression sur le coude de dehors en dedans jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p022-dysfonction-humero-ulnaire-en-adduction-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":22,"sourceRow":93}},{"slug":"ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite","sourceRow":94,"sourceBook":"OSTPRA3","sourcePage":24,"matchers":["dysfonction humero radiale en anteriorite a droite"],"title":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","zone":"Membres supérieurs","sub":"Coude","level":"Niveau intermédiaire","status":"non vue","icon":"CO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. Le coude du sujet est posé sur la face antérieure de la cuisse du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, le genou du membre inférieur proximal est posé sur la table.\n\nPOSITION DES MAINS\nLa main interne empaume le poignet du sujet. L’index et le majeur de la main opposée contactent le pli antérieur du coude.\n\nBARRIÈRE MOTRICE\nAmener l’avant-bras en flexion et en supination. La main applicatrice exerce une pression sur la tête radiale en la tractant jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main applicatrice en majorant la traction.","detail":{"source":"OSTPRA3 - page 24","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la tête est légèrement tournée du côté opposé à la dysfonction. Le coude du sujet est posé sur la face antérieure de la cuisse du\npraticien.\nPRATICIEN Debout à la hauteur du thorax, le genou du membre inférieur proximal est posé sur la table.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume le poignet du sujet. L’index et le majeur de la main opposée contactent le pli antérieur du coude.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener l’avant-bras en flexion et en supination. La main applicatrice exerce une pression sur la tête radiale en la tractant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice en majorant la traction.","photo":"assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p024-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":24,"sourceRow":94}},{"slug":"ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite","sourceRow":95,"sourceBook":"OSTPRA3","sourcePage":26,"matchers":["dysfonction humero radiale en anteriorite a droite"],"title":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","zone":"Membres supérieurs","sub":"Coude","level":"Niveau intermédiaire","status":"non vue","icon":"CO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax, du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main distale empaume le poignet du sujet. Le pouce de la main proximale applicatrice contacte la convexité postérieure de la tête radiale en dysfonction, les autres doigts soutiennent la face interne du coude.\n\nBARRIÈRE MOTRICE\nPlacer l’avant-bras en extension incomplète de façon à permettre le jeu articulaire. Amener la main du sujet en flexion palmaire et en inclinaison ulnaire.\n\nNORMALISATION\nPorter le thrust en majorant la rotation interne et l’extension du coude. Simultanément, le pouce applicateur exerce une pression sur la tête radiale. En fin de mouvement, la main du sujet vient en butée sur la hanche du praticien de façon à éviter l’hyper-extension.","detail":{"source":"OSTPRA3 - page 26","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le poignet du sujet. Le pouce de la main proximale applicatrice contacte la convexité postérieure de la tête radiale en dysfonction, les autres doigts soutiennent la face interne du coude.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Placer l’avant-bras en extension incomplète de façon à permettre le jeu articulaire. Amener la main du sujet en flexion palmaire et en inclinaison ulnaire.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la rotation interne et l’extension du coude. Simultanément, le pouce applicateur exerce une pression sur la tête radiale. En fin de mouvement, la main du sujet vient en butée sur la hanche du praticien de façon à éviter l’hyper-extension.","photo":"assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p026-dysfonction-humero-radiale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":26,"sourceRow":95}},{"slug":"ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite","sourceRow":96,"sourceBook":"OSTPRA3","sourcePage":28,"matchers":["dysfonction humero radiale en posteriorite variante a droite"],"title":"DYSFONCTION HUMÉRO-RADIALE, en postériorité (variante), à droite","zone":"Membres supérieurs","sub":"Coude","level":"Niveau intermédiaire","status":"non vue","icon":"CO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nPlacer et maintenir l’avant-bras du sujet en pronation entre le membre supérieur interne et le thorax à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La main externe applicatrice contacte, par la métacarpo-phalangienne de l’index, la partie postérieure de la tête radiale.\n\nBARRIÈRE MOTRICE\nAmener le coude du sujet en extension. La main applicatrice exerce une pression sur le coude de l’arrière vers l’avant jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction du plafond.","detail":{"source":"OSTPRA3 - page 28","category":"Membre supérieur – huméro-radiale","method":"Thrust","intro":"DYSFONCTION HUMÉRO-RADIALE, en postériorité (variante), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du thorax en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’avant-bras du sujet en pronation entre le membre supérieur interne et le thorax à la hauteur du poignet pour permettre un contre appui. Les deux mains enserrent le coude de façon à ce que les pouces reposent sur sa face antérieure, les autres doigts sont croisés sur la face postérieure. La main externe applicatrice contacte, par la métacarpo-phalangienne de l’index, la partie postérieure de la tête radiale.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le coude du sujet en extension. La main applicatrice exerce une pression sur le coude de l’arrière vers l’avant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du plafond.","photo":"assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p028-dysfonction-humero-radiale-en-posteriorite-variante-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":28,"sourceRow":96}},{"slug":"ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-","sourceRow":97,"sourceBook":"OSTPRA3","sourcePage":30,"matchers":["dysfonction radio carpienne du scaphoide ou du semi lunaire en posteriorite a gauche"],"title":"DYSFONCTION RADIO-CARPIENNE DU SCAPHOÏDE OU DU SEMI-LUNAIRE, en postériorité, à gauche","zone":"Membres supérieurs","sub":"Poignet","level":"Niveau intermédiaire","status":"non vue","icon":"PO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, la main est placée en dehors de la table.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nEnserrer le poignet entre les pouces et les index des deux mains. Les pouces superposés contactent la partie supérieure du scaphoïde ou du semi-lunaire. Les index soutiennent la face palmaire de la main.\n\nBARRIÈRE MOTRICE\nExercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en « Snap » sur l’un ou l’autre des deux os, en direction du sol.","detail":{"source":"OSTPRA3 - page 30","category":"Membre supérieur – radio-carpienne","method":"Snap","intro":"DYSFONCTION RADIO-CARPIENNE DU SCAPHOÏDE OU DU SEMI-LUNAIRE, en postériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, la main est placée en dehors de la table.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Enserrer le poignet entre les pouces et les index des deux mains. Les pouces superposés contactent la partie supérieure du scaphoïde ou du semi-lunaire. Les index soutiennent la face palmaire de la main.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » sur l’un ou l’autre des deux os, en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p030-dysfonction-radio-carpienne-du-scaphoide-ou-du-semi-lunaire-en-posteriorite-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":30,"sourceRow":97}},{"slug":"ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche","sourceRow":98,"sourceBook":"OSTPRA3","sourcePage":32,"matchers":["dysfonction radio carpienne en adduction a gauche"],"title":"DYSFONCTION RADIO-CARPIENNE, en adduction, à gauche","zone":"Membres supérieurs","sub":"Poignet","level":"Niveau intermédiaire","status":"non vue","icon":"PO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main interne empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main externe contacte le bord ulnaire des os du carpe.\n\nBARRIÈRE MOTRICE\nExercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en adduction jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust avec la main externe de dehors en dedans.","detail":{"source":"OSTPRA3 - page 32","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"DYSFONCTION RADIO-CARPIENNE, en adduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main interne empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main externe contacte le bord ulnaire des os du carpe.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en adduction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p032-dysfonction-radio-carpienne-en-adduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":32,"sourceRow":98}},{"slug":"ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche","sourceRow":99,"sourceBook":"OSTPRA3","sourcePage":34,"matchers":["dysfonction radio carpienne en abduction a gauche"],"title":"DYSFONCTION RADIO-CARPIENNE, en abduction, à gauche","zone":"Membres supérieurs","sub":"Poignet","level":"Niveau intermédiaire","status":"non vue","icon":"PO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main externe empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main interne contacte le bord radial des os du carpe.\n\nBARRIÈRE MOTRICE\nExercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en abduction jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust avec la main interne de dedans en dehors.","detail":{"source":"OSTPRA3 - page 34","category":"Membre supérieur – radio-carpienne","method":"Thrust","intro":"DYSFONCTION RADIO-CARPIENNE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout à la hauteur du bassin, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale de l’avant-bras. La métacarpo-phalangienne de l’index de la main interne contacte le bord radial des os du carpe.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener la main en abduction jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust avec la main interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p034-dysfonction-radio-carpienne-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":34,"sourceRow":99}},{"slug":"ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite","sourceRow":100,"sourceBook":"OSTPRA3","sourcePage":36,"matchers":["dysfonction articulaire globale des medio carpiennes a droite"],"title":"DYSFONCTION ARTICULAIRE GLOBALE DES MÉDIO-CARPIENNES, à droite","zone":"Membres supérieurs","sub":"Poignet","level":"Niveau intermédiaire","status":"non vue","icon":"PO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal, le coude est fléchi à 90°.\nPRATICIEN Debout en fente avant les épaules dirigées du côté de la dysfonction.\n\nPOSITION DES MAINS\nLes deux mains recouvrent la région carpienne antérieure et postérieure. Les éminences thénars sont placées perpendiculairement à l’axe de l’avant-bras. Les pouces se croisent sur la première commissure.\n\nBARRIÈRE MOTRICE\nLes éminences thénar majorent la compression sur les os du carpe jusqu’à la barrière motrice et la maintiennent.\n\nNORMALISATION\nInviter le sujet à fermer la main avec force quelques secondes puis, au relâchement, majorer la compression – À répéter 3 fois.","detail":{"source":"OSTPRA3 - page 36","category":"Membre supérieur – médio-carpienne","method":"Mobilisation","intro":"DYSFONCTION ARTICULAIRE GLOBALE DES MÉDIO-CARPIENNES, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal, le coude est fléchi à 90°.\nPRATICIEN Debout en fente avant les épaules dirigées du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains recouvrent la région carpienne antérieure et postérieure. Les éminences thénars sont placées perpendiculairement à l’axe de l’avant-bras. Les pouces se croisent sur la première commissure.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Les éminences thénar majorent la compression sur les os du carpe jusqu’à la barrière motrice et la maintiennent.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à fermer la main avec force quelques secondes puis, au relâchement, majorer la compression – À répéter 3 fois.","photo":"assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p036-dysfonction-articulaire-globale-des-medio-carpiennes-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":36,"sourceRow":100}},{"slug":"ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche","sourceRow":101,"sourceBook":"OSTPRA3","sourcePage":38,"matchers":["dysfonction articulaire globale des inter carpiennes a gauche"],"title":"DYSFONCTION ARTICULAIRE GLOBALE DES INTER-CARPIENNES, à gauche","zone":"Membres supérieurs","sub":"Poignet","level":"Niveau intermédiaire","status":"non vue","icon":"PO","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/planche-photos.webp","text":"POSITION\nSUJET En décubitus dorsal.\nPRATICIEN Debout en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nLes deux pouces sont superposés sur la partie postérieure de l’espace inter-carpien en dysfonction. Les autres doigts maintiennent la partie antérieure du poignet.\n\nBARRIÈRE MOTRICE\nExercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale.\n\nNORMALISATION\nPorter le thrust en « Snap » en direction du sol.","detail":{"source":"OSTPRA3 - page 38","category":"Membre supérieur – inter-carpiennes","method":"Snap","intro":"DYSFONCTION ARTICULAIRE GLOBALE DES INTER-CARPIENNES, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus dorsal.\nPRATICIEN Debout en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux pouces sont superposés sur la partie postérieure de l’espace inter-carpien en dysfonction. Les autres doigts maintiennent la partie antérieure du poignet.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer une légère traction sur la main dans l’axe longitudinal de l’avant-bras. Amener successivement la main en flexion palmaire puis en flexion dorsale.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en « Snap » en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p038-dysfonction-articulaire-globale-des-inter-carpiennes-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":38,"sourceRow":101}},{"slug":"ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite","sourceRow":102,"sourceBook":"OSTPRA3","sourcePage":40,"matchers":["dysfonction articulaire globale de la trapezo metacarpienne a droite"],"title":"DYSFONCTION ARTICULAIRE GLOBALE DE LA TRAPÉZO-MÉTACARPIENNE, à droite","zone":"Membres supérieurs","sub":"Main","level":"Niveau intermédiaire","status":"non vue","icon":"MA","video":"","headerImage":"assets/images/zones/zone-membres-superieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/planche-photos.webp","text":"POSITION\nSUJET En décubitus.\nPRATICIEN Debout à la hauteur de la main du sujet, du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main distale empaume le premier rayon de la main du sujet. Le pouce contacte la base postérieure du premier métacarpien. La main proximale empaume l’extrémité distale de l’avant-bras, le pouce de la main proximale se superposant au premier.\n\nBARRIÈRE MOTRICE\nLes pouces exercent une pression progressive sur la base métacarpienne en dedans et vers l’extrémité distale du pouce jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la pression sur la base métacarpienne jusqu’à percevoir la décoaptation de l’articulation.","detail":{"source":"OSTPRA3 - page 40","category":"Membre supérieu – trapézo-metacarpienne","method":"Thrust","intro":"DYSFONCTION ARTICULAIRE GLOBALE DE LA TRAPÉZO-MÉTACARPIENNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"SUJET En décubitus.\nPRATICIEN Debout à la hauteur de la main du sujet, du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main distale empaume le premier rayon de la main du sujet. Le pouce contacte la base postérieure du premier métacarpien. La main proximale empaume l’extrémité distale de l’avant-bras, le pouce de la main proximale se superposant au premier.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Les pouces exercent une pression progressive sur la base métacarpienne en dedans et vers l’extrémité distale du pouce jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la pression sur la base métacarpienne jusqu’à percevoir la décoaptation de l’articulation.","photo":"assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p040-dysfonction-articulaire-globale-de-la-trapezo-metacarpienne-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":40,"sourceRow":102}},{"slug":"ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche","sourceRow":103,"sourceBook":"OSTPRA3","sourcePage":42,"matchers":["dysfonction de la coxo femorale en rotation interne a gauche"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation interne, à gauche","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT Assis en bord de table, les pieds sont posés au sol, les mains sont en appui sur la table. Placer la cheville homolatérale à la dysfonction sur le genou opposé, l’ensemble est stabilisé par le genou du\npraticien.\nPRATICIEN Debout face au patient, en fente avant, du côté opposé à l’articulation en dysfonction.\n\nPOSITION DES MAINS\nLa main proximale établit un contact, par la métacarpo-phalangienne de l’index, avec la région inguinale homolatérale à la dysfonction. La main opposée du praticien empaume la face interne du genou.\n\nBARRIÈRE MOTRICE\nInviter le sujet à incliner et tourner le tronc et la tête légèrement du côté opposé à la dysfonction. Majorer la rotation externe de la hanche jusqu’à la barrière motrice en poussant le genou du patient en direction du sol. Majorer son contact inguinal en appuyant en direction de la table.\n\nNORMALISATION\nInviter le sujet à pousser son genou vers le haut et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation externe de la hanche – À répéter trois fois. En fin de technique, porter le thrust en majorant à la fois la rotation externe et la pression au niveau de l’aine.","detail":{"source":"OSTPRA3 - page 42","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation interne, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT Assis en bord de table, les pieds sont posés au sol, les mains sont en appui sur la table. Placer la cheville homolatérale à la dysfonction sur le genou opposé, l’ensemble est stabilisé par le genou du\npraticien.\nPRATICIEN Debout face au patient, en fente avant, du côté opposé à l’articulation en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main proximale établit un contact, par la métacarpo-phalangienne de l’index, avec la région inguinale homolatérale à la dysfonction. La main opposée du praticien empaume la face interne du genou.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Inviter le sujet à incliner et tourner le tronc et la tête légèrement du côté opposé à la dysfonction. Majorer la rotation externe de la hanche jusqu’à la barrière motrice en poussant le genou du patient en direction du sol. Majorer son contact inguinal en appuyant en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Inviter le sujet à pousser son genou vers le haut et s’y opposer pendant 10 à 12 secondes. Au relâchement, rechercher la nouvelle barrière motrice en majorant la rotation externe de la hanche – À répéter trois fois. En fin de technique, porter le thrust en majorant à la fois la rotation externe et la pression au niveau de l’aine.","photo":"assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p042-dysfonction-de-la-coxo-femorale-en-rotation-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":42,"sourceRow":103}},{"slug":"ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite","sourceRow":104,"sourceBook":"OSTPRA3","sourcePage":44,"matchers":["dysfonction de la coxo femorale en rotation externe a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation externe, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, le genou est fléchi à 90°, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main caudale saisit la cheville homolatérale à la dysfonction du patient. Le talon de la main céphalique contacte la face postérieure du grand trochanter après avoir refoulé les tissus musculaires.\n\nBARRIÈRE MOTRICE\nLa main caudale majore la rotation interne de la hanche, la main céphalique exerce une pression progressive sur le grand trochanter en direction de la table.\n\nNORMALISATION\nMajorer trois fois de suite la rotation interne et la pression sur le grand trochanter puis demander au sujet de tourner la tête du côté opposé à la dysfonction. Porter le thrust en direction de la table.","detail":{"source":"OSTPRA3 - page 44","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en rotation externe, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur du pelvis, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit la cheville homolatérale à la dysfonction du patient. Le talon de la main céphalique contacte la face postérieure du grand trochanter après avoir refoulé les tissus musculaires.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale majore la rotation interne de la hanche, la main céphalique exerce une pression progressive sur le grand trochanter en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer trois fois de suite la rotation interne et la pression sur le grand trochanter puis demander au sujet de tourner la tête du côté opposé à la dysfonction. Porter le thrust en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p044-dysfonction-de-la-coxo-femorale-en-rotation-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":44,"sourceRow":104}},{"slug":"ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche","sourceRow":105,"sourceBook":"OSTPRA3","sourcePage":46,"matchers":["dysfonction de la coxo femorale en abduction a gauche"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en abduction, à gauche","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus latéral sur le côté de la dysfonction.\nPRATICIEN Debout derrière le sujet à la hauteur du bassin.\n\nPOSITION DES MAINS\nLa main caudale soutient en prise berceau le membre inférieur en dysfonction. La main céphalique contacte par la métacarpo-phalangienne de l’index la région inguinale homolatérale. Le pelvis du sujet est stabilisé par le bassin du praticien.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur sus-jacent en légère extension. Amener le membre inférieur en dysfonction en légère flexion de hanche et adduction jusqu’à la barrière motrice. Le praticien majore le contact inguinal de la main céphalique par un mouvement antérieur de son pelvis.\n\nNORMALISATION\nPorter le thrust en majorant à la fois l’adduction et la pression inguinale.","detail":{"source":"OSTPRA3 - page 46","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus latéral sur le côté de la dysfonction.\nPRATICIEN Debout derrière le sujet à la hauteur du bassin.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale soutient en prise berceau le membre inférieur en dysfonction. La main céphalique contacte par la métacarpo-phalangienne de l’index la région inguinale homolatérale. Le pelvis du sujet est stabilisé par le bassin du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur sus-jacent en légère extension. Amener le membre inférieur en dysfonction en légère flexion de hanche et adduction jusqu’à la barrière motrice. Le praticien majore le contact inguinal de la main céphalique par un mouvement antérieur de son pelvis.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’adduction et la pression inguinale.","photo":"assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p046-dysfonction-de-la-coxo-femorale-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":46,"sourceRow":105}},{"slug":"ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite","sourceRow":106,"sourceBook":"OSTPRA3","sourcePage":48,"matchers":["dysfonction de la coxo femorale en adduction a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en adduction, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus du côté opposé à la dysfonction. Le membre inférieur sous‑jacent est en flexion de hanche et de genou.\nPRATICIEN Debout derrière le sujet à la hauteur du pelvis pour le stabiliser.\n\nPOSITION DES MAINS\nLa main et l’avant-bras caudaux soutiennent en berceau le membre inférieur en dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en abduction puis majorer l’appui sur le grand trochanter jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction du genou fléchi sous-jacent en majorant à la fois l’abduction et la pression sur le grand trochanter.","detail":{"source":"OSTPRA3 - page 48","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en adduction, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé à la dysfonction. Le membre inférieur sous‑jacent est en flexion de hanche et de genou.\nPRATICIEN Debout derrière le sujet à la hauteur du pelvis pour le stabiliser.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur en dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en abduction puis majorer l’appui sur le grand trochanter jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction du genou fléchi sous-jacent en majorant à la fois l’abduction et la pression sur le grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p048-dysfonction-de-la-coxo-femorale-en-adduction-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":48,"sourceRow":106}},{"slug":"ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite","sourceRow":107,"sourceBook":"OSTPRA3","sourcePage":50,"matchers":["dysfonction de la coxo femorale en flexion a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en flexion, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur des cuisses, du côté opposé à la dysfonction.\n\nPOSITION DES MAINS\nLa main et l’avant-bras caudaux soutiennent en berceau le membre inférieur homolatéral à la dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en extension jusqu’à la barrière motrice et majorer le contact trochantérien.\n\nNORMALISATION\nPorter le thrust en majorant à la fois l’extension et la pression sur le grand trochanter.","detail":{"source":"OSTPRA3 - page 50","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en flexion, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, la tête est tournée du côté de la dysfonction.\nPRATICIEN Debout à la hauteur des cuisses, du côté opposé à la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main et l’avant-bras caudaux soutiennent en berceau le membre inférieur homolatéral à la dysfonction. Le talon de la main céphalique contacte la face postérieure du grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en extension jusqu’à la barrière motrice et majorer le contact trochantérien.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant à la fois l’extension et la pression sur le grand trochanter.","photo":"assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p050-dysfonction-de-la-coxo-femorale-en-flexion-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":50,"sourceRow":107}},{"slug":"ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite","sourceRow":108,"sourceBook":"OSTPRA3","sourcePage":52,"matchers":["dysfonction de la coxo femorale en anteriorite classique a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en antériorité classique, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table aux pieds du sujet.\n\nPOSITION DES MAINS\nLa main externe empaume l’extrémité distale et postérieure du tibia du membre inférieur en dysfonction. La main interne empaume l’extrémité distale et antérieure du tibia.\n\nBARRIÈRE MOTRICE\nLe praticien cherche à amener la hanche en adduction et en rotation interne de hanche jusqu’à la barrière motrice.\n\nNORMALISATION\nSoulever le membre inférieur de façon à permettre une adduction de la hanche au-delà de l’axe médian du corps. Le praticien transfert son poids sur la jambe externe de façon à amener le membre inférieur en abduction et rotation externe. Il transfert ensuite son poids sur la jambe interne pour porter un thrust en majorant à la fois l’adduction et la rotation interne. Renouveler la manœuvre si nécessaire.","detail":{"source":"OSTPRA3 - page 52","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en antériorité classique, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table aux pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume l’extrémité distale et postérieure du tibia du membre inférieur en dysfonction. La main interne empaume l’extrémité distale et antérieure du tibia.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le praticien cherche à amener la hanche en adduction et en rotation interne de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Soulever le membre inférieur de façon à permettre une adduction de la hanche au-delà de l’axe médian du corps. Le praticien transfert son poids sur la jambe externe de façon à amener le membre inférieur en abduction et rotation externe. Il transfert ensuite son poids sur la jambe interne pour porter un thrust en majorant à la fois l’adduction et la rotation interne. Renouveler la manœuvre si nécessaire.","photo":"assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p052-dysfonction-de-la-coxo-femorale-en-anteriorite-classique-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":52,"sourceRow":108}},{"slug":"ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite","sourceRow":109,"sourceBook":"OSTPRA3","sourcePage":54,"matchers":["dysfonction de la coxo femorale en posteriorite a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE, en postériorité, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main externe et le sillon delto‑pectoral calent le genou fléchi du membre inférieur en dysfonction. La main interne stabilise le pelvis par un contre-appui sur l’épine iliaque antéro-supérieure controlatérale.\n\nBARRIÈRE MOTRICE\nExercer quatre séries de trois pressions. D’abord dans l’axe fémoral en direction de la table, puis en adduction, puis en abduction puis en flexion. La mise en tension se termine par une série de circumduction de plus en plus ample jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en fin de circumduction en majorant l’abduction et la rotation externe dans un mouvement de haute vélocité.","detail":{"source":"OSTPRA3 - page 54","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE, en postériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe et le sillon delto‑pectoral calent le genou fléchi du membre inférieur en dysfonction. La main interne stabilise le pelvis par un contre-appui sur l’épine iliaque antéro-supérieure controlatérale.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Exercer quatre séries de trois pressions. D’abord dans l’axe fémoral en direction de la table, puis en adduction, puis en abduction puis en flexion. La mise en tension se termine par une série de circumduction de plus en plus ample jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en fin de circumduction en majorant l’abduction et la rotation externe dans un mouvement de haute vélocité.","photo":"assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p054-dysfonction-de-la-coxo-femorale-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":54,"sourceRow":109}},{"slug":"ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-","sourceRow":110,"sourceBook":"OSTPRA3","sourcePage":56,"matchers":["dysfonction de la coxo femorale articulaire globale dans un axe transversal a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE dans un axe transversal, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.\n\nPOSITION DES MAINS\nLes deux mains superposées empaument la partie supéro-interne de la cuisse du membre inférieur en dysfonction. La face externe du genou est stabilisée par le sternum du praticien.\n\nBARRIÈRE MOTRICE\nMajorer la compression des tissus de la face interne de la cuisse.\n\nNORMALISATION\nÀ l’aide du sternum, exercer une pression sur le genou. Les deux mains tractent la cuisse en direction du haut et du dehors – À répéter plusieurs fois dans un mouvement de pompage.","detail":{"source":"OSTPRA3 - page 56","category":"Membre inférieur – coxo-fémorale","method":"Mobilisation","intro":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE dans un axe transversal, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains superposées empaument la partie supéro-interne de la cuisse du membre inférieur en dysfonction. La face externe du genou est stabilisée par le sternum du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la compression des tissus de la face interne de la cuisse.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"À l’aide du sternum, exercer une pression sur le genou. Les deux mains tractent la cuisse en direction du haut et du dehors – À répéter plusieurs fois dans un mouvement de pompage.","photo":"assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p056-dysfonction-de-la-coxo-femorale-articulaire-globale-dans-un-axe-transversal-/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":56,"sourceRow":110}},{"slug":"ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite","sourceRow":111,"sourceBook":"OSTPRA3","sourcePage":58,"matchers":["dysfonction de la coxo femorale articulaire globale en anteriorite a droite"],"title":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE, en antériorité, à droite","zone":"Membres inférieurs","sub":"Hanche","level":"Niveau intermédiaire","status":"non vue","icon":"H","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis, en fente avant du côté de la dysfonction.\n\nPOSITION DES MAINS\nLa main caudale empaume le genou du membre inférieur en dysfonction et l’avant-bras stabilise la face interne du segment jambier. La main céphalique stabilise le pelvis par un contact sur l’épine iliaque antéro-supérieure opposée.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en rotation interne jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en direction de la table.","detail":{"source":"OSTPRA3 - page 58","category":"Membre inférieur – coxo-fémorale","method":"Thrust","intro":"DYSFONCTION DE LA COXO-FÉMORALE ARTICULAIRE GLOBALE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en flexion de hanche à 90°, le genou est fléchi.\nPRATICIEN Debout à la hauteur du pelvis, en fente avant du côté de la dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le genou du membre inférieur en dysfonction et l’avant-bras stabilise la face interne du segment jambier. La main céphalique stabilise le pelvis par un contact sur l’épine iliaque antéro-supérieure opposée.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en rotation interne jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p058-dysfonction-de-la-coxo-femorale-articulaire-globale-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":58,"sourceRow":111}},{"slug":"ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche","sourceRow":112,"sourceBook":"OSTPRA3","sourcePage":60,"matchers":["dysfonction de la femoro tibiale en abduction a gauche"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en abduction, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.\n\nPOSITION DES MAINS\nPlacer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou, les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.\n\nBARRIÈRE MOTRICE\nDéverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’adduction du genou jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main applicatrice interne de dedans en dehors.","detail":{"source":"OSTPRA3 - page 60","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en abduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou, les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’adduction du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p060-dysfonction-de-la-femoro-tibiale-en-abduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":60,"sourceRow":112}},{"slug":"ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche","sourceRow":113,"sourceBook":"OSTPRA3","sourcePage":62,"matchers":["dysfonction de la femoro tibiale en adduction a gauche"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en adduction, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.\n\nPOSITION DES MAINS\nPlacer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou. Les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.\n\nBARRIÈRE MOTRICE\nDéverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’abduction du genou jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main applicatrice externe de dehors en dedans.","detail":{"source":"OSTPRA3 - page 62","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en adduction, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe en dysfonction entre les cuisses. Empaumer par les deux mains les faces latérales du genou. Les doigts sont croisés dans la fosse poplitée. Les avant-bras, dans le prolongement l’un de l’autre, sont dans l’axe de l’interligne articulaire fémoro-tibial.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer l’abduction du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main applicatrice externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p062-dysfonction-de-la-femoro-tibiale-en-adduction-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":62,"sourceRow":113}},{"slug":"ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche","sourceRow":114,"sourceBook":"OSTPRA3","sourcePage":64,"matchers":["dysfonction de la femoro tibiale en anteriorite a gauche"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.\n\nPOSITION DES MAINS\nLe talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.\n\nBARRIÈRE MOTRICE\nMajorer, par les deux mains applicatrices, la pression sur la tubérosité tibiale antérieure vers l’arrière jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par les deux mains vers l’arrière.","detail":{"source":"OSTPRA3 - page 64","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer, par les deux mains applicatrices, la pression sur la tubérosité tibiale antérieure vers l’arrière jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’arrière.","photo":"assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p064-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":64,"sourceRow":114}},{"slug":"ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche","sourceRow":115,"sourceBook":"OSTPRA3","sourcePage":66,"matchers":["dysfonction de la femoro tibiale en anteriorite a gauche"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.\n\nPOSITION DES MAINS\nLe talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.\n\nBARRIÈRE MOTRICE\nTracter, par les deux mains applicatrices, le plateau tibial vers l’avant jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par les deux mains vers l’avant.","detail":{"source":"OSTPRA3 - page 66","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le genou est fléchi à 90°, le pied est posé sur la table.\nPRATICIEN Assis en bord de table au niveau du pied du patient, l’avant-pied est stabilisé par la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le talon des deux mains est posé de part et d’autre de la tubérosité tibiale antérieure. Les pouces sont orientés vers le haut et les autres doigts sont posés au niveau de la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Tracter, par les deux mains applicatrices, le plateau tibial vers l’avant jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains vers l’avant.","photo":"assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p066-dysfonction-de-la-femoro-tibiale-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":66,"sourceRow":115}},{"slug":"ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite","sourceRow":116,"sourceBook":"OSTPRA3","sourcePage":68,"matchers":["dysfonction de la femoro tibiale en rotation interne a droite"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation interne, à droite","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur de la jambe, en fente avant.\n\nPOSITION DES MAINS\nLa main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial interne.\n\nBARRIÈRE MOTRICE\nLa main caudale amène le segment jambier en rotation externe et en flexion complète du genou jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la flexion du genou par la main caudale.","detail":{"source":"OSTPRA3 - page 68","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation interne, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout à la hauteur de la jambe, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial interne.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation externe et en flexion complète du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale.","photo":"assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p068-dysfonction-de-la-femoro-tibiale-en-rotation-interne-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":68,"sourceRow":116}},{"slug":"ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite","sourceRow":117,"sourceBook":"OSTPRA3","sourcePage":70,"matchers":["dysfonction de la femoro tibiale en rotation externe a droite"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation externe, à droite","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout en fente avant à la hauteur de la jambe en dysfonction.\n\nPOSITION DES MAINS\nLa main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial externe.\n\nBARRIÈRE MOTRICE\nLa main caudale amène le segment jambier en rotation interne et en flexion complète du genou jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la flexion du genou par la main caudale.","detail":{"source":"OSTPRA3 - page 70","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en rotation externe, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en flexion de hanche et de genou.\nPRATICIEN Debout en fente avant à la hauteur de la jambe en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité distale de la jambe, la main céphalique est placée dans la fosse poplitée en regard du plateau tibial externe.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène le segment jambier en rotation interne et en flexion complète du genou jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale.","photo":"assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p070-dysfonction-de-la-femoro-tibiale-en-rotation-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":70,"sourceRow":117}},{"slug":"ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite","sourceRow":118,"sourceBook":"OSTPRA3","sourcePage":72,"matchers":["dysfonction du menisque medial en posteriorite et en extension a droite"],"title":"DYSFONCTION DU MÉNISQUE MÉDIAL, en postériorité et en extension, à droite","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.\n\nPOSITION DES MAINS\nLa main caudale empaume la face plantaire du pied. La main céphalique empaume la partie supérieure du genou. L’index contacte l’interligne fémoro-tibial interne en regard de la corne antérieure du ménisque interne en dysfonction.\n\nBARRIÈRE MOTRICE\nAmener le tibia en rotation externe et en abduction pour ouvrir le compartiment interne. Ramener le talon du sujet sur la table. Puis tourner la main céphalique de telle façon à ce que le pouce remplace l’index au contact du ménisque médial et que les autres doigts soutiennent le genou.\n\nNORMALISATION\nLa normalisation dynamique se fait en amenant simultanément le genou en extension complète, en adduction et en rotation interne.","detail":{"source":"OSTPRA3 - page 72","category":"Membre inférieur – fémoro-tibiale","method":"Mobilisation","intro":"DYSFONCTION DU MÉNISQUE MÉDIAL, en postériorité et en extension, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume la face plantaire du pied. La main céphalique empaume la partie supérieure du genou. L’index contacte l’interligne fémoro-tibial interne en regard de la corne antérieure du ménisque interne en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le tibia en rotation externe et en abduction pour ouvrir le compartiment interne. Ramener le talon du sujet sur la table. Puis tourner la main céphalique de telle façon à ce que le pouce remplace l’index au contact du ménisque médial et que les autres doigts soutiennent le genou.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"La normalisation dynamique se fait en amenant simultanément le genou en extension complète, en adduction et en rotation interne.","photo":"assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p072-dysfonction-du-menisque-medial-en-posteriorite-et-en-extension-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":72,"sourceRow":118}},{"slug":"ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche","sourceRow":119,"sourceBook":"OSTPRA3","sourcePage":74,"matchers":["dysfonction de la femoro tibiale en translation interne a gauche"],"title":"DYSFONCTION DE LA FÉMORO-TIBIALE, en translation interne, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.\n\nPOSITION DES MAINS\nPlacer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité inférieure de la cuisse, au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité supérieure du tibia, en dessous de l’interligne articulaire.\n\nBARRIÈRE MOTRICE\nDéverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial interne de dedans en dehors jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main interne de dedans en dehors.","detail":{"source":"OSTPRA3 - page 74","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION DE LA FÉMORO-TIBIALE, en translation interne, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité inférieure de la cuisse, au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité supérieure du tibia, en dessous de l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial interne de dedans en dehors jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne de dedans en dehors.","photo":"assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p074-dysfonction-de-la-femoro-tibiale-en-translation-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":74,"sourceRow":119}},{"slug":"ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche","sourceRow":120,"sourceBook":"OSTPRA3","sourcePage":76,"matchers":["dysfonction femoro tibiale en translation externe a gauche"],"title":"DYSFONCTION FÉMORO-TIBIALE, en translation externe, à gauche","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.\n\nPOSITION DES MAINS\nPlacer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité supérieure du tibia au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité inférieure de la cuisse en dessous de l’interligne articulaire.\n\nBARRIÈRE MOTRICE\nDéverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial externe de dehors en dedans jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main externe de dehors en dedans.","detail":{"source":"OSTPRA3 - page 76","category":"Membre inférieur – fémoro-tibiale","method":"Thrust","intro":"DYSFONCTION FÉMORO-TIBIALE, en translation externe, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le membre inférieur en dysfonction est en dehors de la table.\nPRATICIEN Debout à la hauteur de la cheville, dans l’axe du membre inférieur, les deux pieds sont croisés.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Placer et maintenir l’extrémité distale de la jambe entre les cuisses. La main externe empaume la face latérale externe de l’extrémité supérieure du tibia au dessus de l’interligne articulaire. La main interne empaume la face latérale interne de l’extrémité inférieure de la cuisse en dessous de l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Déverrouiller le genou par une flexion de quelques degrés. Le praticien exerce une traction sur le membre inférieur. Majorer la pression sur le plateau tibial externe de dehors en dedans jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main externe de dehors en dedans.","photo":"assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p076-dysfonction-femoro-tibiale-en-translation-externe-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":76,"sourceRow":120}},{"slug":"ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite","sourceRow":121,"sourceBook":"OSTPRA3","sourcePage":78,"matchers":["dysfonction du menisque medial en posteriorite en flexion a droite"],"title":"DYSFONCTION DU MÉNISQUE MÉDIAL en postériorité, en flexion, à droite","zone":"Membres inférieurs","sub":"Genou","level":"Niveau intermédiaire","status":"non vue","icon":"G","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, la hanche et le genou sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.\n\nPOSITION DES MAINS\nLa main caudale saisit l’extrémité inférieure du segment jambier en dysfonction. Les doigts de la main céphalique contactent l’interligne articulaire fémoro-tibial interne, en regard du ménisque médial. La face externe du genou est stabilisée par le sternum du praticien.\n\nBARRIÈRE MOTRICE\nAmener le genou en abduction et en rotation externe afin de favoriser l’ouverture du compartiment articulaire interne.\n\nNORMALISATION\nLa main caudale amène le genou en rotation interne et en flexion complète du genou dans un mouvement dynamique. La main céphalique reste, quant à elle, au contact du ménisque.","detail":{"source":"OSTPRA3 - page 78","category":"Membre inférieur – fémoro-tibiale","method":"Mobilisation","intro":"DYSFONCTION DU MÉNISQUE MÉDIAL en postériorité, en flexion, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inférieure du segment jambier en dysfonction. Les doigts de la main céphalique contactent l’interligne articulaire fémoro-tibial interne, en regard du ménisque médial. La face externe du genou est stabilisée par le sternum du praticien.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le genou en abduction et en rotation externe afin de favoriser l’ouverture du compartiment articulaire interne.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"La main caudale amène le genou en rotation interne et en flexion complète du genou dans un mouvement dynamique. La main céphalique reste, quant à elle, au contact du ménisque.","photo":"assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p078-dysfonction-du-menisque-medial-en-posteriorite-en-flexion-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":78,"sourceRow":121}},{"slug":"ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche","sourceRow":122,"sourceBook":"OSTPRA3","sourcePage":80,"matchers":["dysfonction de la fibulo tibiale superieure en posteriorite a gauche"],"title":"DYSFONCTION DE LA FIBULO-TIBIALE SUPÉRIEURE, en postériorité, à gauche","zone":"Membres inférieurs","sub":"Tibia-fibula","level":"Niveau intermédiaire","status":"non vue","icon":"TF","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou, en fente avant.\n\nPOSITION DES MAINS\nLa main caudale saisit l’extrémité inféro-interne de la jambe. La métacarpo-phalangienne de l’index de la main céphalique contacte la face postérieure de la tête péronière formant ainsi un contre appui dans la fosse poplitée.\n\nBARRIÈRE MOTRICE\nAmener le membre inférieur en flexion de hanche et de genou en y associant une rotation externe du segment jambier et une abduction de hanche jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust en majorant la flexion du genou par la main caudale. La main céphalique restant au contact de la face postérieure de la fibula. Le sternum en appui sur la face antérieure du tibia accompagne le mouvement.","detail":{"source":"OSTPRA3 - page 80","category":"Membre inférieur – fibulo-tibiale supérieure","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE SUPÉRIEURE, en postériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, la hanche et le genou du membre inférieur en dysfonction sont fléchis à 90°.\nPRATICIEN Debout à la hauteur du genou, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale saisit l’extrémité inféro-interne de la jambe. La métacarpo-phalangienne de l’index de la main céphalique contacte la face postérieure de la tête péronière formant ainsi un contre appui dans la fosse poplitée.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le membre inférieur en flexion de hanche et de genou en y associant une rotation externe du segment jambier et une abduction de hanche jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust en majorant la flexion du genou par la main caudale. La main céphalique restant au contact de la face postérieure de la fibula. Le sternum en appui sur la face antérieure du tibia accompagne le mouvement.","photo":"assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p080-dysfonction-de-la-fibulo-tibiale-superieure-en-posteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":80,"sourceRow":122}},{"slug":"ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche","sourceRow":123,"sourceBook":"OSTPRA3","sourcePage":82,"matchers":["dysfonction de la fibulo tibiale inferieure en anteriorite a gauche"],"title":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en antériorité, à gauche","zone":"Membres inférieurs","sub":"Tibia-fibula","level":"Niveau intermédiaire","status":"non vue","icon":"TF","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le pied est posé sur la table.\nPRATICIEN Debout face au pied du sujet, en bout de table.\n\nPOSITION DES MAINS\nLes deux mains empaument le pied. La pulpe du pouce externe contacte la face antérieure de la malléole externe, les autres doigts sont sur le talon. Le pouce de la main interne renforce l’appui initial.\n\nBARRIÈRE MOTRICE\nAmener le pied en légère flexion dorsale. Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par les deux pouces en direction de la table.","detail":{"source":"OSTPRA3 - page 82","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en antériorité, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est posé sur la table.\nPRATICIEN Debout face au pied du sujet, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains empaument le pied. La pulpe du pouce externe contacte la face antérieure de la malléole externe, les autres doigts sont sur le talon. Le pouce de la main interne renforce l’appui initial.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en légère flexion dorsale. Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p082-dysfonction-de-la-fibulo-tibiale-inferieure-en-anteriorite-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":82,"sourceRow":123}},{"slug":"ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite","sourceRow":124,"sourceBook":"OSTPRA3","sourcePage":84,"matchers":["dysfonction de la fibulo tibiale inferieure en posteriorite a droite"],"title":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en postériorité, à droite","zone":"Membres inférieurs","sub":"Tibia-fibula","level":"Niveau intermédiaire","status":"non vue","icon":"TF","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table, face au pied du patient, la plante du pied contacte la cuisse du\npraticien.\n\nPOSITION DES MAINS\nLa pulpe du pouce de la main externe est en appui sur la face postérieure de la malléole externe, les autres doigts maintiennent et stabilisent l’avant-pied en légère flexion dorsale. Le pouce interne renforce l’appui initial.\n\nBARRIÈRE MOTRICE\nLe pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par les deux pouces en direction du sol.","detail":{"source":"OSTPRA3 - page 84","category":"Membre inferieur – fibulo-tibiale inférieur","method":"Thrust","intro":"DYSFONCTION DE LA FIBULO-TIBIALE INFÉRIEURE, en postériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, les pieds sont en dehors de la table.\nPRATICIEN Debout, en bout de table, face au pied du patient, la plante du pied contacte la cuisse du\npraticien.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La pulpe du pouce de la main externe est en appui sur la face postérieure de la malléole externe, les autres doigts maintiennent et stabilisent l’avant-pied en légère flexion dorsale. Le pouce interne renforce l’appui initial.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Le pouce majore la pression sur la malléole externe en direction du sol jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux pouces en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p084-dysfonction-de-la-fibulo-tibiale-inferieure-en-posteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":84,"sourceRow":124}},{"slug":"ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a","sourceRow":125,"sourceBook":"OSTPRA3","sourcePage":86,"matchers":["dysfonction de la tibio tarsienne articulaire globale en decubitus ventral a gauche"],"title":"DYSFONCTION DE LA TIBIO-TARSIENNE ARTICULAIRE GLOBALE, en décubitus ventral, à gauche","zone":"Membres inférieurs","sub":"Cheville","level":"Niveau intermédiaire","status":"non vue","icon":"CH","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, le genou est fléchi à 90°.\nPRATICIEN Debout à la hauteur du genou.\n\nPOSITION DES MAINS\nLe genou céphalique maintient la face postérieure de la cuisse au dessus de la fosse poplitée. Les deux mains, les doigts sont croisés en regard de la malléole interne, enserrent la cheville en dysfonction. Les avant-bras sont à l’horizontale.\n\nBARRIÈRE MOTRICE\nAmener le pied en position neutre et exercer une légère traction en direction du plafond jusqu’à la barrière motrice.\n\nNORMALISATION\nMajorer la traction par une traction verticale (lift) des deux mains dans l’axe tibial.","detail":{"source":"OSTPRA3 - page 86","category":"Membre inférieur – tibio-tarsienne","method":"Lift","intro":"DYSFONCTION DE LA TIBIO-TARSIENNE ARTICULAIRE GLOBALE, en décubitus ventral, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le genou est fléchi à 90°.\nPRATICIEN Debout à la hauteur du genou.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Le genou céphalique maintient la face postérieure de la cuisse au dessus de la fosse poplitée. Les deux mains, les doigts sont croisés en regard de la malléole interne, enserrent la cheville en dysfonction. Les avant-bras sont à l’horizontale.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en position neutre et exercer une légère traction en direction du plafond jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Majorer la traction par une traction verticale (lift) des deux mains dans l’axe tibial.","photo":"assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p086-dysfonction-de-la-tibio-tarsienne-articulaire-globale-en-decubitus-ventral-a/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":86,"sourceRow":125}},{"slug":"ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite","sourceRow":126,"sourceBook":"OSTPRA3","sourcePage":88,"matchers":["entorse tibio tarsienne externe a droite"],"title":"ENTORSE TIBIO-TARSIENNE EXTERNE, à droite","zone":"Membres inférieurs","sub":"Cheville","level":"Niveau intermédiaire","status":"non vue","icon":"CH","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.\n\nPOSITION DES MAINS\nLa main externe empaume le talon, le pouce contacte le col du talus. La main interne renforce l’appui en maintenant le coup de pied en légère flexion dorsale.\n\nBARRIÈRE MOTRICE\nMajorer la flexion dorsale du pied et ajouter une composante d’éversion jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust sur le talus par le pouce en « snap » vers l’arrière et le dedans.","detail":{"source":"OSTPRA3 - page 88","category":"Membre inférieur – tibio-tarsienne","method":"Snap","intro":"ENTORSE TIBIO-TARSIENNE EXTERNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon, le pouce contacte le col du talus. La main interne renforce l’appui en maintenant le coup de pied en légère flexion dorsale.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Majorer la flexion dorsale du pied et ajouter une composante d’éversion jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust sur le talus par le pouce en « snap » vers l’arrière et le dedans.","photo":"assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p088-entorse-tibio-tarsienne-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":88,"sourceRow":126}},{"slug":"ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite","sourceRow":127,"sourceBook":"OSTPRA3","sourcePage":90,"matchers":["dysfonction de la tibio tarsienne en anteriorite a droite"],"title":"DYSFONCTION DE LA TIBIO-TARSIENNE, en antériorité, à droite","zone":"Membres inférieurs","sub":"Cheville","level":"Niveau intermédiaire","status":"non vue","icon":"CH","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal.\nPRATICIEN Debout à la hauteur de la cheville.\n\nPOSITION DES MAINS\nLa main caudale empaume le talon. La première commissure de la main céphalique maintient la face antérieure du pilon tibial.\n\nBARRIÈRE MOTRICE\nMaintenir le pied en légère flexion dorsale. La main céphalique majore la pression vers l’arrière jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main céphalique en direction du sol.","detail":{"source":"OSTPRA3 - page 90","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"DYSFONCTION DE LA TIBIO-TARSIENNE, en antériorité, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal.\nPRATICIEN Debout à la hauteur de la cheville.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le talon. La première commissure de la main céphalique maintient la face antérieure du pilon tibial.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Maintenir le pied en légère flexion dorsale. La main céphalique majore la pression vers l’arrière jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction du sol.","photo":"assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p090-dysfonction-de-la-tibio-tarsienne-en-anteriorite-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":90,"sourceRow":127}},{"slug":"ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche","sourceRow":128,"sourceBook":"OSTPRA3","sourcePage":92,"matchers":["decoaptation de la tibio tarsienne globale a gauche"],"title":"DÉCOAPTATION DE LA TIBIO-TARSIENNE GLOBALE, à gauche","zone":"Membres inférieurs","sub":"Cheville","level":"Niveau intermédiaire","status":"non vue","icon":"CH","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Position semi-accroupie en bout de table à la hauteur du pied du sujet.\n\nPOSITION DES MAINS\nLes deux mains sont croisées sur le coup de pied, les bords cubitaux des deux mains contactent le col du talus.\n\nBARRIÈRE MOTRICE\nAmener le pied en flexion dorsale et exercer une traction dans l’axe tibial jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par les deux mains en majorant la traction du pied.","detail":{"source":"OSTPRA3 - page 92","category":"Membre inférieur – tibio-tarsienne","method":"Thrust","intro":"DÉCOAPTATION DE LA TIBIO-TARSIENNE GLOBALE, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Position semi-accroupie en bout de table à la hauteur du pied du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains sont croisées sur le coup de pied, les bords cubitaux des deux mains contactent le col du talus.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied en flexion dorsale et exercer une traction dans l’axe tibial jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par les deux mains en majorant la traction du pied.","photo":"assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p092-decoaptation-de-la-tibio-tarsienne-globale-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":92,"sourceRow":128}},{"slug":"ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche","sourceRow":129,"sourceBook":"OSTPRA3","sourcePage":94,"matchers":["dysfonction de la sous astragalienne antero interne a gauche"],"title":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE ANTÉRO-INTERNE, à gauche","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, le pied est en dehors de la table.\nPRATICIEN Debout entre les jambes du sujet, à la hauteur du pied en dysfonction.\n\nPOSITION DES MAINS\nEmpaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. Le pisiforme de la main céphalique contact la tête du talus en dedans du tibial antérieur.\n\nBARRIÈRE MOTRICE\nAmener le pied successivement en inversion, en flexion dorsale, en éversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","detail":{"source":"OSTPRA3 - page 94","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE ANTÉRO-INTERNE, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, le pied est en dehors de la table.\nPRATICIEN Debout entre les jambes du sujet, à la hauteur du pied en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. Le pisiforme de la main céphalique contact la tête du talus en dedans du tibial antérieur.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener le pied successivement en inversion, en flexion dorsale, en éversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","photo":"assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p094-dysfonction-de-la-sous-astragalienne-antero-interne-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":94,"sourceRow":129}},{"slug":"ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite","sourceRow":130,"sourceBook":"OSTPRA3","sourcePage":96,"matchers":["dysfonction de la sous astragalienne postero externe a droite"],"title":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE POSTÉRO-EXTERNE, à droite","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur du pied en dysfonction.\n\nPOSITION DES MAINS\nEmpaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. La main céphalique contacte par le pisiforme la tête du talus, en dehors de l’extenseur commun des orteils.\n\nBARRIÈRE MOTRICE\nAmener successivement le pied en éversion, en flexion dorsale, en inversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","detail":{"source":"OSTPRA3 - page 96","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-ASTRAGALIENNE POSTÉRO-EXTERNE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur du pied en dysfonction.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Empaumer le talon par la main caudale, l’avant-bras contacte la face plantaire du pied en dysfonction. La main céphalique contacte par le pisiforme la tête du talus, en dehors de l’extenseur commun des orteils.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Amener successivement le pied en éversion, en flexion dorsale, en inversion et en flexion plantaire. Répéter le mouvement plusieurs fois jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en flexion plantaire, sur la tête astragalienne.","photo":"assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p096-dysfonction-de-la-sous-astragalienne-postero-externe-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":96,"sourceRow":130}},{"slug":"ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche","sourceRow":131,"sourceBook":"OSTPRA3","sourcePage":98,"matchers":["dysfonction de la sous talienne calcaneus en varus a gauche"],"title":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en varus, à gauche","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/planche-photos.webp","text":"POSITION\nPATIENT En latérocubitus du côté opposé au membre inférieur en dysfonction. Les genoux sont fléchis, le pied sus-jacent est légèrement en retrait.\nPRATICIEN Debout à la hauteur des pieds.\n\nPOSITION DES MAINS\nLa main caudale empaume le calcanéus en dysfonction. Le bord cubital de la main céphalique contacte la face supéro-externe du calcanéus.\n\nBARRIÈRE MOTRICE\nLa main caudale amène et maintient le calcanéus en valgus. Exercer par la main céphalique une pression progressive, en direction de la table, sur la face externe du calcanéus jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main céphalique en direction de la table.","detail":{"source":"OSTPRA3 - page 98","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en varus, à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En latérocubitus du côté opposé au membre inférieur en dysfonction. Les genoux sont fléchis, le pied sus-jacent est légèrement en retrait.\nPRATICIEN Debout à la hauteur des pieds.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main caudale empaume le calcanéus en dysfonction. Le bord cubital de la main céphalique contacte la face supéro-externe du calcanéus.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène et maintient le calcanéus en valgus. Exercer par la main céphalique une pression progressive, en direction de la table, sur la face externe du calcanéus jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p098-dysfonction-de-la-sous-talienne-calcaneus-en-varus-a-gauche/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":98,"sourceRow":131}},{"slug":"ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite","sourceRow":132,"sourceBook":"OSTPRA3","sourcePage":100,"matchers":["dysfonction de la sous talienne calcaneus en valgus a droite"],"title":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en valgus, à droite","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les genoux sont fléchis, le pied en dysfonction est en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur des pieds du sujet.\n\nPOSITION DES MAINS\nAmener le talon en dysfonction en dehors de la table, le reste du pied est sur la table. La main caudale empaume et fixe l’avant-pied en éversion. La main céphalique empaume la face interne du calcanéus.\n\nBARRIÈRE MOTRICE\nLa main céphalique maintient le calcanéus en valgus. La main caudale exerce une pression progressive, en direction de la table jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main céphalique en direction de la table.","detail":{"source":"OSTPRA3 - page 100","category":"Membre inférieur – sous-astragalienne","method":"Thrust","intro":"DYSFONCTION DE LA SOUS-TALIENNE, calcanéus en valgus, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les genoux sont fléchis, le pied en dysfonction est en dehors de la table.\nPRATICIEN Debout en bout de table, à la hauteur des pieds du sujet.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Amener le talon en dysfonction en dehors de la table, le reste du pied est sur la table. La main caudale empaume et fixe l’avant-pied en éversion. La main céphalique empaume la face interne du calcanéus.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique maintient le calcanéus en valgus. La main caudale exerce une pression progressive, en direction de la table jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main céphalique en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p100-dysfonction-de-la-sous-talienne-calcaneus-en-valgus-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":100,"sourceRow":132}},{"slug":"ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch","sourceRow":133,"sourceBook":"OSTPRA3","sourcePage":102,"matchers":["dysfonction de la calcaneo cuboidienne en rotation interne pronation a gauche"],"title":"DYSFONCTION DE LA CALCANÉO-CUBOÏDIENNE, en rotation interne (pronation), à gauche","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.\n\nPOSITION DES MAINS\nLa main externe empaume le talon en dysfonction, le pouce contacte le col du talus en avant de la malléole externe. La main opposée enserre entre le pouce et les autres doigts la face plantaire et dorsale du pied, jusqu’au 4e et 5e métatarsiens (sous l’interligne cuboïdo-métatarsien)\n\nBARRIÈRE MOTRICE\nLa main externe fixe le talon, la main interne amène l’avant-pied en supination jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust par la main interne en supination de l’avant-pied.","detail":{"source":"OSTPRA3 - page 102","category":"Membre inférieur – calcanéo-cuboïdienne","method":"Thrust","intro":"DYSFONCTION DE LA CALCANÉO-CUBOÏDIENNE, en rotation interne (pronation), à gauche","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout face au pied du patient, en bout de table.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main externe empaume le talon en dysfonction, le pouce contacte le col du talus en avant de la malléole externe. La main opposée enserre entre le pouce et les autres doigts la face plantaire et dorsale du pied, jusqu’au 4e et 5e métatarsiens (sous l’interligne cuboïdo-métatarsien)","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main externe fixe le talon, la main interne amène l’avant-pied en supination jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust par la main interne en supination de l’avant-pied.","photo":"assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p102-dysfonction-de-la-calcaneo-cuboidienne-en-rotation-interne-pronation-a-gauch/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":102,"sourceRow":133}},{"slug":"ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite","sourceRow":134,"sourceBook":"OSTPRA3","sourcePage":104,"matchers":["dysfonction talo naviculaire en rotation externe supination a droite"],"title":"DYSFONCTION TALO-NAVICULAIRE, en rotation externe (supination), à droite","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout du côté de la dysfonction à la hauteur du pied du patient.\n\nPOSITION DES MAINS\nLa main céphalique empaume l’extrémité inférieure du segment jambier, l’index est sur le col du talus en dysfonction. La main caudale contacte la face supérieure et interne de l’avant pied, son index est sur la partie interne de l’os naviculaire.\n\nBARRIÈRE MOTRICE\nLa main caudale amène l’os naviculaire en pronation jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust, par la main caudale en pronation, en direction de la table.","detail":{"source":"OSTPRA3 - page 104","category":"Membre inférieur – talo-naviculaire","method":"Thrust","intro":"DYSFONCTION TALO-NAVICULAIRE, en rotation externe (supination), à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout du côté de la dysfonction à la hauteur du pied du patient.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume l’extrémité inférieure du segment jambier, l’index est sur le col du talus en dysfonction. La main caudale contacte la face supérieure et interne de l’avant pied, son index est sur la partie interne de l’os naviculaire.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main caudale amène l’os naviculaire en pronation jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale en pronation, en direction de la table.","photo":"assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p104-dysfonction-talo-naviculaire-en-rotation-externe-supination-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":104,"sourceRow":134}},{"slug":"ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite","sourceRow":135,"sourceBook":"OSTPRA3","sourcePage":106,"matchers":["dysfonction de la naviculo cuboidienne articulaire globale a droite"],"title":"DYSFONCTION DE LA NAVICULO-CUBOÏDIENNE ARTICULAIRE GLOBALE, à droite","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/planche-photos.webp","text":"POSITION\nPATIENT En procubitus, le membre inférieur en dysfonction est en dehors de la table, le genou est fléchi.\nPRATICIEN Debout face au pied du patient, en fente avant.\n\nPOSITION DES MAINS\nLes deux mains enserrent les bords interne et externe du pied. Les pouces sont superposés sur l’interligne articulaire naviculo-cuboïdien de la face plantaire, les autres doigts soutiennent la face dorsale du pied.\n\nBARRIÈRE MOTRICE\nMobiliser le membre inférieur par plusieurs mouvements en piston jusqu’à la barrière motrice.\n\nNORMALISATION\nEn fin de mouvement, porter le thrust en « snap » par les deux pouces en majorant la flexion plantaire et la pression sur l’interligne articulaire.","detail":{"source":"OSTPRA3 - page 106","category":"Membre inférieur – naviculo-cuboïdienne","method":"Snap","intro":"DYSFONCTION DE LA NAVICULO-CUBOÏDIENNE ARTICULAIRE GLOBALE, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En procubitus, le membre inférieur en dysfonction est en dehors de la table, le genou est fléchi.\nPRATICIEN Debout face au pied du patient, en fente avant.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"Les deux mains enserrent les bords interne et externe du pied. Les pouces sont superposés sur l’interligne articulaire naviculo-cuboïdien de la face plantaire, les autres doigts soutiennent la face dorsale du pied.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"Mobiliser le membre inférieur par plusieurs mouvements en piston jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"En fin de mouvement, porter le thrust en « snap » par les deux pouces en majorant la flexion plantaire et la pression sur l’interligne articulaire.","photo":"assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p106-dysfonction-de-la-naviculo-cuboidienne-articulaire-globale-a-droite/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":106,"sourceRow":135}},{"slug":"ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa","sourceRow":136,"sourceBook":"OSTPRA3","sourcePage":108,"matchers":["dysfonction de la metacarpo phalangienne de la 1re phalange en flexion dorsale a droite"],"title":"DYSFONCTION DE LA MÉTACARPO-PHALANGIENNE DE LA 1re PHALANGE, en flexion dorsale, à droite","zone":"Membres inférieurs","sub":"Pied","level":"Niveau intermédiaire","status":"non vue","icon":"P","video":"","headerImage":"assets/images/zones/zone-membres-inferieurs.webp","image":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/planche-photos.webp","text":"POSITION\nPATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout sur le côté du pied en dysfonction à la hauteur du pied du patient.\n\nPOSITION DES MAINS\nLa main céphalique empaume la face interne de l’avant-pied au niveau du premier rayon métatarsien en dysfonction. La pince pouce-index de la main caudale saisit la première phalange du gros orteil.\n\nBARRIÈRE MOTRICE\nLa main céphalique amène le premier métatarsien en pronation. La main caudale majore la flexion plantaire de la première phalange du gros orteil jusqu’à la barrière motrice.\n\nNORMALISATION\nPorter le thrust, par la main caudale, en flexion plantaire.","detail":{"source":"OSTPRA3 - page 108","category":"Membre inférieur – metatarso-phalangiennes","method":"Thrust","intro":"DYSFONCTION DE LA MÉTACARPO-PHALANGIENNE DE LA 1re PHALANGE, en flexion dorsale, à droite","steps":[{"key":"position","logoKey":"position","logo":"","label":"Position","title":"Patient et praticien","body":"PATIENT En décubitus dorsal, les pieds sont posés sur la table.\nPRATICIEN Debout sur le côté du pied en dysfonction à la hauteur du pied du patient.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/position.webp"},{"key":"mains","logoKey":"mains","logo":"","label":"Position des mains","title":"Contacts et prises","body":"La main céphalique empaume la face interne de l’avant-pied au niveau du premier rayon métatarsien en dysfonction. La pince pouce-index de la main caudale saisit la première phalange du gros orteil.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/mains.webp"},{"key":"barriere","logoKey":"barriere","logo":"","label":"Barrière motrice","title":"Mise en tension","body":"La main céphalique amène le premier métatarsien en pronation. La main caudale majore la flexion plantaire de la première phalange du gros orteil jusqu’à la barrière motrice.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/barriere.webp"},{"key":"normalisation","logoKey":"normalisation","logo":"","label":"Normalisation","title":"Geste de correction","body":"Porter le thrust, par la main caudale, en flexion plantaire.","photo":"assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/normalisation.webp"}],"images":["assets/images/techniques-officielles/ostpra3-p108-dysfonction-de-la-metacarpo-phalangienne-de-la-1re-phalange-en-flexion-dorsa/planche-photos.webp"],"official":true,"sourceBook":"OSTPRA3","sourcePage":108,"sourceRow":136}}]};
